# Complete quest catalogue from the supplied PalworldSaveTools 2.2.1 source.
# It is compressed to preserve this editor's single-file distribution.
_QUEST_DATA_ZLIB_B64 = (
    ""
)

def get_embedded_quest_data():
    data = zlib.decompress(base64.b64decode(_QUEST_DATA_ZLIB_B64))
    quests = json.loads(data.decode("utf-8")).get("quests", [])
    if len(quests) != 120:
        raise ValueError("The embedded quest catalogue failed validation.")
    return quests

# Technology catalogue extracted from the supplied PalworldSaveTools 2.2.1
# world.json. Only the fields used by this panel are retained.
_TECH_DATA_ZLIB_B64 = (
    ""
)

def get_embedded_technology_data():
    items = json.loads(
        zlib.decompress(base64.b64decode(_TECH_DATA_ZLIB_B64)).decode("utf-8")
    )
    if len(items) != 588:
        raise ValueError("The embedded technology catalogue failed validation.")
    return items

