def _make_index_entry(num, name, elem_codes, work_codes):
    subtitle = " / ".join(ELEMENT_NAMES[c] for c in elem_codes) if elem_codes else "Unknown"
    icon = ELEMENT_ICON[elem_codes[0]] if elem_codes else "\u2753"
    work = [(WORK_NAMES[c], lvl) for c, lvl in work_codes]
    hp, atk, df = BASE_STATS.get(num, ("\u2014", "\u2014", "\u2014"))
    partner = PARTNER_INFO.get(num)
    if partner:
        spawn_id, skill_name, blurb = partner
        passive_name = f"{skill_name} (Partner Skill)"
        passive_desc = blurb + " Active skill list for this pal hasn't been loaded yet."
    else:
        spawn_id = "\u2014"
        passive_name = "\u2014"
        passive_desc = ("Base stats are real (from a consolidated Paldeck listing) but "
                         "the spawn ID, partner skill, and active skill list for this "
                         "pal haven't been loaded from its individual page yet.")
    return {
        "num": num, "name": name, "subtitle": subtitle, "icon": icon,
        "spawn_id": spawn_id,
        "stats": [("HP", hp), ("Melee Attack", atk), ("Shot Atk", atk), ("Defense", df)],
        "extra": [("Rarity", "\u2014"), ("Work Speed", "\u2014"), ("Size", "\u2014"),
                  ("Capture Rate", "\u2014"), ("Lv.65 HP", "\u2014")],
        "work": work,
        "passive_name": passive_name,
        "passive_desc": passive_desc,
        "skills": [],
    }


def build_wiki_pals():
    detailed_by_num = {p["num"]: p for p in wiki_pals}
    pals = []
    for num, name, elem_codes, work_codes in WIKI_INDEX:
        if num in _DETAILED_NUMS and num in detailed_by_num:
            pals.append(detailed_by_num[num])
        else:
            pals.append(_make_index_entry(num, name, elem_codes, work_codes))
    return pals


wiki_pals = build_wiki_pals()


