def get_active_skill_name(skill_id):
    row = ACTIVE_SKILL_DATA.get(skill_id)
    return row[0] if row else skill_id


def get_passive_skill_name(skill_id):
    row = PASSIVE_SKILL_DATA.get(skill_id)
    return row[0] if row else skill_id


def get_pal_scaling(character_id):
    if not character_id:
        return None
    if character_id in PAL_SCALING_DATA:
        return PAL_SCALING_DATA[character_id]
    base = character_id
    for pfx in ("BOSS_", "PREDATOR_", "GYM_", "RAID_", "POLICE_", "SUMMON_", "QUEST_"):
        if base.upper().startswith(pfx):
            base = base[len(pfx):]
            break
    return PAL_SCALING_DATA.get(base)


def get_friendship_rank(trust_points):
    thresholds = [0, 6000, 13000, 21000, 30000, 40000, 55000, 80000, 110000, 150000, 200000]
    for rank in range(len(thresholds) - 1, 0, -1):
        if int(trust_points) >= thresholds[rank]:
            return rank
    return 0


def calculate_max_hp(scaling_row, level, talent_hp=0, rank_hp=0, friendship_pts=0,
                      condenser_rank=1, is_awake=False):
    if not scaling_row:
        return None
    hp_scaling = scaling_row[0]
    friendship_hp = scaling_row[4]
    friendship_rank = get_friendship_rank(friendship_pts)
    hp_iv = talent_hp * 0.3 / 100
    soul_bonus = rank_hp * 0.03
    condenser_bonus = max(0, condenser_rank - 1) * 0.05
    base = math.floor(500 + 5 * level + hp_scaling * 0.5 * level * (1 + hp_iv))
    base_with_condenser = math.floor(base * (1 + condenser_bonus))
    trust_bonus = int(level * friendship_rank * friendship_hp * 0.65 * (1 + condenser_bonus) + 0.5)
    awake_bonus = (math.floor(hp_scaling * level * 0.065 * (1 + condenser_bonus))
                   if hp_scaling and is_awake else 0)
    subtotal = base_with_condenser + trust_bonus + awake_bonus
    return math.floor(subtotal * (1 + soul_bonus)) * 1000


selected_wiki_num = wiki_pals[0]["num"]
docs_category = "pals"


def get_wiki_pal(num):
    return next((p for p in wiki_pals if p["num"] == num), None)


try:
    from wiki_items_data import WIKI_ITEMS_DATA
except ImportError:
    import importlib.util

    _wiki_candidates = (
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "wiki_items_data(1).py"),
        os.path.join(os.getcwd(), "wiki_items_data(1).py"),
    )
    WIKI_ITEMS_DATA = None
    for _wiki_path in _wiki_candidates:
        if not os.path.isfile(_wiki_path):
            continue
        _spec = importlib.util.spec_from_file_location("_palworld_wiki_items", _wiki_path)
        _module = importlib.util.module_from_spec(_spec)
        _spec.loader.exec_module(_module)
        WIKI_ITEMS_DATA = _module.WIKI_ITEMS_DATA
        break

    if WIKI_ITEMS_DATA is None:
        WIKI_ITEMS_DATA = [
            {"name": "Gold Coin", "slug": "Gold_Coin", "category": "Material", "icon": "\U0001F9F1",
             "tech_level": None,
             "recipe": {"station": "Gold Coin Assembly Line", "materials": {"Ingot": 30}},
             "obtained_from": ["Dropped by various enemies and merchants"], "notes": None,
             "game_id": "Money", "game_id_source": "built-in fallback"},
        ]

wiki_items = sorted(WIKI_ITEMS_DATA, key=lambda i: (i["category"], i["name"]))
selected_wiki_item_slug = wiki_items[0]["slug"] if wiki_items else None
item_category_filter = None  # None = show all categories


def get_wiki_item(slug):
    return next((i for i in wiki_items if i["slug"] == slug), None)


WIKI_ITEMS_BY_GAME_ID = {
    item["game_id"]: item
    for item in wiki_items
    if isinstance(item.get("game_id"), str) and item["game_id"].strip()
}

def _load_dynamic_item_metadata():
    candidates = [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "items.json"),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "items(2).json"),
        os.path.join(os.getcwd(), "items.json"),
        os.path.join(os.getcwd(), "items(2).json"),
    ]
    for path in candidates:
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
            dynamic = data.get("items_dynamic", {})
            icon_map = {}
            for item in data.get("items", []):
                if not isinstance(item, dict):
                    continue
                item_id = item.get("asset")
                icon_path = item.get("icon")
                if isinstance(item_id, str) and isinstance(icon_path, str) and icon_path:
                    icon_map[item_id] = os.path.basename(icon_path)
            if isinstance(dynamic, dict) and dynamic:
                return dynamic, path, icon_map
        except (OSError, ValueError, TypeError):
            continue
    return {}, None, {}


ITEMS_DYNAMIC, ITEMS_DYNAMIC_PATH, ITEM_ICON_FILES = _load_dynamic_item_metadata()


def get_dynamic_item_metadata(item_id):
    meta = ITEMS_DYNAMIC.get(item_id, {}) if isinstance(item_id, str) else {}
    dynamic = meta.get("dynamic", {}) if isinstance(meta, dict) else {}
    return dynamic if isinstance(dynamic, dict) else {}


def get_dynamic_item_type(item_id):
    return get_dynamic_item_metadata(item_id).get("type", "unknown")


def item_requires_dynamic_record(item):
    item_id = ""
    if isinstance(item, dict):
        item_id = (item.get("game_id") or item.get("asset") or "").strip()
    elif isinstance(item, str):
        item_id = item.strip()
    return get_dynamic_item_type(item_id) in {"weapon", "armor", "egg"}


def get_wiki_item_by_game_id(game_id):
    return WIKI_ITEMS_BY_GAME_ID.get(game_id)


SPAWN_ID_TO_PAL = {
    p["spawn_id"]: p for p in wiki_pals
    if p.get("spawn_id") and p["spawn_id"] != "\u2014"
}


MAGIC_ZLIB = b"PlZ"
MAGIC_OODLE = b"PlM"
MAGIC_CHUNKED = b"CNK"


class OodleError(Exception):
    pass


class OodleDecompressor:

    def __init__(self, lib_path):
        self.lib_path = lib_path
        self._lib = ctypes.CDLL(lib_path)
        fn = self._lib.OodleLZ_Decompress
        fn.restype = ctypes.c_int
        fn.argtypes = [
            ctypes.c_char_p, ctypes.c_size_t,   # compressed buffer, size
            ctypes.c_char_p, ctypes.c_size_t,   # output buffer, size
            ctypes.c_int, ctypes.c_int, ctypes.c_int,  # fuzzSafe, checkCRC, verbosity
            ctypes.c_void_p, ctypes.c_size_t,   # decBufBase, decBufSize
            ctypes.c_void_p, ctypes.c_void_p,   # fpCallback, callbackUserData
            ctypes.c_void_p, ctypes.c_size_t,   # decoderMemory, decoderMemorySize
            ctypes.c_int,                       # threadPhase
        ]
        self._decompress_fn = fn

    def decompress(self, compressed, out_size):
        out_buf = ctypes.create_string_buffer(out_size)
        written = self._decompress_fn(
            compressed, len(compressed),
            out_buf, out_size,
            1, 0, 0,
            None, 0,
            None, None,
            None, 0,
            3,
        )
        if written <= 0:
            raise OodleError("The Oodle library returned an error while decompressing.")
        return out_buf.raw[:written]


def decompress_sav(data, oodle=None):
    if len(data) < 12:
        raise ValueError("File is too small to be a Palworld save.")

    header_offset = 0
    magic = data[8:11]
    note = ""
    if magic == MAGIC_CHUNKED:
        header_offset = 12
        magic = data[header_offset + 8:header_offset + 11]
        note = "chunked (CNK) wrapper, "

    if len(data) < header_offset + 12:
        raise ValueError("File is too small to contain a full save header.")

    uncompressed_len, compressed_len = struct.unpack("<II", data[header_offset:header_offset + 8])
    save_type = data[header_offset + 11]
    payload_start = header_offset + 12
    payload = data[payload_start:payload_start + compressed_len] if compressed_len else data[payload_start:]

    if magic == MAGIC_OODLE:
        if oodle is None:
            raise ValueError(
                "This save is Oodle-compressed (magic \"PlM\"), not zlib. "
                "Oodle is a proprietary format with no pure-Python decoder. "
                "Click \"Locate Oodle Library\" in Tools and point it at the "
                "oo2core file from your Palworld install to add support."
            )
        try:
            return oodle.decompress(payload, uncompressed_len), f"{note}Oodle ({os.path.basename(oodle.lib_path)})"
        except OodleError as e:
            raise ValueError(f"Oodle decompression failed: {e}")

    if magic != MAGIC_ZLIB:
        found = magic.decode("latin-1", errors="replace")
        raise ValueError(
            f"Couldn't find the expected Palworld save header. Expected "
            f"{note}magic bytes \"PlZ\" but found {found!r} instead. This "
            f"may be a different file type, a corrupted save, or a save "
            f"format this template hasn't been updated for."
        )

    if save_type not in (0x31, 0x32):
        raise ValueError(f"Unrecognized compression type byte: 0x{save_type:02x} "
                          f"(expected 0x31 or 0x32).")

    try:
        step1 = zlib.decompress(payload)
    except zlib.error as e:
        raise ValueError(f"zlib decompression failed: {e}")

    if save_type == 0x32:
        try:
            return zlib.decompress(step1), f"{note}double zlib (save_type 0x32)"
        except zlib.error as e:
            raise ValueError(f"First zlib pass succeeded but the second "
                              f"(expected for save_type 0x32) failed: {e}")

    return step1, f"{note}single zlib (save_type 0x31)"


def compress_sav(gvas_bytes, save_type=0x31):
    if save_type == 0x32:
        compressed = zlib.compress(zlib.compress(gvas_bytes))
    else:
        compressed = zlib.compress(gvas_bytes)
    header = struct.pack("<II", len(gvas_bytes), len(compressed)) + MAGIC_ZLIB + bytes([save_type])
    return header + compressed


def scan_for_known_pals(gvas_bytes):
    text = gvas_bytes.decode("latin-1")  # 1 byte <-> 1 char, lossless for scanning
    counts = {}
    for spawn_id, pal in SPAWN_ID_TO_PAL.items():
        n = text.count(spawn_id)
        if n:
            counts[spawn_id] = (pal, n)
    return counts


import base64
import io


class GvasParseError(Exception):
    pass


def _read_fstring(r):
    length = struct.unpack("<i", r.read(4))[0]
    if length == 0:
        return ""
    if length < 0:
        n_chars = -length
        raw = r.read(n_chars * 2)
        return raw[:-2].decode("utf-16-le")
    raw = r.read(length)
    return raw[:-1].decode("utf-8", errors="replace")


def _write_fstring(w, s):
    # Some editor controls preserve a decoded Unreal value as a lightweight
    # wrapper (for example {"type": "None", "value": "Male"}). The GVAS
    # writer needs the wrapped scalar, not the wrapper object itself.
    unwrap_depth = 0
    while isinstance(s, dict) and unwrap_depth < 8:
        unwrap_depth += 1
        found = False
        for key in ("value", "_enum", "enum", "name", "text", "id"):
            if key in s and not isinstance(s[key], (list, tuple, bytes, bytearray)):
                s = s[key]
                found = True
                break
        if not found:
            raise ValueError(
                "FString field contains an unsupported object instead of text "
                f"(keys: {', '.join(map(str, s.keys()))})")
    if s is None:
        s = ""
    elif not isinstance(s, str):
        if isinstance(s, (int, float, bool, uuid.UUID)):
            s = str(s)
        else:
            raise ValueError(
                f"FString field contains {type(s).__name__} instead of text")
    if s == "":
        w.write(struct.pack("<i", 0))
        return
    try:
        encoded = s.encode("ascii") + b"\x00"
        w.write(struct.pack("<i", len(encoded)))
        w.write(encoded)
    except UnicodeEncodeError:
        encoded = s.encode("utf-16-le") + b"\x00\x00"
        w.write(struct.pack("<i", -(len(encoded) // 2)))
        w.write(encoded)


_BUILTIN_STRUCTS = {
    "Guid": 16, "Vector": 24, "Vector2D": 16, "Rotator": 24,
    "Quat": 32, "Color": 4, "LinearColor": 16, "DateTime": 8, "Timespan": 8,
}


def _read_property_value(r, prop_type, size, extra, name=None):
    start = r.tell()
    if prop_type in ("IntProperty", "UInt32Property"):
        value = struct.unpack("<i" if prop_type == "IntProperty" else "<I", r.read(4))[0]
    elif prop_type == "Int64Property":
        value = struct.unpack("<q", r.read(8))[0]
    elif prop_type in ("UInt16Property",):
        value = struct.unpack("<H", r.read(2))[0]
    elif prop_type in ("Int8Property", "ByteProperty") and extra.get("enum_name") in (None, "None"):
        value = r.read(1)[0]
    elif prop_type == "ByteProperty":
        value = _read_fstring(r)  # enum value, written as its name
    elif prop_type == "BoolProperty":
        value = bool(extra.get("bool_value", 0))
    elif prop_type == "FloatProperty":
        value = struct.unpack("<f", r.read(4))[0]
    elif prop_type == "DoubleProperty":
        value = struct.unpack("<d", r.read(8))[0]
    elif prop_type in ("StrProperty", "NameProperty"):
        value = _read_fstring(r)
    elif prop_type == "EnumProperty":
        value = _read_fstring(r)
    elif prop_type == "StructProperty":
        struct_name = extra.get("struct_name")
        if struct_name is None:
            raise GvasParseError("StructProperty with no known struct_name (nested in array/map)")
        if struct_name in _BUILTIN_STRUCTS:
            value = {"_struct": struct_name, "_raw_b64": base64.b64encode(r.read(size)).decode("ascii")}
        else:
            value = {"_struct": struct_name, "_fields": read_property_list(r)}
    elif prop_type == "ArrayProperty":
        inner_type = extra["inner_type"]
        count = struct.unpack("<i", r.read(4))[0]
        if inner_type == "StructProperty":
            inner_name = _read_fstring(r)
            inner_type2 = _read_fstring(r)
            arr_size = struct.unpack("<q", r.read(8))[0]
            sname = _read_fstring(r)
            inner_guid = r.read(16).hex()
            inner_term = r.read(1)[0]
            array_value_start = r.tell()
            items = []
            if sname in _BUILTIN_STRUCTS:
                elem_size = _BUILTIN_STRUCTS[sname]
                for _ in range(count):
                    items.append({"_struct": sname,
                                  "_raw_b64": base64.b64encode(r.read(elem_size)).decode("ascii")})
            else:
                for _ in range(count):
                    fields = read_property_list(r)
                    items.append({"_struct": sname, "_fields": fields})
            r.seek(array_value_start + arr_size)
            value = {
                "_array_struct": sname, "_items": items,
                "_inner_name": inner_name, "_inner_type": inner_type2,
                "_inner_guid": inner_guid, "_inner_terminator": inner_term,
            }
        else:
            items = []
            for _ in range(count):
                items.append(_read_property_value(r, inner_type, None, {}))
            if name == "RawData" and inner_type == "ByteProperty" and items:
                raw_bytes = bytes(items)
                try:
                    sub_reader = io.BytesIO(raw_bytes)
                    decoded = read_property_list(sub_reader)
                    trailing = sub_reader.read()
                    valid_properties = all(
                        entry.get("type") == "__RAW_TAIL__"
                        or (
                            bool(entry.get("name"))
                            and bool(entry.get("type"))
                            and all(ord(ch) >= 32 for ch in entry.get("name", ""))
                        )
                        for entry in decoded
                    )
                    if not valid_properties:
                        raise GvasParseError(
                            "RawData bytes only resembled a property list."
                        )
                    check = io.BytesIO()
                    write_property_list(check, decoded)
                    if check.getvalue() + trailing == raw_bytes:
                        value = {"_rawdata_decoded": decoded,
                                 "_rawdata_trailing_b64": base64.b64encode(trailing).decode("ascii")}
                    else:
                        value = {"_array": items}
                except Exception:
                    value = {"_array": items}
            else:
                value = {"_array": items}
    elif prop_type in ("MapProperty",):
        key_type = extra["key_type"]
        value_type = extra["value_type"]
        map_start = r.tell()
        r.read(4)  # map flags (usually 0)
        count = struct.unpack("<i", r.read(4))[0]
        pairs = []
        for _ in range(count):
            if key_type == "StructProperty":
                k = {"_map_struct_fields": read_property_list(r)}
            else:
                k = _read_property_value(r, key_type, None, {})
            if value_type == "StructProperty":
                v = {"_map_struct_fields": read_property_list(r)}
            else:
                v = _read_property_value(r, value_type, None, {})
            pairs.append([k, v])
        map_end = r.tell()
        value = {"_map": pairs, "_key_type": key_type, "_value_type": value_type}
        if key_type == "StructProperty" or value_type == "StructProperty":
            r.seek(map_start)
            original_span = r.read(map_end - map_start)
            check = io.BytesIO()
            check.write(struct.pack("<i", 0))
            check.write(struct.pack("<i", count))
            for k, v in pairs:
                if isinstance(k, dict) and "_map_struct_fields" in k:
                    write_property_list(check, k["_map_struct_fields"])
                else:
                    _write_property_value(check, key_type, k, {})
                if isinstance(v, dict) and "_map_struct_fields" in v:
                    write_property_list(check, v["_map_struct_fields"])
                else:
                    _write_property_value(check, value_type, v, {})
            if check.getvalue() != original_span:
                raise GvasParseError(f"MapProperty struct-key/value parse didn't "
                                      f"reproduce the original bytes for this map")
            r.seek(map_end)
    elif prop_type == "SetProperty":
        elem_type = extra["elem_type"]
        r.read(4)  # set flags
        count = struct.unpack("<i", r.read(4))[0]
        items = [_read_property_value(r, elem_type, None, {}) for _ in range(count)]
        value = {"_set": items}
    else:
        raise GvasParseError(f"no handler for {prop_type}")

    if size is not None:
        consumed = r.tell() - start
        if consumed != size:
            r.seek(start)
            return {"_raw_b64": base64.b64encode(r.read(size)).decode("ascii"), "_unparsed_type": prop_type}
    return value


def read_property_list(r):
    props = []
    while True:
        entry_start = r.tell()
        try:
            name = _read_fstring(r)
            if name == "None" or name == "":
                break
            prop_type = _read_fstring(r)
            size = struct.unpack("<q", r.read(8))[0]
            extra = {}
            if prop_type == "StructProperty":
                extra["struct_name"] = _read_fstring(r)
                r.read(16)  # struct guid
                r.read(1)   # terminator byte
            elif prop_type == "ArrayProperty":
                extra["inner_type"] = _read_fstring(r)
                r.read(1)
            elif prop_type == "MapProperty":
                extra["key_type"] = _read_fstring(r)
                extra["value_type"] = _read_fstring(r)
                r.read(1)
            elif prop_type == "SetProperty":
                extra["elem_type"] = _read_fstring(r)
                r.read(1)
            elif prop_type in ("ByteProperty", "EnumProperty"):
                extra["enum_name"] = _read_fstring(r)
                r.read(1)
            elif prop_type == "BoolProperty":
                extra["bool_value"] = r.read(1)[0]
                r.read(1)
            else:
                r.read(1)  # the generic 1-byte "has property guid" terminator
        except (struct.error, UnicodeDecodeError, IndexError, OverflowError, MemoryError):
            r.seek(entry_start)
            props.append({"name": "__RAW_TAIL__", "type": "__RAW_TAIL__", "extra": {},
                           "value": {"_raw_b64": base64.b64encode(r.read()).decode("ascii")}})
            return props

        value_start = r.tell()
        try:
            value = _read_property_value(r, prop_type, size, extra, name=name)
        except (GvasParseError, struct.error, UnicodeDecodeError, IndexError, KeyError, OverflowError):
            r.seek(value_start)
            value = {"_raw_b64": base64.b64encode(r.read(size)).decode("ascii"), "_unparsed_type": prop_type}
        props.append({"name": name, "type": prop_type, "extra": extra, "value": value})
    return props


def parse_gvas(data):
    r = io.BytesIO(data)
    magic = r.read(4)
    if magic != b"GVAS":
        raise GvasParseError(f"expected GVAS magic, found {magic!r}")
    header = {
        "save_game_version": struct.unpack("<i", r.read(4))[0],
        "package_version_ue4": struct.unpack("<i", r.read(4))[0],
        "package_version_ue5": struct.unpack("<i", r.read(4))[0],
        "engine_version_major": struct.unpack("<H", r.read(2))[0],
        "engine_version_minor": struct.unpack("<H", r.read(2))[0],
        "engine_version_patch": struct.unpack("<H", r.read(2))[0],
        "engine_version_changelist": struct.unpack("<I", r.read(4))[0],
        "engine_version_branch": _read_fstring(r),
        "custom_version_format": struct.unpack("<i", r.read(4))[0],
    }
    n_versions = struct.unpack("<i", r.read(4))[0]
    header["custom_versions"] = []
    for _ in range(n_versions):
        guid = r.read(16).hex()
        ver = struct.unpack("<i", r.read(4))[0]
        header["custom_versions"].append({"guid": guid, "version": ver})
    header["save_game_class_name"] = _read_fstring(r)

    properties = read_property_list(r)
    trailer = r.read()  # anything after the top-level property list (rare, kept as-is)
    return {
        "header": header,
        "properties": properties,
        "_trailer_b64": base64.b64encode(trailer).decode("ascii") if trailer else "",
    }


def sav_to_json_dict(gvas_bytes):
    try:
        return parse_gvas(gvas_bytes)
    except (GvasParseError, struct.error) as e:
        return {
            "_parse_error": str(e),
            "_raw_gvas_b64": base64.b64encode(gvas_bytes).decode("ascii"),
        }


def _write_property_value(w, prop_type, value, extra):
    if isinstance(value, dict) and "_raw_b64" in value and "_struct" not in value:
        w.write(base64.b64decode(value["_raw_b64"]))
        return
    if prop_type in ("IntProperty", "UInt32Property"):
        w.write(struct.pack("<i" if prop_type == "IntProperty" else "<I", value))
    elif prop_type == "Int64Property":
        w.write(struct.pack("<q", value))
    elif prop_type == "UInt16Property":
        w.write(struct.pack("<H", value))
    elif prop_type in ("Int8Property", "ByteProperty") and extra.get("enum_name") in (None, "None"):
        w.write(bytes([value & 0xFF]))
    elif prop_type == "ByteProperty":
        _write_fstring(w, value)
    elif prop_type == "BoolProperty":
        pass  # value lives in the tag's extra byte, not the value blob
    elif prop_type == "FloatProperty":
        w.write(struct.pack("<f", value))
    elif prop_type == "DoubleProperty":
        w.write(struct.pack("<d", value))
    elif prop_type in ("StrProperty", "NameProperty"):
        _write_fstring(w, value)
    elif prop_type == "EnumProperty":
        _write_fstring(w, value)
    elif prop_type == "StructProperty":
        if "_raw_b64" in value:
            w.write(base64.b64decode(value["_raw_b64"]))
        else:
            write_property_list(w, value["_fields"])
    elif prop_type == "ArrayProperty":
        inner_type = extra["inner_type"]
        if "_array_struct" in value:
            items = value["_items"]
            w.write(struct.pack("<i", len(items)))
            _write_fstring(w, value["_inner_name"])
            _write_fstring(w, value["_inner_type"])
            body = io.BytesIO()
            for item in items:
                if "_raw_b64" in item:
                    body.write(base64.b64decode(item["_raw_b64"]))
                else:
                    write_property_list(body, item["_fields"])
            body_bytes = body.getvalue()
            w.write(struct.pack("<q", len(body_bytes)))
            _write_fstring(w, value["_array_struct"])
            w.write(bytes.fromhex(value["_inner_guid"]))
            w.write(bytes([value["_inner_terminator"]]))
            w.write(body_bytes)
        else:
            if "_rawdata_decoded" in value:
                body = io.BytesIO()
                write_property_list(body, value["_rawdata_decoded"])
                body.write(base64.b64decode(value.get("_rawdata_trailing_b64", "")))
                items = list(body.getvalue())
            else:
                items = value["_array"]
            w.write(struct.pack("<i", len(items)))
            for item in items:
                _write_property_value(w, inner_type, item, {})
    elif prop_type == "MapProperty":
        pairs = value["_map"]
        key_type = value.get("_key_type", extra.get("key_type"))
        value_type = value.get("_value_type", extra.get("value_type"))
        w.write(struct.pack("<i", 0))  # map flags
        w.write(struct.pack("<i", len(pairs)))
        for k, v in pairs:
            if isinstance(k, dict) and "_map_struct_fields" in k:
                write_property_list(w, k["_map_struct_fields"])
            else:
                _write_property_value(w, key_type, k, {})
            if isinstance(v, dict) and "_map_struct_fields" in v:
                write_property_list(w, v["_map_struct_fields"])
            else:
                _write_property_value(w, value_type, v, {})
    elif prop_type == "SetProperty":
        items = value["_set"]
        elem_type = extra["elem_type"]
        w.write(struct.pack("<i", 0))  # set flags
        w.write(struct.pack("<i", len(items)))
        for item in items:
            _write_property_value(w, elem_type, item, {})
    else:
        raise GvasParseError(f"no writer for {prop_type}")


def write_property_list(w, props):
    for prop in props:
        if prop["type"] == "__RAW_TAIL__":
            w.write(base64.b64decode(prop["value"]["_raw_b64"]))
            return

        _write_fstring(w, prop["name"])
        _write_fstring(w, prop["type"])
        prop_type = prop["type"]
        extra = prop.get("extra", {})
        value = prop["value"]

        is_raw_fallback = (isinstance(value, dict) and "_raw_b64" in value
                            and "_struct" not in value and "_unparsed_type" in value)

        body = io.BytesIO()
        if is_raw_fallback:
            body.write(base64.b64decode(value["_raw_b64"]))
        else:
            _write_property_value(body, prop_type, value, extra)
        body_bytes = body.getvalue()

        w.write(struct.pack("<q", len(body_bytes)))
        if prop_type == "StructProperty":
            _write_fstring(w, extra["struct_name"])
            w.write(b"\x00" * 16)
            w.write(b"\x00")
        elif prop_type == "ArrayProperty":
            _write_fstring(w, extra["inner_type"])
            w.write(b"\x00")
        elif prop_type == "MapProperty":
            _write_fstring(w, extra["key_type"])
            _write_fstring(w, extra["value_type"])
            w.write(b"\x00")
        elif prop_type == "SetProperty":
            _write_fstring(w, extra["elem_type"])
            w.write(b"\x00")
        elif prop_type == "ByteProperty":
            _write_fstring(w, extra.get("enum_name", "None"))
            w.write(b"\x00")
        elif prop_type == "EnumProperty":
            _write_fstring(w, extra.get("enum_name", "None"))
            w.write(b"\x00")
        elif prop_type == "BoolProperty":
            w.write(bytes([extra.get("bool_value", 0)]))
            w.write(b"\x00")
        else:
            w.write(b"\x00")
        w.write(body_bytes)
    _write_fstring(w, "None")


def build_gvas(obj):
    if "_raw_gvas_b64" in obj:
        return base64.b64decode(obj["_raw_gvas_b64"])

    w = io.BytesIO()
    w.write(b"GVAS")
    h = obj["header"]
    w.write(struct.pack("<i", h["save_game_version"]))
    w.write(struct.pack("<i", h["package_version_ue4"]))
    w.write(struct.pack("<i", h["package_version_ue5"]))
    w.write(struct.pack("<H", h["engine_version_major"]))
    w.write(struct.pack("<H", h["engine_version_minor"]))
    w.write(struct.pack("<H", h["engine_version_patch"]))
    w.write(struct.pack("<I", h["engine_version_changelist"]))
    _write_fstring(w, h["engine_version_branch"])
    w.write(struct.pack("<i", h["custom_version_format"]))
    w.write(struct.pack("<i", len(h["custom_versions"])))
    for cv in h["custom_versions"]:
        w.write(bytes.fromhex(cv["guid"]))
        w.write(struct.pack("<i", cv["version"]))
    _write_fstring(w, h["save_game_class_name"])

    write_property_list(w, obj["properties"])
    if obj.get("_trailer_b64"):
        w.write(base64.b64decode(obj["_trailer_b64"]))
    return w.getvalue()


def json_dict_to_gvas_bytes(obj):
    try:
        return build_gvas(obj)
    except (GvasParseError, KeyError, struct.error, ValueError) as e:
        raise ValueError(f"Couldn't rebuild save data from this JSON: {e}")


def _find_field(fields, name):
    return next((f for f in fields if f["name"] == name), None)


def character_id_display(character_id):
    pal = SPAWN_ID_TO_PAL.get(character_id)
    if pal:
        return pal["icon"], pal["name"]
    for prefix, suffix in (("BOSS_", " (Boss)"), ("GYM_", " (Gym Boss)")):
        if character_id.startswith(prefix):
            base = character_id[len(prefix):].rstrip("_0123456789")
            pal = SPAWN_ID_TO_PAL.get(base) or SPAWN_ID_TO_PAL.get(character_id[len(prefix):])
            if pal:
                return pal["icon"], pal["name"] + suffix
    return "\u2754", character_id or "Unknown"


def build_pal_entries_from_json(loaded_json):
    entries_out = []
    field_refs = {}
    if not isinstance(loaded_json, dict) or "_parse_error" in loaded_json or "_raw_gvas_b64" in loaded_json:
        return entries_out, field_refs
    world = next((p for p in loaded_json.get("properties", []) if p["name"] == "worldSaveData"), None)
    if not world or not isinstance(world.get("value"), dict) or "_fields" not in world["value"]:
        return entries_out, field_refs
    csm = next((f for f in world["value"]["_fields"] if f["name"] == "CharacterSaveParameterMap"), None)
    if not csm or not isinstance(csm.get("value"), dict) or "_map" not in csm["value"]:
        return entries_out, field_refs

    next_local_id = 1
    for key, val in csm["value"]["_map"]:
        key_fields = key.get("_map_struct_fields", []) if isinstance(key, dict) else []
        val_fields = val.get("_map_struct_fields", []) if isinstance(val, dict) else []
        rawdata_field = _find_field(val_fields, "RawData")
        if not rawdata_field or not isinstance(rawdata_field["value"], dict):
            continue
        rd_value = rawdata_field["value"]
        if "_rawdata_decoded" not in rd_value:
            continue  # this entry's data wasn't decodable -- not editable here, safely skipped
        sp = next((p for p in rd_value["_rawdata_decoded"] if p["name"] == "SaveParameter"), None)
        if not sp or not isinstance(sp.get("value"), dict) or "_fields" not in sp["value"]:
            continue
        pal_fields = sp["value"]["_fields"]

        def gv(name, default=None):
            f = _find_field(pal_fields, name)
            return f["value"] if f is not None and not isinstance(f["value"], dict) else default

        character_id = gv("CharacterID", "") or ""
        icon, species_name = character_id_display(character_id)
        nickname = gv("NickName", "") or ""
        level = gv("Level", 1)
        level = int(level) if isinstance(level, int) else 1
        debug_name_field = _find_field(key_fields, "DebugName")
        debug_name = debug_name_field["value"] if debug_name_field else ""

        entry_id = next_local_id
        next_local_id += 1
        slot_id_field = _find_field(pal_fields, "SlotId")
        container_id, slot_index = None, None
        if slot_id_field and isinstance(slot_id_field["value"], dict):
            slot_id_fields = slot_id_field["value"].get("_fields", [])
            container_field = _find_field(slot_id_fields, "ContainerId")
            if container_field and isinstance(container_field["value"], dict):
                id_field = _find_field(container_field["value"].get("_fields", []), "ID")
                if id_field and isinstance(id_field["value"], str):
                    container_id = id_field["value"]
                elif id_field and isinstance(id_field["value"], dict):
                    container_id = id_field["value"].get("_raw_b64") or None
            slot_index_field = _find_field(slot_id_fields, "SlotIndex")
            if slot_index_field is not None and not isinstance(slot_index_field["value"], dict):
                slot_index = slot_index_field["value"]
        entries_out.append({
            "id": entry_id,
            "name": nickname or species_name or debug_name or "Unnamed",
            "icon": icon,
            "level": level,
            "max_level": 255,
            "locked": False,
            "starred": character_id.startswith(("BOSS_", "GYM_")),
            "is_real_pal": True,
            "character_id": character_id,
            "species_name": species_name,
            "nickname": nickname,
            "gender": gv("Gender", "") or "",
            "exp": gv("Exp", 0) or 0,
            "rank": gv("Rank", 0) or 0,
            "talent_hp": gv("Talent_HP", 0) or 0,
            "talent_shot": gv("Talent_Shot", 0) or 0,
            "talent_defense": gv("Talent_Defense", 0) or 0,
            "rank_hp": gv("Rank_HP", 0) or 0,
            "rank_attack": gv("Rank_Attack", 0) or 0,
            "rank_defence": gv("Rank_Defence", 0) or 0,
            "rank_craftspeed": gv("Rank_CraftSpeed", 0) or 0,
            "container_id": container_id,
            "slot_index": slot_index,
        })
        field_refs[entry_id] = pal_fields
    return entries_out, field_refs


def find_palbox_container_id(loaded_json):
    if not isinstance(loaded_json, dict):
        return None
    world = next((p for p in loaded_json.get("properties", []) if p["name"] == "worldSaveData"), None)
    if not world or not isinstance(world.get("value"), dict):
        return None
    ccs = next((f for f in world["value"].get("_fields", []) if f["name"] == "CharacterContainerSaveData"), None)
    if not ccs or not isinstance(ccs.get("value"), dict) or "_map" not in ccs["value"]:
        return None
    for key, val in ccs["value"]["_map"]:
        val_fields = val.get("_map_struct_fields", []) if isinstance(val, dict) else []
        slotnum_field = _find_field(val_fields, "SlotNum")
        if slotnum_field and slotnum_field["value"] == 960:
            key_fields = key.get("_map_struct_fields", []) if isinstance(key, dict) else []
            id_field = _find_field(key_fields, "ID")
            if id_field and isinstance(id_field["value"], dict):
                return id_field["value"].get("_raw_b64")
            if isinstance(key, str):
                return key
    return None


def find_party_container_ids(loaded_json):
    ids = set()
    if not isinstance(loaded_json, dict):
        return ids
    world = next((p for p in loaded_json.get("properties", []) if p["name"] == "worldSaveData"), None)
    if not world or not isinstance(world.get("value"), dict):
        return ids
    ccs = next((f for f in world["value"].get("_fields", []) if f["name"] == "CharacterContainerSaveData"), None)
    if not ccs or not isinstance(ccs.get("value"), dict) or "_map" not in ccs["value"]:
        return ids
    for key, val in ccs["value"]["_map"]:
        val_fields = val.get("_map_struct_fields", []) if isinstance(val, dict) else []
        slotnum_field = _find_field(val_fields, "SlotNum")
        if slotnum_field and slotnum_field["value"] in (5, 6):
            key_fields = key.get("_map_struct_fields", []) if isinstance(key, dict) else []
            id_field = _find_field(key_fields, "ID")
            cid = None
            if id_field and isinstance(id_field["value"], dict):
                cid = id_field["value"].get("_raw_b64")
            elif isinstance(key, str):
                cid = key
            if cid:
                ids.add(cid)
    return ids


def _rd_guid(r):
    return r.read(16).hex()


def _new_palworld_guid_bytes():
    """Create a UUID4 in Palworld/Unreal FGuid byte order.

    PalworldSaveTools serializes an FGuid as four little-endian uint32 blocks,
    which is different from both uuid.UUID.bytes and uuid.UUID.bytes_le.
    """
    value = uuid.uuid4().bytes
    return b"".join(
        value[offset:offset + 4][::-1] for offset in range(0, 16, 4))


def _rd_i32(r):
    return struct.unpack("<i", r.read(4))[0]


def _rd_i64(r):
    return struct.unpack("<q", r.read(8))[0]


def _rd_byte(r):
    return r.read(1)[0]


def _rd_float(r):
    return struct.unpack("<f", r.read(4))[0]


def _rd_double(r):
    return struct.unpack("<d", r.read(8))[0]


def _decode_guid_keyed_struct_map(raw_bytes):
    r = io.BytesIO(raw_bytes)
    r.read(4)  # map flags
    count = struct.unpack("<i", r.read(4))[0]
    pairs = []
    for _ in range(count):
        key_guid = r.read(16).hex()
        fields = read_property_list(r)
        pairs.append((key_guid, fields))
    return pairs


def _rawdata_bytes(fields, name="RawData"):
    f = _find_field(fields, name)
    if not f or not isinstance(f["value"], dict):
        return None
    v = f["value"]
    if "_array" in v:
        return bytes(v["_array"])
    if "_rawdata_decoded" in v:
        decoded = v["_rawdata_decoded"]
        trailing = base64.b64decode(v.get("_rawdata_trailing_b64", "") or "")
        if len(decoded) == 1 and decoded[0]["type"] == "__RAW_TAIL__":
            return base64.b64decode(decoded[0]["value"]["_raw_b64"]) + trailing
        body = io.BytesIO()
        write_property_list(body, decoded)
        return body.getvalue() + trailing
    return None


def decode_base_camp_raw(raw):
    fallback = None
    for precision, rd in (("double", _rd_double), ("float", _rd_float)):
        r = io.BytesIO(raw)
        try:
            base_id = _rd_guid(r)
            name = _read_fstring(r)
            state = _rd_byte(r)
            rd(r), rd(r), rd(r), rd(r)  # rotation quaternion (unused)
            loc = [rd(r) for _ in range(3)]
            rd(r), rd(r), rd(r)  # scale (unused)
            area_range = _rd_float(r)
            group_id = _rd_guid(r)
            rd(r), rd(r), rd(r), rd(r)  # fast-travel rotation (unused)
            rd(r), rd(r), rd(r)  # fast-travel translation (unused)
            rd(r), rd(r), rd(r)  # fast-travel scale (unused)
            owner_map_object_id = _rd_guid(r)
            r.read(4)  # trailing bytes
            result = {
                "id": base_id, "name": name, "state": state,
                "x": loc[0], "y": loc[1], "z": loc[2],
                "area_range": area_range, "group_id": group_id,
                "owner_map_object_id": owner_map_object_id,
            }
            if r.tell() == len(raw):
                return result
            fallback = fallback or result
        except Exception:
            continue
    return fallback


def decode_group_raw(raw, group_type):
    r = io.BytesIO(raw)
    group_id = _rd_guid(r)
    group_name = _read_fstring(r)
    char_count = _rd_i32(r)
    for _ in range(char_count):
        r.read(32)  # per-character instance id pair (world id + local id)
    result = {"group_id": group_id, "group_name": group_name, "group_type": group_type,
              "base_ids": [], "base_camp_level": 0, "guild_name": None, "players": []}
    if group_type in ("EPalGroupType::Guild", "EPalGroupType::IndependentGuild",
                       "EPalGroupType::Organization"):
        _rd_byte(r)  # org_type
    if group_type == "EPalGroupType::Organization":
        r.read(12)
    elif group_type == "EPalGroupType::Guild":
        r.read(4)
        base_count = _rd_i32(r)
        base_ids = [_rd_guid(r) for _ in range(base_count)]
        _rd_i32(r)  # unknown
        base_camp_level = _rd_i32(r)
        bcp_count = _rd_i32(r)
        for _ in range(bcp_count):
            _rd_guid(r)
        guild_name = _read_fstring(r)
        _rd_guid(r)  # last name-modifier player uid
        marker_count = _rd_i32(r)
        for _ in range(marker_count):
            r.read(16 + 24 + 4 + 16)  # marker id, location, icon type, owner

        start = r.tell()
        players = []
        try:
            allowed_roles_count = _rd_i32(r)
            r.read(allowed_roles_count)
            _rd_i32(r)  # unknown
            admin_uid = _rd_guid(r)
            player_count = _rd_i32(r)
            tmp_players = []
            for _ in range(player_count):
                tmp_players.append({
                    "uid": _rd_guid(r), "last_online": _rd_i64(r),
                    "name": _read_fstring(r), "role": _rd_byte(r),
                })
            perm_count = _rd_i32(r)
            for _ in range(perm_count):
                _rd_byte(r)
                pc = _rd_i32(r)
                r.read(pc)
            r.read(4)
            if r.tell() != len(raw):
                raise ValueError("mismatched length for post-update layout")
            players = tmp_players
        except Exception:
            r.seek(start)
            admin_uid = _rd_guid(r)
            player_count = _rd_i32(r)
            for _ in range(player_count):
                players.append({
                    "uid": _rd_guid(r), "last_online": _rd_i64(r), "name": _read_fstring(r),
                })
        result.update({"base_ids": base_ids, "base_camp_level": base_camp_level,
                        "guild_name": guild_name, "players": players, "admin_uid": admin_uid})
    elif group_type == "EPalGroupType::IndependentGuild":
        base_camp_level = _rd_i32(r)
        bcp_count = _rd_i32(r)
        for _ in range(bcp_count):
            _rd_guid(r)
        guild_name = _read_fstring(r)
        player_uid = _rd_guid(r)
        _read_fstring(r)  # duplicate guild name
        _rd_i64(r)  # last online
        player_name = _read_fstring(r)
        result.update({"base_camp_level": base_camp_level, "guild_name": guild_name,
                        "players": [{"uid": player_uid, "name": player_name}]})
    return result


def build_map_entries_from_json(loaded_json):
    result = {"players": [], "bases": [], "guilds": [],
              "bases_available": False, "guilds_available": False}
    if not isinstance(loaded_json, dict) or "_parse_error" in loaded_json or "_raw_gvas_b64" in loaded_json:
        return result
    world = next((p for p in loaded_json.get("properties", []) if p["name"] == "worldSaveData"), None)
    if not world or not isinstance(world.get("value"), dict) or "_fields" not in world["value"]:
        return result
    wfields = world["value"]["_fields"]

    csm = next((f for f in wfields if f["name"] == "CharacterSaveParameterMap"), None)
    if csm and isinstance(csm.get("value"), dict) and "_map" in csm["value"]:
        for key, val in csm["value"]["_map"]:
            key_fields = key.get("_map_struct_fields", []) if isinstance(key, dict) else []
            val_fields = val.get("_map_struct_fields", []) if isinstance(val, dict) else []
            rawdata_field = _find_field(val_fields, "RawData")
            if not rawdata_field or not isinstance(rawdata_field["value"], dict):
                continue
            rd_value = rawdata_field["value"]
            if "_rawdata_decoded" not in rd_value:
                continue
            sp = next((p for p in rd_value["_rawdata_decoded"] if p["name"] == "SaveParameter"), None)
            if not sp or not isinstance(sp.get("value"), dict) or "_fields" not in sp["value"]:
                continue
            pfields = sp["value"]["_fields"]

            def gv(name, default=None, _pf=pfields):
                f = _find_field(_pf, name)
                return f["value"] if f is not None and not isinstance(f["value"], dict) else default

            if not gv("IsPlayer", False):
                continue
            player_uid_field = _find_field(key_fields, "PlayerUId")
            player_uid_raw = player_uid_field["value"] if player_uid_field else None
            player_uid = None
            if isinstance(player_uid_raw, dict) and "_raw_b64" in player_uid_raw:
                try:
                    uid_bytes = base64.b64decode(player_uid_raw["_raw_b64"])
                    # Palworld serialises GUIDs in four little-endian 32-bit groups.
                    # A plain .hex() produces a different value from the filename
                    # used in Players\<UID>.sav, especially for the host UID.
                    player_uid = _guid_from_pal_bytes(uid_bytes) or uid_bytes.hex()
                except Exception:
                    player_uid = player_uid_raw.get("_raw_b64")
            elif isinstance(player_uid_raw, str):
                player_uid = player_uid_raw
            debug_name_field = _find_field(key_fields, "DebugName")
            debug_name = debug_name_field["value"] if debug_name_field else ""
            result["players"].append({
                "uid": player_uid,
                "name": gv("NickName", "") or debug_name or "Unnamed Survivor",
                "level": gv("Level", 1) or 1,
                "guild": None,  # filled in below once guilds are decoded
                "x": None, "y": None,  # no world-position field in SaveParameter itself
            })

    bcs = next((f for f in wfields if f["name"] == "BaseCampSaveData"), None)
    bases_by_id = {}
    if bcs and isinstance(bcs.get("value"), dict) and "_raw_b64" in bcs["value"]:
        try:
            raw = base64.b64decode(bcs["value"]["_raw_b64"])
            for base_id, fields in _decode_guid_keyed_struct_map(raw):
                rd = _rawdata_bytes(fields)
                decoded = decode_base_camp_raw(rd) if rd else None
                if decoded:
                    bases_by_id[base_id] = decoded
            result["bases_available"] = True
        except Exception:
            pass  # leave bases_available False; the UI explains why

    gsm = next((f for f in wfields if f["name"] == "GroupSaveDataMap"), None)
    if gsm and isinstance(gsm.get("value"), dict) and "_raw_b64" in gsm["value"]:
        try:
            raw = base64.b64decode(gsm["value"]["_raw_b64"])
            uid_to_player = {p["uid"]: p for p in result["players"] if p.get("uid")}
            for group_id, fields in _decode_guid_keyed_struct_map(raw):
                gt_field = _find_field(fields, "GroupType")
                group_type = gt_field["value"] if gt_field else None
                if group_type != "EPalGroupType::Guild":
                    continue  # skip Organization/wild-pal-pack groups for the map view
                rd = _rawdata_bytes(fields)
                decoded = decode_group_raw(rd, group_type) if rd else None
                if not decoded:
                    continue
                guild_bases = [bases_by_id[b] for b in decoded["base_ids"] if b in bases_by_id]
                gx = guild_bases[0]["x"] if guild_bases else None
                gy = guild_bases[0]["y"] if guild_bases else None
                leader_name = None
                for p in decoded["players"]:
                    match = uid_to_player.get(p["uid"])
                    if match:
                        match["guild"] = decoded["guild_name"] or "Unnamed Guild"
                    if p["uid"] == decoded.get("admin_uid"):
                        leader_name = p.get("name")
                result["guilds"].append({
                    "id": group_id,
                    "name": decoded["guild_name"] or "Unnamed Guild",
                    "level": decoded.get("base_camp_level", 1) or 1,
                    "leader": leader_name or (decoded["players"][0]["name"] if decoded["players"] else "\u2014"),
                    "base_count": len(decoded["base_ids"]),
                    "player_count": len(decoded["players"]),
                    "x": gx, "y": gy,
                })
                for b in guild_bases:
                    result["bases"].append({
                        "id": b["id"], "name": b["name"] or "Base Camp",
                        "guild": decoded["guild_name"] or "Unnamed Guild",
                        "x": b["x"], "y": b["y"],
                    })
            result["guilds_available"] = True
        except Exception:
            pass  # leave guilds_available False; the UI explains why

    return result


_BASE_STRUCTURE_NAMES = {
    "WorkBench_SkillUnlock": "Pal Gear Workbench",
    "Workbench": "Workbench",
    "WorkBench": "Workbench",
    "PalFoodBox": "Feed Box",
    "CampFire": "Campfire",
    "GuildChest": "Guild Chest",
}


def _base_structure_display_name(map_object_id):
    if map_object_id in _BASE_STRUCTURE_NAMES:
        return _BASE_STRUCTURE_NAMES[map_object_id]
    text = str(map_object_id or "Storage").replace("BP_", "").replace("_C", "")
    text = text.replace("_", " ")
    text = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", text)
    return " ".join(text.split()).strip() or "Storage"


def build_base_container_catalog(loaded_json):
    """Return save-owned storage containers keyed by their raw base GUID."""
    result = {}
    if not isinstance(loaded_json, dict):
        return result
    world = next(
        (p for p in loaded_json.get("properties", []) if p.get("name") == "worldSaveData"),
        None,
    )
    if not world or not isinstance(world.get("value"), dict):
        return result
    wfields = world["value"].get("_fields", [])
    map_objects = _find_field(wfields, "MapObjectSaveData")
    items = (
        map_objects.get("value", {}).get("_items", [])
        if isinstance(map_objects, dict) else []
    )
    for item in items:
        fields = item.get("_fields", []) if isinstance(item, dict) else []
        object_id_field = _find_field(fields, "MapObjectId")
        object_id = object_id_field.get("value") if object_id_field else ""
        model_field = _find_field(fields, "Model")
        model_fields = (
            model_field.get("value", {}).get("_fields", [])
            if model_field and isinstance(model_field.get("value"), dict) else []
        )
        model_raw = _rawdata_bytes(model_fields)
        if not model_raw or len(model_raw) < 48:
            continue
        base_id = model_raw[32:48].hex()
        if not base_id or base_id == "0" * 32:
            continue
        concrete_field = _find_field(fields, "ConcreteModel")
        concrete_fields = (
            concrete_field.get("value", {}).get("_fields", [])
            if concrete_field and isinstance(concrete_field.get("value"), dict) else []
        )
        module_map_field = _find_field(concrete_fields, "ModuleMap")
        module_map = (
            module_map_field.get("value", {}).get("_map", [])
            if module_map_field and isinstance(module_map_field.get("value"), dict) else []
        )
        container_id = None
        for module_key, module_value in module_map:
            key_text = str(module_key)
            if isinstance(module_key, dict):
                key_text = str(
                    module_key.get("_enum")
                    or module_key.get("value")
                    or module_key
                )
            if "ItemContainer" not in key_text:
                continue
            module_fields = (
                module_value.get("_map_struct_fields", [])
                if isinstance(module_value, dict) else []
            )
            module_raw = _rawdata_bytes(module_fields)
            if module_raw and len(module_raw) >= 16:
                container_id = module_raw[:16].hex()
                break
        if container_id:
            result.setdefault(base_id, []).append({
                "container_id": container_id,
                "object_id": str(object_id or ""),
                "name": _base_structure_display_name(object_id),
            })

    guild_extra = _find_field(wfields, "GuildExtraSaveDataMap")
    if guild_extra and isinstance(guild_extra.get("value"), dict):
        encoded = guild_extra["value"].get("_raw_b64")
        if encoded:
            try:
                for guild_id, fields in _decode_guid_keyed_struct_map(base64.b64decode(encoded)):
                    storage = _find_field(fields, "GuildItemStorage")
                    storage_fields = (
                        storage.get("value", {}).get("_fields", [])
                        if storage and isinstance(storage.get("value"), dict) else []
                    )
                    raw = _rawdata_bytes(storage_fields)
                    if raw and len(raw) >= 16:
                        result.setdefault(("guild", guild_id), []).append({
                            "container_id": raw[:16].hex(),
                            "object_id": "GuildChest",
                            "name": "Guild Chest",
                        })
            except Exception:
                pass
    return result


def decode_item_slot_bytes(raw):
    if len(raw) < 12:
        return None
    marker, count, id_len = struct.unpack("<iii", raw[0:12])
    if id_len <= 0 or 12 + id_len > len(raw):
        return None
    item_id = raw[12:12 + id_len - 1].decode("utf-8", errors="replace")
    tail = raw[12 + id_len:]
    return {"marker": marker, "count": count, "item_id": item_id, "tail_b64": base64.b64encode(tail).decode("ascii")}


def encode_item_slot_bytes(decoded):
    id_bytes = decoded["item_id"].encode("utf-8") + b"\x00"
    tail = base64.b64decode(decoded["tail_b64"])
    return struct.pack("<iii", decoded["marker"], decoded["count"], len(id_bytes)) + id_bytes + tail


_ZERO_GUID_BYTES = b"\x00" * 16

_ITEM_SLOT_CUSTOM_VERSION = [
    2, 0, 0, 0, 126, 180, 234, 18, 154, 27, 90, 255,
    113, 170, 113, 188, 223, 51, 214, 14, 1, 0, 0, 0,
    56, 11, 0, 222, 73, 73, 215, 206, 151, 223, 45, 153,
    192, 193, 195, 105, 1, 0, 0, 0,
]
_DYNAMIC_CUSTOM_VERSION = [1, 0, 0, 0, 56, 11, 0, 222, 73, 73, 215, 206,
                           151, 223, 45, 153, 192, 193, 195, 105, 1, 0, 0, 0]
_EGG_CUSTOM_VERSION = [2, 0, 0, 0, 56, 11, 0, 222, 73, 73, 215, 206,
                       151, 223, 45, 153, 192, 193, 195, 105, 1, 0, 0, 0,
                       108, 246, 252, 15, 153, 72, 144, 17, 248, 156, 96,
                       177, 94, 71, 70, 74, 1, 0, 0, 0]


def _guid_to_pal_bytes(value):
    u = value if isinstance(value, uuid.UUID) else uuid.UUID(str(value))
    b = u.bytes
    return bytes((b[3], b[2], b[1], b[0], b[7], b[6], b[5], b[4],
                  b[11], b[10], b[9], b[8], b[15], b[14], b[13], b[12]))


def _guid_from_pal_bytes(raw):
    if not raw or len(raw) != 16 or raw == _ZERO_GUID_BYTES:
        return None
    b = bytes((raw[3], raw[2], raw[1], raw[0], raw[7], raw[6], raw[5], raw[4],
               raw[11], raw[10], raw[9], raw[8], raw[15], raw[14], raw[13], raw[12]))
    return str(uuid.UUID(bytes=b))


def _pack_fstring(text):
    encoded = str(text).encode("utf-8") + b"\x00"
    return struct.pack("<i", len(encoded)) + encoded


def _dynamic_id_from_slot_bytes(raw):
    decoded = decode_item_slot_bytes(raw) if raw else None
    if not decoded:
        return None
    tail = base64.b64decode(decoded.get("tail_b64", ""))
    return _guid_from_pal_bytes(tail[16:32]) if len(tail) >= 32 else None


def _build_slot_tail(dynamic_id=None, old_tail=None):
    old_tail = bytes(old_tail or b"")
    trailing = old_tail[32:] if len(old_tail) >= 32 else b"\x00" * 20
    if len(trailing) < 20:
        trailing += b"\x00" * (20 - len(trailing))
    trailing = trailing[:20]
    local = _guid_to_pal_bytes(dynamic_id) if dynamic_id else _ZERO_GUID_BYTES
    return _ZERO_GUID_BYTES + local + trailing


def _encode_dynamic_raw(item_id, dynamic_id, item_type, durability):
    out = bytearray()
    out += _ZERO_GUID_BYTES
    out += _guid_to_pal_bytes(dynamic_id)
    out += _pack_fstring(item_id)
    if item_type == "weapon":
        out += b"\x00" * 4
        out += struct.pack("<f", float(durability))
        out += struct.pack("<i", 0)  # remaining bullets
        out += struct.pack("<I", 0)  # passive skill count
        out += b"\x00" * 4
    elif item_type == "armor":
        out += b"\x00" * 4
        out += struct.pack("<f", float(durability))
        out += b"\x00" * 4
    elif item_type == "egg":
        out += b"\x00" * 4
        out += _pack_fstring("")
        out += _pack_fstring("None")
        out += b"\x00" * 28
    else:
        raise ValueError(f"Unsupported dynamic item type: {item_type}")
    return bytes(out)


def _find_world_field(loaded_json, field_name):
    if not isinstance(loaded_json, dict):
        return None
    world = next((p for p in loaded_json.get("properties", []) if p.get("name") == "worldSaveData"), None)
    fields = world.get("value", {}).get("_fields", []) if world else []
    return next((f for f in fields if f.get("name") == field_name), None)


def _dynamic_items_array(loaded_json):
    field = _find_world_field(loaded_json, "DynamicItemSaveData")
    value = field.get("value", {}) if field else {}
    return value.get("_items") if isinstance(value.get("_items"), list) else None


def _dynamic_record_id(record):
    try:
        fields = record.get("_fields", [])
        raw_field = next(f for f in fields if f.get("name") == "RawData")
        raw = bytes(raw_field.get("value", {}).get("_array", []))
        if len(raw) < 32:
            return None
        return _guid_from_pal_bytes(raw[16:32])
    except (StopIteration, TypeError, ValueError):
        return None


def _remove_dynamic_record(loaded_json, dynamic_id):
    if not dynamic_id:
        return False
    items = _dynamic_items_array(loaded_json)
    if items is None:
        return False
    target = str(dynamic_id).lower()
    before = len(items)
    items[:] = [r for r in items if (_dynamic_record_id(r) or "").lower() != target]
    return len(items) != before


def _append_dynamic_record(loaded_json, item_id, dynamic_id):
    items = _dynamic_items_array(loaded_json)
    if items is None:
        raise ValueError("DynamicItemSaveData is missing or could not be parsed.")
    dynamic = get_dynamic_item_metadata(item_id)
    item_type = dynamic.get("type", "unknown")
    if item_type not in {"weapon", "armor", "egg"}:
        raise ValueError(f"{item_id} is not marked as a supported dynamic item.")
    durability = float(dynamic.get("durability", 100.0))
    raw = _encode_dynamic_raw(item_id, dynamic_id, item_type, durability)
    custom = _EGG_CUSTOM_VERSION if item_type == "egg" else _DYNAMIC_CUSTOM_VERSION
    items.append({
        "_struct": "PalDynamicItemSaveData",
        "_fields": [
            {"name": "RawData", "type": "ArrayProperty",
             "extra": {"inner_type": "ByteProperty"},
             "value": {"_array": list(raw)}},
            {"name": "CustomVersionData", "type": "ArrayProperty",
             "extra": {"inner_type": "ByteProperty"},
             "value": {"_array": list(custom)}},
        ],
    })
    return True


def _item_slot_raw_bytes(rd_value):
    if not isinstance(rd_value, dict):
        return None
    if "_rawdata_decoded" in rd_value:
        decoded = rd_value["_rawdata_decoded"]
        if len(decoded) == 1 and decoded[0]["type"] == "__RAW_TAIL__":
            return base64.b64decode(decoded[0]["value"]["_raw_b64"])
        return None  # a real nested property list here isn't the item format we expect
    if "_array" in rd_value:
        return bytes(rd_value["_array"])
    return None


def build_inventory_from_json(loaded_json, player_container_ids=None):
    containers_out = []
    slot_refs = {}
    slots_field_values = {}
    if not isinstance(loaded_json, dict) or "_parse_error" in loaded_json or "_raw_gvas_b64" in loaded_json:
        return containers_out, slot_refs, slots_field_values
    world = next((p for p in loaded_json.get("properties", []) if p["name"] == "worldSaveData"), None)
    if not world or not isinstance(world.get("value"), dict) or "_fields" not in world["value"]:
        return containers_out, slot_refs, slots_field_values
    ics = next((f for f in world["value"]["_fields"] if f["name"] == "ItemContainerSaveData"), None)
    if not ics or not isinstance(ics.get("value"), dict) or "_map" not in ics["value"]:
        return containers_out, slot_refs, slots_field_values

    for c_idx, (key, val) in enumerate(ics["value"]["_map"]):
        key_fields = key.get("_map_struct_fields", []) if isinstance(key, dict) else []
        val_fields = val.get("_map_struct_fields", []) if isinstance(val, dict) else []
        id_field = _find_field(key_fields, "ID")
        container_id = ""
        if id_field and isinstance(id_field["value"], dict) and "_raw_b64" in id_field["value"]:
            container_id = base64.b64decode(id_field["value"]["_raw_b64"]).hex()
        slot_num_field = _find_field(val_fields, "SlotNum")
        slot_num = slot_num_field["value"] if slot_num_field else 0
        slots_field = _find_field(val_fields, "Slots")
        slots_out = []
        n_items = 0
        if slots_field and isinstance(slots_field["value"], dict):
            slots_field_value = slots_field["value"]
            slots_field_values[c_idx] = slots_field_value
            for array_pos, item in enumerate(slots_field_value.get("_items", [])):
                rd = _find_field(item.get("_fields", []), "RawData")
                raw = _item_slot_raw_bytes(rd["value"]) if rd else None
                decoded = decode_item_slot_bytes(raw) if raw else None
                slot_index = decoded["marker"] if decoded and decoded["marker"] >= 0 else array_pos
                if decoded and decoded["item_id"]:
                    n_items += 1
                    slots_out.append({"slot_index": slot_index, "item_id": decoded["item_id"],
                                       "count": decoded["count"], "empty": False})
                else:
                    slots_out.append({"slot_index": slot_index, "item_id": "", "count": 0, "empty": True})
                if rd is not None:
                    slot_refs[(c_idx, slot_index)] = rd
        existing_by_idx = {s["slot_index"]: s for s in slots_out}
        total_slots = max(slot_num, (max(existing_by_idx) + 1) if existing_by_idx else 0)
        slots_out = [
            existing_by_idx.get(i) or {"slot_index": i, "item_id": "", "count": 0, "empty": True}
            for i in range(total_slots)
        ]

        containers_out.append({
            "index": c_idx, "container_id": container_id, "slot_num": slot_num,
            "slots": slots_out, "item_count": n_items,
        })

    _label_likely_player_containers(containers_out, player_container_ids)
    return containers_out, slot_refs, slots_field_values


_PLAYER_CONTAINER_ID_FIELDS = {
    "CommonContainerId": "Common Inventory",
    "EssentialContainerId": "Key Items / Essential",
    "WeaponLoadOutContainerId": "Weapon Loadout",
    "PlayerEquipArmorContainerId": "Equipped Armor",
    "FoodEquipContainerId": "Food Bag",
    "PalStorageContainerId": "Pal Storage (items)",
    "OtomoCharacterContainerId": "Active Party (characters, not items)",
    "DropSlotContainerId": "Drop Slot",
}


def _walk_fields_collect(fields, target_names, out, _depth=0):
    if _depth > 12 or not isinstance(fields, list):
        return
    for f in fields:
        if f.get("name") in target_names and f["name"] not in out:
            out[f["name"]] = f
        v = f.get("value")
        if isinstance(v, dict):
            if "_fields" in v:
                _walk_fields_collect(v["_fields"], target_names, out, _depth + 1)
            if "_items" in v:
                for item in v["_items"]:
                    _walk_fields_collect(item.get("_fields", []), target_names, out, _depth + 1)
            if "_map" in v:
                for k2, v2 in v["_map"]:
                    if isinstance(k2, dict) and "_map_struct_fields" in k2:
                        _walk_fields_collect(k2["_map_struct_fields"], target_names, out, _depth + 1)
                    if isinstance(v2, dict) and "_map_struct_fields" in v2:
                        _walk_fields_collect(v2["_map_struct_fields"], target_names, out, _depth + 1)


def extract_player_container_ids(player_json):
    result = {}
    if not isinstance(player_json, dict) or "properties" not in player_json:
        return result
    found = {}
    _walk_fields_collect(player_json["properties"], set(_PLAYER_CONTAINER_ID_FIELDS), found)
    for field_name, label in _PLAYER_CONTAINER_ID_FIELDS.items():
        f = found.get(field_name)
        if not f or not isinstance(f["value"], dict):
            continue
        value = f["value"]
        guid_b64 = None
        if "_raw_b64" in value:
            guid_b64 = value["_raw_b64"]
        elif "_fields" in value:
            id_field = _find_field(value["_fields"], "ID")
            if id_field and isinstance(id_field["value"], dict) and "_raw_b64" in id_field["value"]:
                guid_b64 = id_field["value"]["_raw_b64"]
        if guid_b64:
            result[label] = base64.b64decode(guid_b64).hex()
    return result


def get_verified_fast_travel_guids():
    packed = base64.b64decode(_FAST_TRAVEL_GUIDS_ZLIB_B64)
    guids = tuple(zlib.decompress(packed).decode("ascii").splitlines())
    if len(guids) != 174 or any(not re.fullmatch(r"[0-9A-F]{32}", g) for g in guids):
        raise ValueError("The embedded fast-travel GUID data failed validation.")
    return guids


def _build_fast_travel_map_raw(guids=None):
    guids = tuple(guids or get_verified_fast_travel_guids())
    out = io.BytesIO()
    out.write(struct.pack("<ii", 0, len(guids)))
    for guid in guids:
        _write_fstring(out, guid)
        out.write(b"\x01")
    return out.getvalue()


def _player_record_fields(player_json):
    if not isinstance(player_json, dict):
        return None
    save_data = _find_field(player_json.get("properties", []), "SaveData")
    save_fields = save_data.get("value", {}).get("_fields", []) if save_data else []
    record_data = _find_field(save_fields, "RecordData")
    return record_data.get("value", {}).get("_fields") if record_data else None


def unlock_all_fast_travel_in_player_json(player_json):
    record_fields = _player_record_fields(player_json)
    if not isinstance(record_fields, list):
        raise ValueError("The matched player save has no readable RecordData structure.")

    raw_map = _build_fast_travel_map_raw()
    field = _find_field(record_fields, "FastTravelPointUnlockFlag")
    changed = True
    if field is None:
        field = {
            "name": "FastTravelPointUnlockFlag",
            "type": "MapProperty",
            "extra": {
                "key_type": "NameProperty",
                "value_type": "BoolProperty",
            },
            "value": {
                "_raw_b64": "",
                "_unparsed_type": "MapProperty",
            },
        }
        record_fields.append(field)
    else:
        current_value = field.get("value", {})
        current_raw = (
            base64.b64decode(current_value.get("_raw_b64", ""))
            if isinstance(current_value, dict)
            else b""
        )
        changed = current_raw != raw_map
        field["type"] = "MapProperty"
        field["extra"] = {
            "key_type": "NameProperty",
            "value_type": "BoolProperty",
        }

    field["value"] = {
        "_raw_b64": base64.b64encode(raw_map).decode("ascii"),
        "_unparsed_type": "MapProperty",
    }
    return changed, len(get_verified_fast_travel_guids())


def _read_fstring_from_bytes(data, offset):
    if offset + 4 > len(data):
        raise ValueError("Truncated FString length.")
    length = struct.unpack_from("<i", data, offset)[0]
    offset += 4
    if length == 0:
        return "", offset
    byte_count = (-length * 2) if length < 0 else length
    if byte_count < 0 or offset + byte_count > len(data):
        raise ValueError("Invalid FString length.")
    raw = data[offset:offset + byte_count]
    offset += byte_count
    if length < 0:
        return raw[:-2].decode("utf-16-le", errors="strict"), offset
    return raw[:-1].decode("utf-8", errors="strict"), offset


def reveal_full_map_in_localdata_gvas(gvas_bytes):
    """Clear Palworld's map-fog masks without changing other local data."""
    data = bytearray(gvas_bytes)
    target_names = ("MaskTextureData", "WorldMapMaskTextureV4")
    masks_found = 0
    bytes_cleared = 0

    def revealed_pixels(length):
        # This matches PalworldSaveTools' verified clear-fog operation:
        # every byte in each saved mask texture is cleared.
        return b"\x00" * length

    for target_name in target_names:
        marker = struct.pack("<i", len(target_name) + 1) + target_name.encode("ascii") + b"\x00"
        search_from = 0
        while True:
            name_at = data.find(marker, search_from)
            if name_at < 0:
                break
            search_from = name_at + len(marker)
            try:
                prop_type, cursor = _read_fstring_from_bytes(data, search_from)
                if prop_type != "ArrayProperty" or cursor + 9 > len(data):
                    continue
                property_size = struct.unpack_from("<q", data, cursor)[0]
                cursor += 8
                # ArrayProperty headers store the inner property type before
                # the optional property GUID. This metadata is outside the
                # declared value size.
                inner_type, cursor = _read_fstring_from_bytes(data, cursor)
                if not inner_type:
                    continue
                has_property_guid = data[cursor]
                cursor += 1 + (16 if has_property_guid else 0)
                value_start = cursor
                value_end = value_start + property_size
                if property_size <= 0 or value_end > len(data):
                    continue

                # Current LocalData uses Palworld's custom byte-array layout:
                # FString array type, optional GUID, uint32 length, raw mask.
                try:
                    array_type, custom_cursor = _read_fstring_from_bytes(data, value_start)
                    if array_type == "ByteProperty" and custom_cursor < value_end:
                        has_inner_guid = data[custom_cursor]
                        custom_cursor += 1 + (16 if has_inner_guid else 0)
                        if custom_cursor + 4 <= value_end:
                            count = struct.unpack_from("<I", data, custom_cursor)[0]
                            payload_start = custom_cursor + 4
                            if count <= value_end - payload_start:
                                payload_end = payload_start + count
                                replacement = revealed_pixels(count)
                                bytes_cleared += sum(
                                    a != b for a, b in zip(
                                        data[payload_start:payload_end], replacement
                                    )
                                )
                                data[payload_start:payload_end] = replacement
                                masks_found += 1
                                continue
                except (UnicodeError, ValueError, struct.error):
                    pass

                # Older saves can contain a regular ArrayProperty<ByteProperty>.
                if value_start + 4 <= value_end:
                    count = struct.unpack_from("<i", data, value_start)[0]
                    payload_start = value_start + 4
                    if 0 <= count <= value_end - payload_start:
                        payload_end = payload_start + count
                        replacement = revealed_pixels(count)
                        bytes_cleared += sum(
                            a != b for a, b in zip(
                                data[payload_start:payload_end], replacement
                            )
                        )
                        data[payload_start:payload_end] = replacement
                        masks_found += 1
            except (UnicodeError, ValueError, IndexError, struct.error):
                continue

    if not masks_found:
        raise ValueError(
            "No supported map-fog texture was found in this LocalData.sav."
        )
    return bytes(data), masks_found, bytes_cleared


_KEY_ITEM_MARKERS = (
    "BossDefeatReward_", "AdditionalInventory_", "AutoMealPouch_",
    "UnlockEquipmentSlot_",
)
_EQUIPMENT_MARKERS = ("Armor", "Shield_", "Glider_", "Weapon_", "Helmet")


def _label_likely_player_containers(containers, player_container_ids=None):
    definitive_ids = set((player_container_ids or {}).values())
    id_to_label = {v: k for k, v in (player_container_ids or {}).items()}

    for c in containers:
        c["likely_label"] = None
        c["definitive"] = False
        if c["container_id"] in definitive_ids:
            c["likely_label"] = id_to_label[c["container_id"]]
            c["definitive"] = True
            continue
        item_ids = [s["item_id"] for s in c["slots"] if not s["empty"]]
        if any(marker in iid for iid in item_ids for marker in _KEY_ITEM_MARKERS):
            c["likely_label"] = "Likely: Key Items / Tech"
        elif c["slot_num"] <= 15 and any(
            marker in iid and not iid.startswith("Blueprint_")
            for iid in item_ids for marker in _EQUIPMENT_MARKERS
        ):
            c["likely_label"] = "Likely: Equipment"

    candidates = [c for c in containers if c["likely_label"] is None and c["slot_num"] >= 20]
    if candidates:
        best = max(candidates, key=lambda c: len({s["item_id"] for s in c["slots"] if not s["empty"]}))
        if len({s["item_id"] for s in best["slots"] if not s["empty"]}) >= 8:
            best["likely_label"] = "Likely: Common Inventory"


def _decode_save_in_process(path, oodle_path, player_ids, result_queue):
    """Decode and index a world save without sharing the GUI interpreter."""
    try:
        oodle = OodleDecompressor(oodle_path) if oodle_path else None
        with open(path, "rb") as source:
            raw = source.read()
        gvas, method = decompress_sav(raw, oodle=oodle)
        loaded_json = sav_to_json_dict(gvas)
        map_entries = build_map_entries_from_json(loaded_json)
        pal_entries, field_refs = build_pal_entries_from_json(loaded_json)
        palbox_id = find_palbox_container_id(loaded_json)
        party_ids = find_party_container_ids(loaded_json)
        containers, slot_refs, slot_values = build_inventory_from_json(
            loaded_json, player_ids)
        result_queue.put({
            "ok": True, "path": path, "raw_size": len(raw),
            "gvas": gvas, "method": method, "json": loaded_json,
            "map_entries": map_entries, "pal_entries": pal_entries,
            "field_refs": field_refs, "palbox_id": palbox_id,
            "party_ids": party_ids, "containers": containers,
            "slot_refs": slot_refs, "slot_values": slot_values,
        })
    except Exception as exc:
        result_queue.put({"ok": False, "error": str(exc)})


def _match_player_save_in_process(
        candidates, level_container_ids, oodle_path, result_queue):
    """Find the matching Players/*.sav without parsing it in Tk's process."""
    try:
        oodle = OodleDecompressor(oodle_path) if oodle_path else None
        level_ids = set(level_container_ids)
        best = None
        for path in candidates:
            try:
                with open(path, "rb") as source:
                    raw = source.read()
                gvas, _method = decompress_sav(raw, oodle=oodle)
                player_json = sav_to_json_dict(gvas)
                container_ids = extract_player_container_ids(player_json)
            except Exception:
                continue
            if not container_ids:
                continue
            matched = len(level_ids.intersection(container_ids.values()))
            if matched <= 0:
                continue
            score = (matched, len(container_ids))
            if best is None or score > best[0]:
                best = (score, path, container_ids)
        if best is None:
            result_queue.put({"ok": True, "matched": False})
        else:
            _score, path, container_ids = best
            result_queue.put({
                "ok": True, "matched": True, "path": path,
                "container_ids": container_ids})
    except Exception as exc:
        result_queue.put({"ok": False, "error": str(exc)})


class SaveEditorApp(tk.Tk):
    def _open_windowed_fullscreen(self):
        try:
            self.state("zoomed")
        except tk.TclError:
            # Fallback for window managers that do not support the zoomed state.
            self.update_idletasks()
            width = self.winfo_screenwidth()
            height = self.winfo_screenheight()
            self.geometry(f"{width}x{height}+0+0")

    def __init__(self):
        super().__init__()
        # Let Tk's event loop regain the interpreter frequently while save
        # decoding workers are active, preventing Windows from marking the
        # window as temporarily unresponsive.
        sys.setswitchinterval(0.001)
        self.title("All-In-1 Pal Editor")
        self.geometry("1680x900")
        self.minsize(1180, 720)
        self.configure(bg=COLOR["bg0"])
        self.option_add("*Font", FONT_UI)
        self.option_add("*tearOff", False)
        self.option_add("*Menu.background", COLOR["bg2"])
        self.option_add("*Menu.foreground", COLOR["text0"])
        self.option_add("*Menu.activeBackground", COLOR["accent_dim"])
        self.option_add("*Menu.activeForeground", COLOR["accent"])
        self.option_add("*Button.activeBackground", COLOR["accent_dim"])
        self.option_add("*Button.activeForeground", COLOR["text0"])
        self.option_add("*Button.highlightBackground", COLOR["line"])
        self.option_add("*Listbox.selectBackground", COLOR["accent_dim"])
        self.option_add("*Listbox.selectForeground", COLOR["text0"])
        # Start maximized in normal windowed mode. This fills the usable desktop
        # without using exclusive fullscreen or hiding the Windows taskbar/title bar.
        self.after_idle(self._open_windowed_fullscreen)
        self.results_visible = False
        self._results_detached_window = None

        self.pal_image_dir = None
        # Shared icon caches used by Docs, Palbox, inventory and picker views.
        # PhotoImages are keyed by the resolved file path + requested size so
        # duplicate/unknown icons are created only once for the whole app.
        self._pal_image_cache = {}
        self._pal_image_file_index = None
        self._item_image_cache = {}
        self._image_path_cache = {}
        self._source_image_cache = OrderedDict()
        self._photo_image_cache = OrderedDict()
        self._source_image_cache_limit = 384
        self._photo_image_cache_limit = 1800
        self._docs_prewarm_after = None
        self._source_game_json_cache = {}
        self._docs_detail_generation = 0
        self._debounce_jobs = {}
        self._data_revision = 0
        self._view_render_revision = {}
        self._nav_refresh_generation = 0
        self._nav_refresh_after = None
        self._inventory_grid_widgets = {}
        self._inventory_grid_container = None
        self._inventory_equipment_widgets = {}
        self._thumbnail_cache_root = Path.home() / ".palworld_save_editor" / "thumbnails"
        try:
            self._thumbnail_cache_root.mkdir(parents=True, exist_ok=True)
        except OSError:
            self._thumbnail_cache_root = None
        bundled_pal_assets = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Palworld_Pal_Assets")
        has_bundled_pal_assets = os.path.isdir(bundled_pal_assets)
        if has_bundled_pal_assets:
            self.pal_image_dir = bundled_pal_assets
        script_dir = os.path.dirname(os.path.abspath(__file__))
        bundled_item_icons = os.path.join(script_dir, "Palworld_Item_Assets")
        legacy_item_icons = os.path.join(script_dir, "assets", "item_icons")
        if os.path.isdir(bundled_item_icons):
            self.item_image_dir = bundled_item_icons
        elif os.path.isdir(legacy_item_icons):
            self.item_image_dir = legacy_item_icons
        else:
            self.item_image_dir = None
        reference_pal_assets = self._ensure_reference_pal_assets(script_dir)
        # Keep a user/bundled Palworld_Pal_Assets directory as the primary
        # source. It often contains newer icons that are absent from the
        # reference ZIP cache.
        if reference_pal_assets and not has_bundled_pal_assets:
            self.pal_image_dir = reference_pal_assets
        self.player_container_ids = {}

        self._build_style()
        self._build_topbar()
        self._build_body()
        self._install_ombre_tree_styling()
        self.render_all()
        self._view_render_revision.update({
            "editor": self._data_revision,
            "inventory": self._data_revision,
            "tools": self._data_revision,
        })
        self.bind_all("<Control-o>", lambda _event: self.load_sav_file())
        self.bind_all("<Control-s>", lambda _event: self.export_save_from_editor())
        self.bind_all("<F5>", lambda _event: self.render_all())
        # Docs thumbnails are loaded progressively for the currently visible
        # catalogue.  Prewarming every Pal and item here monopolised Tk's event
        # queue and made category changes pause even when their data was ready.

