    def _install_ombre_tree_styling(self):
        def apply_tree(tree):
            tree.tag_configure("_ombre_even", background="#0b0312",
                               foreground=COLOR["text0"])
            tree.tag_configure("_ombre_odd", background="#140821",
                               foreground=COLOR["text0"])
            original_insert = tree.insert
            row_counter = [len(tree.get_children(""))]

            def ombre_insert(parent, index, iid=None, **kwargs):
                if parent in ("", "{}"):
                    raw_tags = kwargs.get("tags", ())
                    if isinstance(raw_tags, str):
                        tags = (raw_tags,)
                    else:
                        tags = tuple(raw_tags)
                    shade = "_ombre_even" if row_counter[0] % 2 == 0 else "_ombre_odd"
                    kwargs["tags"] = tags + (shade,)
                    row_counter[0] += 1
                if iid is None:
                    return original_insert(parent, index, **kwargs)
                return original_insert(parent, index, iid, **kwargs)

            tree.insert = ombre_insert

        def walk(widget):
            for child in widget.winfo_children():
                if isinstance(child, ttk.Treeview):
                    apply_tree(child)
                walk(child)

        walk(self)

    def entry_style(self, widget):
        widget.configure(bg=COLOR["bg3"], fg=COLOR["text0"],
                          insertbackground=COLOR["text0"],
                          relief="flat", highlightthickness=1,
                          highlightbackground=COLOR["line_strong"],
                          highlightcolor=COLOR["accent"], font=FONT_MONO,
                          selectbackground=COLOR["accent_dim"],
                          selectforeground=COLOR["text0"])

    def _add_ombre_strip(self, parent, height=3):
        strip = tk.Canvas(parent, height=height, bd=0, highlightthickness=0,
                          bg=COLOR["bg0"])
        strip.place(x=0, rely=1.0, relwidth=1.0, height=height, anchor="sw")

        def redraw(_event=None):
            strip.delete("ombre")
            width = max(strip.winfo_width(), 1)
            start = (20, 8, 32)
            end = (168, 85, 247)
            steps = 64
            for index in range(steps):
                ratio = index / max(steps - 1, 1)
                red = int(start[0] + (end[0] - start[0]) * ratio)
                green = int(start[1] + (end[1] - start[1]) * ratio)
                blue = int(start[2] + (end[2] - start[2]) * ratio)
                left = int(width * index / steps)
                right = int(width * (index + 1) / steps) + 1
                strip.create_rectangle(
                    left, 0, right, height, outline="",
                    fill=f"#{red:02x}{green:02x}{blue:02x}", tags="ombre")

        strip.bind("<Configure>", redraw)
        strip.after_idle(redraw)
        return strip

    def _build_topbar(self):
        bar = tk.Frame(self, bg=COLOR["bg1"], height=68,
                       highlightthickness=0)
        bar.pack(side="top", fill="x")
        bar.pack_propagate(False)

        title_font = tkfont.Font(font=FONT_TITLE)
        number_font = tkfont.Font(family="Times New Roman", size=20, weight="bold")
        title_left = "All-In-"
        title_right = " Pal Editor"
        left_width = title_font.measure(title_left)
        number_width = number_font.measure("1")
        right_width = title_font.measure(title_right)
        number_x = left_width - 2
        brand = tk.Canvas(
            bar, width=number_x + number_width + right_width, height=66,
            bg=COLOR["bg1"], highlightthickness=0, bd=0,
        )
        brand.pack(side="left", padx=(20, 24))
        brand.create_text(
            0, 33, text=title_left, anchor="w",
            fill="#f8fafc", font=FONT_TITLE,
        )
        brand.create_text(
            number_x, 33, text="1", anchor="w",
            fill="#f8fafc", font=("Times New Roman", 20, "bold"),
        )
        brand.create_text(
            number_x + number_width, 33, text=title_right, anchor="w",
            fill="#f8fafc", font=FONT_TITLE,
        )

        def chip(text, bg, fg, command=None, image=None):
            cls = tk.Button if command else tk.Label
            kw = dict(text=text, bg=bg, fg=fg, font=("Segoe UI", 9, "bold"),
                      padx=14, pady=7, relief="flat", bd=0,
                      highlightthickness=1, highlightbackground=COLOR["line_strong"])
            if image is not None:
                kw.update(image=image, text="", padx=0, pady=0, width=37, height=32)
            if command:
                kw.update(command=command, activebackground=COLOR["bg3"], activeforeground=fg,
                          cursor="hand2")
            w = cls(bar, **kw)
            w.pack(side="left", padx=5, pady=15)
            if command:
                w.bind("<Enter>", lambda _event, widget=w: widget.configure(
                    highlightbackground=COLOR["accent"]))
                w.bind("<Leave>", lambda _event, widget=w: widget.configure(
                    highlightbackground=COLOR["line_strong"]))
            return w

        self.menu_chip = chip(
            "☰ Menu", COLOR["purple_dim"], "#c084fc",
            self._show_main_menu)
        self._export_save_icon = tk.PhotoImage(data="")
        export_chip = chip("", COLOR["accent_dim"], COLOR["accent"],
                           self.export_save_from_editor, image=self._export_save_icon)
        self._add_tooltip(export_chip, "Export edited save") if hasattr(self, "_add_tooltip") else None
        chip("✓ Validate", COLOR["green_dim"], "#34d399", self.show_validation_window)
        chip("⌁ Inspector", COLOR["accent_dim"], COLOR["accent"], self.show_dynamic_inspector)
        chip("⚙ Diagnostics", COLOR["purple_dim"], "#c084fc", self.show_diagnostics_window)

        self.profile_chip = tk.Label(bar, text="No player loaded",
                                     bg=COLOR["bg2"], fg=COLOR["accent"],
                                     font=("Segoe UI", 9, "bold"), padx=18, pady=6,
                                     highlightthickness=1,
                                     highlightbackground=COLOR["line_strong"])
        self.profile_chip.pack(side="right", padx=(5, 18), pady=15)

        self.build_chip = tk.Label(
            bar, text=APP_BUILD, bg="#f4c84a", fg="#111827",
            font=("Segoe UI", 9, "bold"), padx=13, pady=6,
            relief="flat", bd=0, highlightthickness=1,
            highlightbackground=COLOR["line"],
        )
        self.build_chip.pack(side="right", padx=(5, 0), pady=15)

        self._topbar_ombre_strip = self._add_ombre_strip(bar, 3)

    def _close_main_menu(self):
        submenu = getattr(self, "_main_submenu", None)
        if submenu is not None:
            try:
                submenu.destroy()
            except tk.TclError:
                pass
        self._main_submenu = None
        popup = getattr(self, "_main_menu_popup", None)
        if popup is not None:
            try:
                popup.destroy()
            except tk.TclError:
                pass
        self._main_menu_popup = None

    def _open_editor_data_folder(self):
        folder = os.path.dirname(os.path.abspath(__file__))
        try:
            os.startfile(folder)
        except (AttributeError, OSError) as exc:
            messagebox.showerror(
                "Open folder", f"Could not open:\n{folder}\n\n{exc}")

    def _load_named_save(self, title):
        path = filedialog.askopenfilename(
            title=title,
            filetypes=[
                ("Palworld save files", "*.sav"),
                ("All files", "*.*")])
        if path:
            self.after(
                1, lambda selected=path:
                self._begin_async_sav_load(selected))

    def _rename_loaded_world(self):
        loaded = getattr(self, "loaded_sav_json", None)
        if not loaded:
            messagebox.showinfo(
                "Rename World", "Load a world save before renaming it.")
            return
        candidates = {"worldname", "world_name", "servername", "server_name"}
        matches = []

        def visit(node):
            if isinstance(node, dict):
                field_name = str(node.get("name") or "").casefold()
                if field_name in candidates and "value" in node:
                    matches.append(node)
                for value in node.values():
                    visit(value)
            elif isinstance(node, list):
                for value in node:
                    visit(value)

        visit(loaded)
        if not matches:
            messagebox.showwarning(
                "Rename World",
                "This save does not expose an editable world-name field.")
            return
        raw_value = matches[0].get("value")
        if isinstance(raw_value, dict):
            current = str(raw_value.get("value") or "")
        else:
            current = str(raw_value or "")
        new_name = simpledialog.askstring(
            "Rename World", "New world name:",
            initialvalue=current, parent=self)
        if new_name is None:
            return
        new_name = new_name.strip()
        if not new_name:
            messagebox.showwarning(
                "Rename World", "The world name cannot be empty.")
            return
        for field in matches:
            if isinstance(field.get("value"), dict):
                field["value"]["value"] = new_name
            else:
                field["value"] = new_name
        self._data_revision = getattr(self, "_data_revision", 0) + 1
        messagebox.showinfo(
            "Rename World",
            "The world name was updated in the loaded data.\n"
            "Use Save Changes to export the edited save.")

    def _menu_run(self, callback):
        self._close_main_menu()
        self.after_idle(callback)

    def _show_main_menu(self):
        if getattr(self, "_main_menu_popup", None) is not None:
            self._close_main_menu()
            return
        popup = tk.Toplevel(self)
        self._main_menu_popup = popup
        popup.withdraw()
        popup.overrideredirect(True)
        popup.configure(bg=COLOR["line_strong"])
        try:
            popup.attributes("-topmost", True)
        except tk.TclError:
            pass
        popup.bind("<Escape>", lambda _event: self._close_main_menu())

        panel = tk.Frame(
            popup, bg=COLOR["bg1"], padx=7, pady=7,
            width=212, height=250,
            highlightthickness=1, highlightbackground=COLOR["line"])
        panel.pack(side="left", fill="y")
        panel.pack_propagate(False)
        self._main_menu_category_panel = panel
        categories = [
            ("file", "📁", "File"),
            ("functions", "⚙", "Functions"),
            ("maps", "🗺", "Maps"),
            ("exclusions", "🚫", "Exclusions"),
            ("languages", "🌐", "Language"),
            ("configs", "⚙", "Configs"),
        ]
        self._main_menu_buttons = {}
        for key, icon, label in categories:
            row = tk.Frame(
                panel, bg=COLOR["bg1"], width=198, height=39,
                cursor="hand2")
            row.pack(fill="x")
            row.pack_propagate(False)
            icon_label = tk.Label(
                row, text=icon, bg=COLOR["bg1"], fg=COLOR["text1"],
                font=("Segoe UI Emoji", 11), width=3)
            icon_label.pack(side="left", padx=(7, 2))
            text_label = tk.Label(
                row, text=label, bg=COLOR["bg1"], fg=COLOR["text1"],
                font=("Segoe UI", 10), anchor="w")
            text_label.pack(side="left", fill="x", expand=True)
            arrow = tk.Label(
                row, text="▶", bg=COLOR["bg1"], fg=COLOR["text2"],
                font=("Segoe UI", 8))
            arrow.pack(side="right", padx=9)
            self._main_menu_buttons[key] = row

            def enter(_event, chosen=key, widgets=(
                    row, icon_label, text_label, arrow)):
                for widget in widgets:
                    widget.configure(
                        bg=COLOR["accent_dim"],
                        fg=COLOR["accent"])

            def leave(_event, chosen=key, widgets=(
                    row, icon_label, text_label, arrow)):
                if getattr(
                        self, "_main_submenu_category", None) == chosen:
                    return
                for widget in widgets:
                    widget.configure(
                        bg=COLOR["bg1"], fg=COLOR["text1"])
                widgets[-1].configure(fg=COLOR["text2"])

            for widget in (row, icon_label, text_label, arrow):
                widget.bind("<Enter>", enter)
                widget.bind(
                    "<Button-1>",
                    lambda _event, chosen=key, anchor_widget=row:
                        self._show_main_submenu(chosen, anchor_widget))
            row.bind("<Leave>", leave)

        popup.update_idletasks()
        width = 212
        height = 250

        def place_popup():
            if not popup.winfo_exists():
                return
            self.update_idletasks()
            x = int(self.menu_chip.winfo_rootx())
            y = int(
                self.menu_chip.winfo_rooty()
                + self.menu_chip.winfo_height() + 2)
            x = max(0, min(x, self.winfo_screenwidth() - width))
            y = max(0, min(y, self.winfo_screenheight() - height))
            self._main_menu_origin = (x, y)
            self._main_menu_base_height = height
            popup.wm_geometry(f"{width}x{height}+{x}+{y}")
            popup.lift()

        place_popup()
        popup.deiconify()
        place_popup()
        popup.after(10, place_popup)

    def _show_main_submenu(self, category, anchor):
        current = getattr(self, "_main_submenu_category", None)
        if current == category and getattr(self, "_main_submenu", None):
            return
        old = getattr(self, "_main_submenu", None)
        if old is not None:
            try:
                old.destroy()
            except tk.TclError:
                pass
        for key, row in getattr(self, "_main_menu_buttons", {}).items():
            selected = key == category
            background = COLOR["accent_dim"] if selected else COLOR["bg1"]
            foreground = COLOR["accent"] if selected else COLOR["text1"]
            row.configure(bg=background)
            for child in row.winfo_children():
                child.configure(bg=background, fg=foreground)
            if not selected and row.winfo_children():
                row.winfo_children()[-1].configure(fg=COLOR["text2"])
        actions = []

        def action(label, callback):
            actions.append((label, callback))

        if category == "file":
            action("Load Save", self.load_sav_file)
            action(
                "Load GamePass Save",
                lambda: self._load_named_save("Load GamePass save"))
            action(
                "Load from Backup",
                lambda: self._load_named_save("Load Palworld backup save"))
            action(
                "Load WorldOption",
                lambda: self._load_named_save("Load WorldOption.sav"))
            action("Save Changes", self.export_save_from_editor)
            action("Rename World", self._rename_loaded_world)
            action("Open Data Folder", self._open_editor_data_folder)
        elif category == "functions":
            action("Validate Save", self.show_validation_window)
            action("Dynamic Item Inspector", self.show_dynamic_inspector)
            action("Diagnostics", self.show_diagnostics_window)
            action("Max Current Pal Box", self.max_box)
            action("Unlock All Fast Travel", self.unlock_all_fast_travel)
            action("Reveal Full Map", self.reveal_full_map)
        elif category == "maps":
            action("Show Map", lambda: self.select_nav("map"))
            action("Refresh Map Data", self.load_map_data)
            action("Reset Map View", self.map_reset_view)
            action("Select Map Assets Folder", self.set_map_image_dir)
        elif category == "exclusions":
            action("Show Exclusions", lambda: self.select_nav("exclusions"))
            action("Save Exclusions", self._save_exclusions)
        elif category == "languages":
            action(
                "English (current)",
                lambda: messagebox.showinfo(
                    "Language", "English is the installed interface language."))
        elif category == "configs":
            action("Open Tools", lambda: self.select_nav("tools"))
            action("Show / Hide Results", self.toggle_results)
            action("Detach / Attach Results", self.detach_results)
            action("Select Asset Folder", self.set_map_image_dir)

        popup = getattr(self, "_main_menu_popup", None)
        if popup is None or not popup.winfo_exists():
            return
        submenu = tk.Frame(
            popup, bg=COLOR["line_strong"],
            width=235, height=250, highlightthickness=0)
        submenu.pack(side="left", fill="y")
        submenu.pack_propagate(False)
        body = tk.Frame(
            submenu, bg=COLOR["bg1"], padx=5, pady=5,
            highlightthickness=1, highlightbackground=COLOR["line"])
        body.pack(fill="both", expand=True)
        for label, callback in actions:
            row = tk.Label(
                body, text=label, bg=COLOR["bg1"], fg=COLOR["text1"],
                font=("Segoe UI", 9), anchor="w", padx=11, pady=7,
                cursor="hand2")
            row.pack(fill="x")
            row.bind(
                "<Enter>",
                lambda _event, widget=row: widget.configure(
                    bg=COLOR["accent_dim"], fg=COLOR["accent"]))
            row.bind(
                "<Leave>",
                lambda _event, widget=row: widget.configure(
                    bg=COLOR["bg1"], fg=COLOR["text1"]))
            row.bind(
                "<Button-1>",
                lambda _event, cb=callback: self._menu_run(cb))

        popup.update_idletasks()
        width = max(235, body.winfo_reqwidth())
        height = max(250, body.winfo_reqheight())
        submenu.configure(width=width, height=height)
        base_width = 212
        origin_x, origin_y = getattr(
            self, "_main_menu_origin",
            (popup.winfo_x(), popup.winfo_y()))
        total_width = base_width + width
        total_height = max(
            getattr(self, "_main_menu_base_height", 250), height)
        if origin_x + total_width > self.winfo_screenwidth():
            origin_x = max(0, origin_x - width)
        popup.wm_geometry(
            f"{total_width}x{total_height}+{origin_x}+{origin_y}")
        popup.lift()
        self._main_submenu = submenu
        self._main_submenu_category = category

    def _build_body(self):
        self.body = tk.Frame(self, bg=COLOR["bg0"])
        self.body.pack(side="top", fill="both", expand=True)

        self.nav_panel = self._build_nav(self.body)
        self.nav_panel.pack(side="left", fill="y")

        self.editor_view = tk.Frame(self.body, bg=COLOR["bg0"])
        self.docs_view = self._build_docs(self.body)
        self.about_view = self._build_about_us(self.body)
        self.tools_view = self._build_tools(self.body)
        self.json_editor_view = self._build_json_editor(self.body)
        self.inventory_view = self._build_inventory(self.body)
        self.base_inventory_view = self._build_base_inventory(self.body)
        self.map_view = self._build_map(self.body)
        self.players_view = self._build_players(self.body)
        self.guilds_view = self._build_guilds(self.body)
        self.bases_view = self._build_bases(self.body)
        self.exclusions_view = self._build_exclusions(self.body)
        self.breeding_view = self._build_breeding(self.body)
        self.placeholder_view = self._build_placeholder(self.body)

        pal_header = tk.Frame(self.editor_view, bg=COLOR["bg0"])
        pal_header.pack(fill="x", padx=10, pady=(10, 8))
        tk.Label(
            pal_header, text="Pal Editor", bg=COLOR["bg2"], fg=COLOR["accent"],
            font=("Segoe UI", 10, "bold"), padx=14, pady=9,
            highlightthickness=1, highlightbackground=COLOR["line_strong"],
        ).pack(side="left")
        self.pal_editor_profile_chip = tk.Label(
            pal_header, text="No player loaded", bg=COLOR["bg2"],
            fg=COLOR["accent"], font=("Segoe UI", 9, "bold"),
            padx=22, pady=7, highlightthickness=1,
            highlightbackground=COLOR["line_strong"],
        )
        self.pal_editor_profile_chip.pack(side="right")

        pal_workspace = tk.Frame(
            self.editor_view, bg=COLOR["bg1"], highlightthickness=1,
            highlightbackground=COLOR["line_strong"],
        )
        pal_workspace.pack(fill="both", expand=True, padx=10, pady=(0, 10))

        self.roster_panel = self._build_roster(pal_workspace)
        self.roster_panel.pack(side="left", fill="y", padx=(10, 5), pady=10)

        self.grid_panel = self._build_grid(pal_workspace)
        self.grid_panel.pack(side="left", fill="both", expand=True,
                             padx=5, pady=10)

        self.detail_panel = self._build_detail(pal_workspace)
        self.detail_panel.pack(side="left", fill="y", padx=(5, 10), pady=10)

        # Keep the results model alive for existing statistics/change-log code,
        # but the reference Pal Editor uses the full width for the three work panels.
        # Results is a true body-level rail so it can dock beside every page
        # and can be removed without overlaying or corrupting page geometry.
        self.results_panel = self._build_results(self.body)

        self.views = {"editor": self.editor_view, "docs": self.docs_view,
                      "about": self.about_view, "tools": self.tools_view,
                      "json": self.json_editor_view, "inventory": self.inventory_view,
                      "base_inventory": self.base_inventory_view, "map": self.map_view,
                      "players": self.players_view, "guilds": self.guilds_view,
                      "bases": self.bases_view, "exclusions": self.exclusions_view,
                      "breeding": self.breeding_view}
        for view in self.views.values():
            view.configure(highlightthickness=1,
                           highlightbackground=COLOR["line_strong"])
        self.select_nav("tools")

    def _build_nav(self, parent):
        frame = tk.Frame(parent, bg=COLOR["bg1"], width=194,
                         highlightthickness=1,
                         highlightbackground=COLOR["line_strong"])
        frame.pack_propagate(False)

        tk.Label(frame, text="≪", bg=COLOR["bg0"], fg=COLOR["accent"],
                 font=("Segoe UI", 18, "bold"), anchor="w").pack(fill="x", padx=12, pady=(8, 10))
        items = [
            ("🔧  Tools", "tools"),
            ("⚑  Map Viewer", "map"),
            ("▤  Base Inventory", "base_inventory"),
            ("▣  Player Inventory", "inventory"),
            ("♞  Pal Editor", "editor"),
            ("♟  Search Players:", "players"),
            ("⬟  Search Guilds:", "guilds"),
            ("⌂  Search Bases:", "bases"),
            ("⊘  Exclusions", "exclusions"),
            ("{ }  JSON Editor", "json"),
            ("◯  Breeding", "breeding"),
            ("▣  Docs", "docs"),
            ("♥  About Us", "about"),
        ]
        self.nav_buttons = {}
        for label, key in items:
            row = tk.Frame(frame, bg=COLOR["bg1"])
            row.pack(fill="x", padx=8, pady=2)
            marker = tk.Frame(row, bg=COLOR["bg1"], width=4, height=36)
            marker.pack(side="left", fill="y")
            btn = tk.Label(row, text=label, bg=COLOR["bg1"], fg=COLOR["text1"],
                           font=("Segoe UI", 9, "bold"), anchor="w",
                           padx=14, pady=9,
                           cursor="hand2")
            btn.pack(side="left", fill="x", expand=True)
            btn.bind("<Button-1>", lambda e, k=key: self.select_nav(k))
            btn.bind("<Enter>", lambda _event, widget=btn, nav_key=key:
                     widget.configure(bg=COLOR["bg3"])
                     if getattr(self, "_selected_nav", None) != nav_key else None)
            btn.bind("<Leave>", lambda _event, widget=btn, nav_key=key:
                     widget.configure(bg=COLOR["bg1"])
                     if getattr(self, "_selected_nav", None) != nav_key else None)
            self.nav_buttons[key] = btn
            self.nav_buttons[key + "_marker"] = marker

        tk.Frame(frame, bg=COLOR["bg1"]).pack(fill="both", expand=True)
        self.detach_results_button = tk.Label(
            frame, text="⌁  Detach", bg=COLOR["bg0"], fg=COLOR["text1"],
            font=("Segoe UI", 8, "bold"), anchor="w", padx=14, pady=8,
            cursor="hand2")
        self.detach_results_button.pack(fill="x")
        self.detach_results_button.bind(
            "<Button-1>", lambda _event: self.detach_results())
        self.toggle_results_button = tk.Label(
            frame, text="❯  Show Results", bg=COLOR["bg0"],
            fg=COLOR["accent"], font=("Segoe UI", 8, "bold"),
            anchor="w", padx=14, pady=8, cursor="hand2")
        self.toggle_results_button.pack(fill="x")
        self.toggle_results_button.bind(
            "<Button-1>", lambda _event: self.toggle_results())
        for control in (self.detach_results_button, self.toggle_results_button):
            control.bind(
                "<Enter>", lambda _event, widget=control:
                widget.configure(bg=COLOR["bg3"]))
            control.bind(
                "<Leave>", lambda _event, widget=control:
                widget.configure(bg=COLOR["bg0"]))
        return frame

    def select_nav(self, key):
        if (getattr(self, "_selected_nav", None) == key
                and getattr(self, "_visible_view", None) is not None):
            return
        self._selected_nav = key
        self._current_view_key = key
        for k, btn in self.nav_buttons.items():
            if k.endswith("_marker"):
                base = k[:-7]
                btn.configure(bg=COLOR["accent"] if base == key else COLOR["bg1"])
            elif k == key:
                btn.configure(bg=COLOR["accent_dim"], fg=COLOR["accent"],
                              font=("Segoe UI", 9, "bold"))
            else:
                btn.configure(bg=COLOR["bg1"], fg=COLOR["text1"],
                              font=("Segoe UI", 9, "bold"))

        previous = getattr(self, "_visible_view", None)
        if previous is not None:
            previous.pack_forget()
        target = self.views.get(key, self.placeholder_view)
        target.pack(side="left", fill="both", expand=True, padx=12, pady=12)
        self._visible_view = target
        if target is self.placeholder_view:
            self.placeholder_label.configure(text=f"\u201C{key}\u201D section \u2014 build this out next.")

        previous_job = getattr(self, "_nav_refresh_after", None)
        if previous_job is not None:
            try:
                self.after_cancel(previous_job)
            except tk.TclError:
                pass
        self._nav_refresh_generation = (
            getattr(self, "_nav_refresh_generation", 0) + 1)
        generation = self._nav_refresh_generation
        revision = getattr(self, "_data_revision", 0)
        if self._view_render_revision.get(key) == revision:
            return
        self._nav_refresh_after = self.after_idle(
            lambda: self._refresh_selected_view(key, generation, revision))

    def _refresh_selected_view(self, key, generation, revision):
        self._nav_refresh_after = None
        if (generation != getattr(self, "_nav_refresh_generation", None)
                or key != getattr(self, "_current_view_key", None)):
            return
        if key == "map":
            self.load_map_data()
        elif key == "editor":
            self.render_all()
        elif key == "inventory":
            self.render_inventory()
        elif key == "base_inventory":
            self.render_base_inventory()
        elif key == "docs":
            # The initial Docs catalogue is intentionally lazy-loaded.
            self._docs_rendered_category = None
            self.select_doc_category(docs_category)
            return
        elif key == "players" and getattr(self, "loaded_sav_json", None):
            self.search_players()
        elif key == "guilds" and getattr(self, "loaded_sav_json", None):
            self.search_guilds()
        elif key == "bases" and getattr(self, "loaded_sav_json", None):
            self.search_bases()
        elif key == "exclusions":
            self._refresh_exclusions()
        elif key == "breeding":
            self._load_breeding_data()
        self._view_render_revision[key] = revision

    def _base_chip(self, parent, text, command=None, width=None, disabled=False):
        normal_bg = COLOR["bg3"] if not disabled else "#151a1f"
        kw = dict(text=text, bg=normal_bg,
                  fg=COLOR["accent"] if not disabled else "#6f7478",
                  activebackground=COLOR["accent_dim"], activeforeground=COLOR["text0"],
                  relief="flat", bd=0, font=("Segoe UI", 8, "bold"),
                  padx=11, pady=7, cursor="hand2" if not disabled else "arrow",
                  highlightthickness=1,
                  highlightbackground=COLOR["line_strong"] if not disabled else COLOR["line"])
        if width is not None:
            kw["width"] = width
        if command is not None and not disabled:
            kw["command"] = command
        btn = tk.Button(parent, **kw)
        if disabled:
            btn.configure(state="disabled", disabledforeground="#6f7478")
        else:
            btn.bind("<Enter>", lambda _event: btn.configure(
                bg=COLOR["accent_dim"], highlightbackground=COLOR["accent"]))
            btn.bind("<Leave>", lambda _event: btn.configure(
                bg=normal_bg, highlightbackground=COLOR["line_strong"]))
        return btn

