    @staticmethod
    def _format_last_seen(value):
        if not value:
            return "—"
        try:
            now = int(datetime.datetime.now(datetime.timezone.utc).timestamp())
            v = int(value)
            if v > 10**15:
                v = int((v - 621355968000000000) / 10_000_000)
            elif v > 10**12:
                v //= 1000
            seconds = max(0, now - v)
            if seconds < 60: return f"{seconds}s ago"
            if seconds < 3600: return f"{seconds // 60}m ago"
            if seconds < 86400: return f"{seconds // 3600}h ago"
            return f"{seconds // 86400}d ago"
        except Exception:
            return "—"

    @staticmethod
    def _normalise_player_guid(value):
        text = re.sub(r"[^0-9a-fA-F]", "", str(value or "")).lower()
        return text.zfill(32) if text else ""

    @classmethod
    def _normalise_decoded_player_guid(cls, value):
        """Return the comparable 32-digit UID stored by the decoded save."""
        if isinstance(value, dict):
            raw_b64 = value.get("_raw_b64")
            if raw_b64:
                try:
                    raw = base64.b64decode(raw_b64)
                    if len(raw) == 16:
                        converted = _guid_from_pal_bytes(raw)
                        if converted:
                            return cls._normalise_player_guid(converted)
                        return cls._normalise_player_guid(str(uuid.UUID(bytes=raw)))
                except (ValueError, TypeError):
                    pass
            for key in ("value", "Value", "ID", "id", "Guid", "guid"):
                if key in value:
                    result = cls._normalise_decoded_player_guid(value[key])
                    if result:
                        return result
            return ""
        return cls._normalise_player_guid(value)

    @staticmethod
    def _pal_guid_display(value):
        raw = bytes.fromhex(re.sub(r"[^0-9a-fA-F]", "", str(value or ""))) if value else b""
        if len(raw) != 16:
            return str(value or "—")
        converted = _guid_from_pal_bytes(raw)
        return converted or str(uuid.UUID(bytes=raw))

    def search_players(self):
        if not getattr(self, "loaded_sav_json", None):
            messagebox.showwarning("No world save loaded", "Load Level.sav from the Tools tab first.")
            return
        if getattr(self, "_map_entries_source_id", None) == id(self.loaded_sav_json):
            data = self.map_entries
        else:
            data = build_map_entries_from_json(self.loaded_sav_json)
            self.map_entries = data
            self._map_entries_source_id = id(self.loaded_sav_json)
        guild_by_uid = {}
        for guild in data.get("guilds", []):
            pass
        rows = []
        for p in data.get("players", []):
            uid = p.get("uid") or ""
            rows.append({"name": p.get("name") or "Unnamed Survivor", "seen": "—",
                         "level": p.get("level", 1), "pals": 0, "uid": uid,
                         "guild_name": p.get("guild") or "Unnamed Guild", "guild_id": "—"})
        # Enrich from decoded guild records, including last-online and guild IDs.
        try:
            world = next((x for x in self.loaded_sav_json.get("properties", []) if x.get("name") == "worldSaveData"), None)
            wfields = world.get("value", {}).get("_fields", []) if world else []
            gsm = _find_field(wfields, "GroupSaveDataMap")
            if gsm and isinstance(gsm.get("value"), dict) and "_raw_b64" in gsm["value"]:
                raw = base64.b64decode(gsm["value"]["_raw_b64"])
                by_uid = {self._normalise_player_guid(r["uid"]): r for r in rows if r["uid"]}
                for group_id, fields in _decode_guid_keyed_struct_map(raw):
                    gt = _find_field(fields, "GroupType")
                    if not gt or gt.get("value") not in ("EPalGroupType::Guild", "EPalGroupType::IndependentGuild"):
                        continue
                    rd = _rawdata_bytes(fields)
                    dec = decode_group_raw(rd, gt.get("value")) if rd else None
                    if not dec: continue
                    for gp in dec.get("players", []):
                        raw_uid = str(gp.get("uid", ""))
                        candidates = {self._normalise_player_guid(raw_uid)}
                        try:
                            raw_uid_bytes = bytes.fromhex(self._normalise_player_guid(raw_uid))
                            converted = _guid_from_pal_bytes(raw_uid_bytes)
                            if converted:
                                candidates.add(self._normalise_player_guid(converted))
                        except Exception:
                            pass
                        row = next((by_uid[k] for k in candidates if k in by_uid), None)
                        if row:
                            row["guild_name"] = dec.get("guild_name") or "Unnamed Guild"
                            row["guild_id"] = self._pal_guid_display(group_id)
                            row["seen"] = self._format_last_seen(gp.get("last_online"))
        except Exception:
            pass
        # Count owned Pals from the GUID bytes in each decoded SaveParameter.
        try:
            world = next(x for x in self.loaded_sav_json.get("properties", []) if x.get("name") == "worldSaveData")
            csm = _find_field(world["value"].get("_fields", []), "CharacterSaveParameterMap")
            counts = {}
            rows_by_uid = {}
            for row in rows:
                uid_key = self._normalise_player_guid(row.get("uid"))
                if uid_key:
                    rows_by_uid[uid_key] = row
            for key, val in (csm.get("value", {}).get("_map", []) if csm else []):
                vf = val.get("_map_struct_fields", []) if isinstance(val, dict) else []
                rawf = _find_field(vf, "RawData")
                dec = rawf.get("value", {}).get("_rawdata_decoded", []) if rawf else []
                sp = next((x for x in dec if x.get("name") == "SaveParameter"), None)
                pf = sp.get("value", {}).get("_fields", []) if sp else []
                isp = _find_field(pf, "IsPlayer")
                if isp and isp.get("value"): continue
                owner = _find_field(pf, "OwnerPlayerUId") or _find_field(pf, "OwnerPlayerUID")
                if owner:
                    owner_uid = self._normalise_decoded_player_guid(owner.get("value"))
                    if owner_uid in rows_by_uid:
                        counts[owner_uid] = counts.get(owner_uid, 0) + 1
            for row in rows:
                row["pals"] = counts.get(self._normalise_player_guid(row.get("uid")), 0)
        except Exception:
            pass
        self.player_search_rows = rows
        self._render_player_search_rows()

    def _render_player_search_rows(self):
        if not hasattr(self, "players_tree"): return
        q = self.player_search_var.get().strip().lower()
        if q == "type to search...": q = ""
        rows = [r for r in self.player_search_rows if not q or q in " ".join(str(v).lower() for v in r.values())]
        key = self.player_search_sort_column
        rows.sort(key=lambda r: (isinstance(r.get(key), str), str(r.get(key, "")).lower()),
                  reverse=self.player_search_sort_reverse)
        self.players_tree.delete(*self.players_tree.get_children())
        self.player_search_lookup.clear()
        for r in rows:
            iid = self.players_tree.insert("", "end", values=(r["name"], r["seen"], r["level"], r["pals"],
                                                                r["uid"], r["guild_name"], r["guild_id"]))
            self.player_search_lookup[iid] = r

    def _sort_player_search(self, column):
        if self.player_search_sort_column == column:
            self.player_search_sort_reverse = not self.player_search_sort_reverse
        else:
            self.player_search_sort_column, self.player_search_sort_reverse = column, False
        self._render_player_search_rows()

    def _selected_player_search_row(self):
        sel = self.players_tree.selection() if hasattr(self, "players_tree") else ()
        return self.player_search_lookup.get(sel[0]) if sel else None

    def _open_selected_search_player(self, event=None):
        if event is not None and hasattr(event, "y"):
            iid = self.players_tree.identify_row(event.y)
            if iid:
                self.players_tree.selection_set(iid)
                self.players_tree.focus(iid)
        row = self._selected_player_search_row()
        if not row:
            return "break"

        uid_clean = self._normalise_player_guid(row.get("uid"))
        level_path = getattr(self, "loaded_sav_path", None)
        candidates = []
        searched_folders = []
        if level_path:
            root = Path(level_path).resolve().parent
            for folder in (root / "Players", root):
                if folder.is_dir():
                    searched_folders.append(folder)
                    candidates.extend(p for p in folder.glob("*.sav") if not p.stem.upper().endswith("_DPS"))

        hit = None
        if uid_clean:
            for path in candidates:
                if self._normalise_player_guid(path.stem) == uid_clean:
                    hit = path
                    break
        if hit is None and uid_clean:
            # Some saves expose the GUID in Palworld's serialised byte order.
            try:
                converted = _guid_from_pal_bytes(bytes.fromhex(uid_clean))
                converted_clean = self._normalise_player_guid(converted)
            except Exception:
                converted_clean = ""
            if converted_clean:
                for path in candidates:
                    if self._normalise_player_guid(path.stem) == converted_clean:
                        hit = path
                        break

        if hit:
            try:
                self._set_profile_player_name(row.get("name"))
                self._load_player_sav_path(str(hit), quiet=False)
                self.select_nav("inventory")
            except Exception as exc:
                messagebox.showerror("Couldn't load player save", f"{hit.name}\n\n{exc}")
            return "break"

        locations = "\n".join(str(p) for p in searched_folders) or "No valid save folder was available."
        messagebox.showwarning(
            "Player save not found",
            f"{row['name']}\nUID: {row['uid']}\n\n"
            f"The matching player save was not found. Expected filename:\n"
            f"{uid_clean.upper() or '<UID>'}.sav\n\nSearched:\n{locations}",
        )
        return "break"


    def _bulk_player_items(self):
        self.select_nav("inventory")
        messagebox.showinfo("Bulk Item Management", "Player Inventory is open. Load or select a player, then use its inventory controls for bulk changes.")

    def _bulk_player_pals(self):
        self.select_nav("editor")
        messagebox.showinfo("Bulk Pal Management", "Pal Editor is open. Use box controls and right-click actions to manage the selected player's Pals.")

    def _bulk_player_technology(self):
        messagebox.showinfo("Bulk Technology Management", "Technology editing requires a matching player .sav. Double-click a player first; this panel is reserved for the technology editor.")

