    def _build_guild_tree(self, parent, headings, sort_command):
        wrap = tk.Frame(parent, bg=COLOR["bg1"])
        wrap.pack(fill="both", expand=True)
        columns = tuple(column for column, _text, _width in headings)
        tree = ttk.Treeview(wrap, columns=columns, show="headings",
                            selectmode="browse")
        for column, text, width in headings:
            tree.heading(column, text=text,
                         command=lambda c=column: sort_command(c))
            tree.column(column, width=width, minwidth=60,
                        anchor="center", stretch=True)
        ybar = ttk.Scrollbar(wrap, orient="vertical", command=tree.yview)
        xbar = ttk.Scrollbar(wrap, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=ybar.set, xscrollcommand=xbar.set)
        tree.grid(row=0, column=0, sticky="nsew")
        ybar.grid(row=0, column=1, sticky="ns")
        xbar.grid(row=1, column=0, sticky="ew")
        wrap.grid_rowconfigure(0, weight=1)
        wrap.grid_columnconfigure(0, weight=1)
        tree.configure(cursor="hand2")
        return tree

    def search_guilds(self):
        if not getattr(self, "loaded_sav_json", None):
            return
        # Keep the member level and Pal totals in sync with Search Players.
        self.search_players()
        players_by_uid = {}
        for player in getattr(self, "player_search_rows", []):
            uid = self._normalise_player_guid(player.get("uid"))
            if uid:
                players_by_uid[uid] = player

        guilds = []
        try:
            world = next(x for x in self.loaded_sav_json.get("properties", [])
                         if x.get("name") == "worldSaveData")
            gsm = _find_field(world["value"].get("_fields", []), "GroupSaveDataMap")
            raw = base64.b64decode(gsm["value"]["_raw_b64"])
            for group_id, fields in _decode_guid_keyed_struct_map(raw):
                group_type = _find_field(fields, "GroupType")
                if not group_type or group_type.get("value") not in (
                        "EPalGroupType::Guild", "EPalGroupType::IndependentGuild"):
                    continue
                raw_data = _rawdata_bytes(fields)
                decoded = decode_group_raw(raw_data, group_type.get("value")) if raw_data else None
                if not decoded:
                    continue
                guild_id = self._pal_guid_display(group_id)
                admin_uid = self._normalise_decoded_player_guid(decoded.get("admin_uid"))
                members = []
                for member in decoded.get("players", []):
                    raw_uid = member.get("uid", "")
                    display_uid = self._pal_guid_display(raw_uid)
                    uid_key = self._normalise_player_guid(display_uid)
                    player = players_by_uid.get(uid_key, {})
                    role_number = int(member.get("role", 3) or 3)
                    role = {1: "Guild Master", 2: "Submaster",
                            3: "Member", 4: "Guest"}.get(
                                role_number, f"?{role_number}")
                    is_leader = uid_key == admin_uid or role_number == 1
                    members.append({
                        "name": member.get("name") or player.get("name")
                                or "Unnamed Survivor",
                        "seen": player.get("seen")
                                or self._format_last_seen(member.get("last_online")),
                        "level": player.get("level", 1),
                        "pals": player.get("pals", 0),
                        "uid": display_uid,
                        "role": role,
                        "role_number": role_number,
                        "is_leader": is_leader,
                    })
                if members and not any(m["is_leader"] for m in members):
                    members[0]["is_leader"] = True
                guilds.append({
                    "name": decoded.get("guild_name") or "Unnamed Guild",
                    "id": guild_id,
                    "level": decoded.get("base_camp_level", 1),
                    "members": members,
                })
        except Exception:
            guilds = []
        self.guild_search_rows = guilds
        self.guild_member_rows = []
        self._render_guild_search_rows()
        self._render_guild_member_rows()

    @staticmethod
    def _guild_filter_text(variable):
        query = variable.get().strip().lower()
        return "" if query == "type to search..." else query

    def _render_guild_search_rows(self):
        if not hasattr(self, "guilds_tree"):
            return
        query = self._guild_filter_text(self.guild_search_var)
        rows = [row for row in self.guild_search_rows
                if not query or query in " ".join(
                    str(row.get(key, "")).lower()
                    for key in ("name", "id", "level"))]
        key = self.guild_sort_column
        rows.sort(key=lambda row: (
            int(row.get(key, 0)) if key == "level"
            and str(row.get(key, "")).isdigit()
            else str(row.get(key, "")).lower()),
            reverse=self.guild_sort_reverse)
        self.guilds_tree.delete(*self.guilds_tree.get_children())
        self.guild_search_lookup.clear()
        for row in rows:
            item = self.guilds_tree.insert(
                "", "end", values=(row["name"], row["id"], row["level"]))
            self.guild_search_lookup[item] = row

    def _render_guild_member_rows(self):
        if not hasattr(self, "guild_members_tree"):
            return
        query = self._guild_filter_text(self.guild_member_search_var)
        rows = [row for row in self.guild_member_rows
                if not query or query in " ".join(
                    str(value).lower() for value in row.values())]
        key = self.guild_member_sort_column
        numeric = key in {"level", "pals", "role_number"}
        rows.sort(key=lambda row: (
            int(row.get(key, 0)) if numeric
            and str(row.get(key, "")).isdigit()
            else str(row.get(key, "")).lower()),
            reverse=self.guild_member_sort_reverse)
        self.guild_members_tree.delete(*self.guild_members_tree.get_children())
        self.guild_member_lookup.clear()
        for row in rows:
            name = f"[L]{row['name']}" if row.get("is_leader") else row["name"]
            item = self.guild_members_tree.insert(
                "", "end", values=(name, row["seen"], row["level"],
                                    row["pals"], row["uid"], row["role"]))
            self.guild_member_lookup[item] = row

    def _sort_guild_search(self, column):
        if self.guild_sort_column == column:
            self.guild_sort_reverse = not self.guild_sort_reverse
        else:
            self.guild_sort_column, self.guild_sort_reverse = column, False
        self._render_guild_search_rows()

    def _sort_guild_members(self, column):
        sort_key = "role_number" if column == "role" else column
        if self.guild_member_sort_column == sort_key:
            self.guild_member_sort_reverse = not self.guild_member_sort_reverse
        else:
            self.guild_member_sort_column = sort_key
            self.guild_member_sort_reverse = False
        self._render_guild_member_rows()

    def _on_guild_search_selected(self, _event=None):
        selected = self.guilds_tree.selection()
        guild = self.guild_search_lookup.get(selected[0]) if selected else None
        self.guild_member_rows = list(guild.get("members", [])) if guild else []
        self._render_guild_member_rows()

    def _on_guild_member_selected(self, _event=None):
        selected = self.guild_members_tree.selection()
        member = self.guild_member_lookup.get(selected[0]) if selected else None
        if member:
            self._set_profile_player_name(member.get("name"))

    def _open_guild_member(self, event=None):
        if event is not None and hasattr(event, "y"):
            item = self.guild_members_tree.identify_row(event.y)
            if item:
                self.guild_members_tree.selection_set(item)
                self.guild_members_tree.focus(item)
        selected = self.guild_members_tree.selection()
        member = self.guild_member_lookup.get(selected[0]) if selected else None
        if not member:
            return "break"
        target_uid = self._normalise_player_guid(member.get("uid"))
        for item, player in self.player_search_lookup.items():
            if self._normalise_player_guid(player.get("uid")) == target_uid:
                self.players_tree.selection_set(item)
                self.players_tree.focus(item)
                return self._open_selected_search_player()
        return "break"

    def _build_bases(self, parent):
        frame = tk.Frame(parent, bg=COLOR["bg0"])
        self.base_search_rows = []
        self.base_search_lookup = {}
        self.base_search_sort_column, self.base_search_sort_reverse = "base_id", False

        shell = tk.Frame(frame, bg=COLOR["bg0"], highlightthickness=1,
                         highlightbackground=COLOR["line_strong"])
        shell.pack(fill="both", expand=True, padx=18, pady=20)

        top = tk.Frame(shell, bg=COLOR["bg0"])
        top.pack(fill="x", pady=(0, 10))
        tk.Label(top, text="Search Bases:", bg="#12222c", fg=COLOR["accent"],
                 font=("Segoe UI", 9, "bold"), padx=12, pady=8,
                 highlightthickness=1,
                 highlightbackground=COLOR["line_strong"]).pack(
                     side="left", padx=(0, 18))
        self.base_search_var = tk.StringVar()
        entry = tk.Entry(top, textvariable=self.base_search_var,
                         bg=COLOR["bg1"], fg=COLOR["text1"],
                         insertbackground=COLOR["accent"], relief="flat", bd=0,
                         highlightthickness=1, highlightbackground=COLOR["line"],
                         highlightcolor=COLOR["line_strong"],
                         font=("Segoe UI", 9))
        entry.pack(side="left", fill="x", expand=True, ipady=8)
        entry.insert(0, "Type to search...")
        entry.bind("<FocusIn>", lambda e: entry.delete(0, "end")
                   if entry.get() == "Type to search..." else None)
        entry.bind("<FocusOut>", lambda e: entry.insert(0, "Type to search...")
                   if not entry.get() else None)
        self.base_search_var.trace_add(
            "write", lambda *_: self._render_base_search_rows())

        self.bases_tree = self._build_guild_tree(
            shell,
            (("base_id", "Base ID", 340), ("guild_id", "Guild ID", 340),
             ("guild_name", "Guild Name", 300),
             ("guild_level", "Guild Level", 170)),
            self._sort_base_search,
        )
        self.bases_tree.bind("<<TreeviewSelect>>", self._on_base_search_selected)
        self.bases_tree.bind("<Double-Button-1>", self._open_selected_base)
        self.bases_tree.bind("<Return>", self._open_selected_base)
        self.bases_tree.bind(
            "<Button-3>",
            lambda event: self._show_add_exclusion_menu(
                event, "bases", self.bases_tree,
                self.base_search_lookup, "base_id"))
        self.bases_tree.bind(
            "<Button-2>",
            lambda event: self._show_add_exclusion_menu(
                event, "bases", self.bases_tree,
                self.base_search_lookup, "base_id"))
        return frame

    def search_bases(self):
        if not getattr(self, "loaded_sav_json", None):
            return
        rows = []
        try:
            world = next(x for x in self.loaded_sav_json.get("properties", [])
                         if x.get("name") == "worldSaveData")
            fields = world["value"].get("_fields", [])
            bcs = _find_field(fields, "BaseCampSaveData")
            known_bases = {}
            if bcs and isinstance(bcs.get("value"), dict):
                encoded = bcs["value"].get("_raw_b64")
                if encoded:
                    for base_id, base_fields in _decode_guid_keyed_struct_map(
                            base64.b64decode(encoded)):
                        raw_data = _rawdata_bytes(base_fields)
                        decoded = decode_base_camp_raw(raw_data) if raw_data else None
                        if decoded:
                            known_bases[base_id] = decoded

            gsm = _find_field(fields, "GroupSaveDataMap")
            encoded = gsm.get("value", {}).get("_raw_b64") if gsm else None
            if encoded:
                for group_id, group_fields in _decode_guid_keyed_struct_map(
                        base64.b64decode(encoded)):
                    group_type = _find_field(group_fields, "GroupType")
                    if not group_type or group_type.get("value") not in (
                            "EPalGroupType::Guild",
                            "EPalGroupType::IndependentGuild"):
                        continue
                    raw_data = _rawdata_bytes(group_fields)
                    guild = decode_group_raw(
                        raw_data, group_type.get("value")) if raw_data else None
                    if not guild:
                        continue
                    guild_id = self._pal_guid_display(group_id)
                    guild_name = guild.get("guild_name") or "Unnamed Guild"
                    guild_level = guild.get("base_camp_level", 1)
                    for base_id in guild.get("base_ids", []):
                        base = known_bases.get(base_id, {})
                        rows.append({
                            "base_id": self._pal_guid_display(base_id),
                            "guild_id": guild_id,
                            "guild_name": guild_name,
                            "guild_level": guild_level,
                            "base_name": base.get("name") or "Base Camp",
                        })
        except Exception:
            rows = []
        self.base_search_rows = rows
        self._render_base_search_rows()

    def _render_base_search_rows(self):
        if not hasattr(self, "bases_tree"):
            return
        query = self._guild_filter_text(self.base_search_var)
        rows = [row for row in self.base_search_rows
                if not query or query in " ".join(
                    str(row.get(key, "")).lower()
                    for key in ("base_id", "guild_id", "guild_name",
                                "guild_level", "base_name"))]
        key = self.base_search_sort_column
        rows.sort(key=lambda row: (
            int(row.get(key, 0)) if key == "guild_level"
            and str(row.get(key, "")).isdigit()
            else str(row.get(key, "")).lower()),
            reverse=self.base_search_sort_reverse)
        self.bases_tree.delete(*self.bases_tree.get_children())
        self.base_search_lookup.clear()
        for row in rows:
            item = self.bases_tree.insert(
                "", "end",
                values=(row["base_id"], row["guild_id"],
                        row["guild_name"], row["guild_level"]))
            self.base_search_lookup[item] = row

    def _sort_base_search(self, column):
        if self.base_search_sort_column == column:
            self.base_search_sort_reverse = not self.base_search_sort_reverse
        else:
            self.base_search_sort_column = column
            self.base_search_sort_reverse = False
        self._render_base_search_rows()

    def _on_base_search_selected(self, _event=None):
        selected = self.bases_tree.selection()
        row = self.base_search_lookup.get(selected[0]) if selected else None
        if row:
            self.base_guild_var.set(row.get("guild_name", ""))
            self.base_base_var.set(row.get("base_name", ""))

    def _open_selected_base(self, event=None):
        if event is not None and hasattr(event, "y"):
            item = self.bases_tree.identify_row(event.y)
            if item:
                self.bases_tree.selection_set(item)
                self.bases_tree.focus(item)
        selected = self.bases_tree.selection()
        row = self.base_search_lookup.get(selected[0]) if selected else None
        if not row:
            return "break"
        self.base_guild_var.set(row.get("guild_name", ""))
        self.base_base_var.set(row.get("base_name", ""))
        self.select_nav("base_inventory")
        self.render_base_inventory()
        return "break"

