    def _auto_locate_map_assets(self):
        if not PIL_AVAILABLE:
            return
        candidate_dir_names = ["Palworld_Map_Assets", "palworld_map_assets"]
        search_roots = []
        try:
            search_roots.append(os.path.dirname(os.path.abspath(__file__)))
        except NameError:
            pass
        search_roots.append(os.getcwd())

        for root in search_roots:
            for name in candidate_dir_names:
                candidate = os.path.join(root, name)
                if os.path.isdir(candidate) and os.path.isfile(
                        os.path.join(candidate, "T_WorldMap.webp")):
                    self.map_image_dir = candidate
                    self._map_bg_image_cache.clear()
                    self._map_icon_cache.clear()
                    self.map_folder_status.configure(
                        text=f"Map image loaded ({name})", fg=COLOR["good"])
                    return

    def set_map_image_dir(self):
        if not PIL_AVAILABLE:
            messagebox.showerror("Pillow not installed",
                                  "This feature needs the Pillow library to load and resize "
                                  "images. Install it with:\n\npip install Pillow\n\nthen "
                                  "restart the app.")
            return
        path = filedialog.askdirectory(title="Choose your map assets folder")
        if not path:
            return
        self.map_image_dir = path
        self._map_bg_image_cache.clear()
        self._map_icon_cache.clear()
        found = self._load_map_bg_image() is not None
        self.map_folder_status.configure(
            text=f"Map image loaded ({os.path.basename(path)})" if found
                 else f"No T_WorldMap.webp found in {os.path.basename(path)}",
            fg=COLOR["good"] if found else COLOR["warn"])
        self.render_map_canvas()

    def _load_map_bg_image(self):
        if not PIL_AVAILABLE or not self.map_image_dir:
            return None
        if "T_WorldMap.webp" in self._map_bg_image_cache:
            return self._map_bg_image_cache["T_WorldMap.webp"]
        for name in ("T_WorldMap.webp", "T_WorldMap.png", "T_WorldMap.jpg"):
            path = os.path.join(self.map_image_dir, name)
            if os.path.isfile(path):
                try:
                    img = Image.open(path).convert("RGB")
                except Exception:
                    img = None
                self._map_bg_image_cache["T_WorldMap.webp"] = img
                return img
        self._map_bg_image_cache["T_WorldMap.webp"] = None
        return None

    def _get_map_icon(self, filename, size):
        if not PIL_AVAILABLE or not self.map_image_dir:
            return None
        cache_key = (filename, size)
        if cache_key in self._map_icon_cache:
            return self._map_icon_cache[cache_key]
        path = os.path.join(self.map_image_dir, filename)
        photo = None
        if os.path.isfile(path):
            try:
                img = Image.open(path).convert("RGBA")
                img.thumbnail((size, size), Image.LANCZOS)
                photo = ImageTk.PhotoImage(img)
            except Exception:
                photo = None
        self._map_icon_cache[cache_key] = photo
        return photo

    _COORD_TRANSL_X = 375247.0
    _COORD_TRANSL_Y = -18.0
    _COORD_SCALE = 725.0
    _COORD_RANGE = 1000.0  # the transformed "map space" coordinate's usable +/- range

    def _world_to_texture_px(self, wx, wy, tex_w, tex_h):
        map_x = (wy - self._COORD_TRANSL_Y) / self._COORD_SCALE
        map_y = (wx + self._COORD_TRANSL_X) / self._COORD_SCALE
        px = (map_x + self._COORD_RANGE) / (2 * self._COORD_RANGE) * tex_w
        py = (self._COORD_RANGE - map_y) / (2 * self._COORD_RANGE) * tex_h
        return px, py

    def load_map_data(self):
        if getattr(self, "loaded_sav_json", None):
            source_id = id(self.loaded_sav_json)
            if getattr(self, "_map_entries_source_id", None) != source_id:
                self.map_entries = build_map_entries_from_json(self.loaded_sav_json)
                self._map_entries_source_id = source_id
        else:
            self.map_entries = {"players": [], "bases": [], "guilds": [],
                                 "bases_available": False, "guilds_available": False}
            self._map_entries_source_id = None
        if hasattr(self, "map_tree"):
            self.render_map_list()
            self.render_map_canvas()

    def _toggle_map_layer(self, key):
        self.map_layer_vars[key] = not self.map_layer_vars[key]
        btn = self.map_layer_buttons[key]
        active = self.map_layer_vars[key]
        btn.configure(bg=COLOR["accent_dim"] if active else COLOR["bg2"],
                      fg=COLOR["accent"] if active else COLOR["text1"])
        self.render_map_canvas()

    def select_map_mode(self, key):
        self.map_mode = key
        for k, b in self.map_mode_buttons.items():
            b.configure(bg=COLOR["accent"] if k == key else COLOR["bg2"],
                        fg="#ffffff" if k == key else COLOR["text1"])
        self.render_map_list()

    def map_reset_view(self):
        if self._map_zoom_anim_id:
            self.after_cancel(self._map_zoom_anim_id)
            self._map_zoom_anim_id = None
        c = self.map_canvas
        w = c.winfo_width() or 800
        h = c.winfo_height() or 600
        fit_span = 1_200_000.0
        fit_zoom = min(w, h) / fit_span * 0.95
        self.map_zoom = max(0.0005, fit_zoom)
        self.map_pan_x = w / 2
        self.map_pan_y = h / 2
        self._disp_zoom, self._disp_pan_x, self._disp_pan_y = (
            self.map_zoom, self.map_pan_x, self.map_pan_y)
        self.render_map_canvas()

    def _map_pan_start(self, event):
        self._map_drag_start = (event.x, event.y, self.map_pan_x, self.map_pan_y)
        self._map_last_drag_pos = (event.x, event.y)
        if self._map_settle_after_id:
            self.after_cancel(self._map_settle_after_id)
            self._map_settle_after_id = None

    def _map_pan_move(self, event):
        if not self._map_drag_start:
            return
        sx, sy, ox, oy = self._map_drag_start
        self.map_pan_x = ox + (event.x - sx)
        self.map_pan_y = oy + (event.y - sy)
        self._disp_pan_x, self._disp_pan_y = self.map_pan_x, self.map_pan_y
        lx, ly = self._map_last_drag_pos
        self.map_canvas.move("all", event.x - lx, event.y - ly)
        self._map_last_drag_pos = (event.x, event.y)
        if self._map_settle_after_id:
            self.after_cancel(self._map_settle_after_id)
        self._map_settle_after_id = self.after(120, self._map_pan_settle)

    def _map_pan_end(self, event):
        self._map_drag_start = None
        if self._map_settle_after_id:
            self.after_cancel(self._map_settle_after_id)
            self._map_settle_after_id = None
        self._map_pan_settle()

    def _map_pan_settle(self):
        self._map_settle_after_id = None
        self.render_map_canvas()

    def _map_mouse_move(self, event):
        wx, wy = self._map_canvas_to_world(event.x, event.y)
        self.map_coords_label.configure(text=f"Cursor Coords: {wx:.0f}, {wy:.0f}")

    def _map_zoom_wheel(self, event, direction=None):
        import time as _time
        now = _time.monotonic()
        if now - getattr(self, "_map_last_zoom_time", 0) < 0.03:
            return
        self._map_last_zoom_time = now

        if direction is not None:
            delta = direction
        else:
            delta = 1 if event.delta > 0 else -1

        cx, cy = event.x, event.y
        world_x, world_y = self._map_canvas_to_world(cx, cy)

        self.map_zoom = max(0.0002, min(8.0, self.map_zoom * (1.08 if delta > 0 else 1 / 1.08)))
        self.map_pan_x = cx - world_x * self.map_zoom
        self.map_pan_y = cy - world_y * self.map_zoom
        self._map_start_zoom_animation()

    def _map_start_zoom_animation(self):
        if self._map_zoom_anim_id is None:
            self._map_zoom_anim_tick()

    def _map_zoom_anim_tick(self):
        alpha = 0.35
        dz = self.map_zoom - self._disp_zoom
        dpx = self.map_pan_x - self._disp_pan_x
        dpy = self.map_pan_y - self._disp_pan_y
        close_enough = (abs(dz) < self.map_zoom * 0.002 and abs(dpx) < 0.5 and abs(dpy) < 0.5)

        if close_enough:
            self._disp_zoom, self._disp_pan_x, self._disp_pan_y = (
                self.map_zoom, self.map_pan_x, self.map_pan_y)
            self._map_zoom_anim_id = None
            self.render_map_canvas(fast=False)
            return

        self._disp_zoom += dz * alpha
        self._disp_pan_x += dpx * alpha
        self._disp_pan_y += dpy * alpha
        self.render_map_canvas(fast=True)
        self._map_zoom_anim_id = self.after(16, self._map_zoom_anim_tick)

    def _map_canvas_to_world(self, cx, cy):
        wx = (cx - self._disp_pan_x) / self._disp_zoom
        wy = (cy - self._disp_pan_y) / self._disp_zoom
        return wx, wy

    def _map_world_to_canvas(self, wx, wy):
        return wx * self._disp_zoom + self._disp_pan_x, wy * self._disp_zoom + self._disp_pan_y

    def render_map_canvas(self, fast=False):
        c = self.map_canvas
        c.delete("all")
        w = c.winfo_width() or 800
        h = c.winfo_height() or 600
        if w <= 1 or h <= 1:
            return

        bg_img = self._load_map_bg_image()

        if bg_img is not None:
            tex_w, tex_h = bg_img.size
            def to_tex(sx, sy):
                wx, wy = self._map_canvas_to_world(sx, sy)
                return self._world_to_texture_px(wx, wy, tex_w, tex_h)

            px0, py0 = to_tex(0, 0)
            px1, py1 = to_tex(1, 0)
            px2, py2 = to_tex(0, 1)
            a, d = px1 - px0, py1 - py0
            b, e = px2 - px0, py2 - py0
            coeffs = (a, b, px0, d, e, py0)
            try:
                resample = Image.NEAREST if fast else Image.BILINEAR
                rendered = bg_img.transform((int(w), int(h)), Image.AFFINE, coeffs,
                                             resample=resample, fillcolor=(5, 10, 16))
                self._map_bg_photo = ImageTk.PhotoImage(rendered)
                c.create_image(0, 0, image=self._map_bg_photo, anchor="nw")
            except Exception:
                bg_img = None

        if bg_img is None:
            x0, y0 = self._map_canvas_to_world(0, 0)
            x1, y1 = self._map_canvas_to_world(w, h)
            step = 1000
            start_x = int(x0 // step) * step
            start_y = int(y0 // step) * step
            gx = start_x
            while gx <= x1:
                sx, _ = self._map_world_to_canvas(gx, 0)
                major = (gx % (step * 5) == 0)
                c.create_line(sx, 0, sx, h, fill=COLOR["line"] if not major else COLOR["line_strong"], width=1)
                if major:
                    c.create_text(sx + 4, 4, text=str(gx), fill=COLOR["text2"], font=("Consolas", 7), anchor="nw")
                gx += step
            gy = start_y
            while gy <= y1:
                _, sy = self._map_world_to_canvas(0, gy)
                major = (gy % (step * 5) == 0)
                c.create_line(0, sy, w, sy, fill=COLOR["line"] if not major else COLOR["line_strong"], width=1)
                if major:
                    c.create_text(4, sy + 4, text=str(gy), fill=COLOR["text2"], font=("Consolas", 7), anchor="nw")
                gy += step

        ox, oy = self._map_world_to_canvas(0, 0)
        c.create_oval(ox - 4, oy - 4, ox + 4, oy + 4, outline=COLOR["accent"], width=1.5)

        plottable = []
        if self.map_layer_vars.get("players"):
            plottable += [("players", p) for p in self.map_entries.get("players", []) if p.get("x") is not None]
        if self.map_layer_vars.get("bases"):
            plottable += [("bases", b) for b in self.map_entries.get("bases", []) if b.get("x") is not None]

        self._map_marker_photos = []
        for kind, entry in plottable:
            sx, sy = self._map_world_to_canvas(entry["x"], entry["y"])
            selected = self.map_selected is entry
            icon_file = "playericon.webp" if kind == "players" else "baseicon.webp"
            icon = self._get_map_icon(icon_file, 28 if selected else 22)
            if icon is not None:
                c.create_image(sx, sy, image=icon, anchor="center")
                self._map_marker_photos.append(icon)  # keep a reference alive
                if selected:
                    r = 16
                    c.create_oval(sx - r, sy - r, sx + r, sy + r, outline=COLOR["accent"], width=2)
            else:
                r = 6 if selected else 4
                c.create_oval(sx - r, sy - r, sx + r, sy + r,
                              fill=COLOR["accent"] if selected else COLOR["gold"],
                              outline="#ffffff", width=1.5)

        if not plottable:
            c.create_text(w / 2, h / 2, justify="center", fill=COLOR["text2"],
                          font=("Segoe UI", 10),
                          text="No plottable base/player positions in this save yet.\n"
                               "Pan and zoom still work -- markers will appear here once\n"
                               "world-position data can be read from the save.")

        self.map_zoom_label.configure(text=f"Zoom: {self._disp_zoom * 100:.0f}%")

    def render_map_list(self):
        tree = self.map_tree
        tree.delete(*tree.get_children())

        if self.map_mode == "bases":
            tree.configure(columns=("guild", "leader", "seen", "bases"))
            for col, text, w in (("guild", "Guild Name", 100), ("leader", "Leader", 90),
                                  ("seen", "Last Seen", 70), ("bases", "Bases", 50)):
                tree.heading(col, text=text)
                tree.column(col, width=w, anchor="w")
            if not self.map_entries.get("guilds_available") and not self.map_entries.get("bases_available"):
                tree.insert("", "end", values=("Not available yet", "", "", ""))
                self.map_detail_bar.configure(
                    text="Guild/base data isn't decoded by this app yet -- GroupSaveDataMap and "
                         "BaseCampSaveData use a more complex format than the item/pal records this "
                         "tool already reads.")
                return
            query = self.map_search_var.get().strip().lower()
            if query.startswith("type to search"):
                query = ""
            guilds = self.map_entries.get("guilds", [])
            matches = [g for g in guilds if not query or query in g["name"].lower()
                       or query in (g.get("leader") or "").lower()]
            if not matches:
                tree.insert("", "end", values=("No guilds found", "", "", ""))
                return
            self._map_tree_entry_lookup = getattr(self, "_map_tree_entry_lookup", {})
            for g in matches:
                iid = tree.insert("", "end", values=(g["name"], g.get("leader") or "\u2014",
                                                       "\u2014", g.get("base_count", 0)))
                self._map_tree_entry_lookup[iid] = g
        else:
            tree.configure(columns=("name", "level", "guild", "seen"))
            for col, text, w in (("name", "Player", 110), ("level", "Lv.", 40),
                                  ("guild", "Guild", 90), ("seen", "Last Seen", 70)):
                tree.heading(col, text=text)
                tree.column(col, width=w, anchor="w")
            query = self.map_search_var.get().strip().lower()
            if query.startswith("type to search"):
                query = ""
            players = self.map_entries.get("players", [])
            matches = [p for p in players if not query or query in p["name"].lower()]
            if not matches:
                tree.insert("", "end", values=("No players found", "", "", ""))
                return
            for p in matches:
                iid = tree.insert("", "end", values=(p["name"], p["level"],
                                                       p.get("guild") or "\u2014", "\u2014"))
                tree.set(iid, "name", p["name"])
                tree.item(iid, tags=(str(id(p)),))
                self._map_tree_entry_lookup = getattr(self, "_map_tree_entry_lookup", {})
                self._map_tree_entry_lookup[iid] = p

    def _map_tree_select(self, _event=None):
        sel = self.map_tree.selection()
        if not sel:
            return
        entry = getattr(self, "_map_tree_entry_lookup", {}).get(sel[0])
        if not entry:
            return
        self.map_selected = entry
        if self.map_mode == "players":
            self.map_result_cards["player"].configure(text=entry["name"])
            self.map_result_cards["guild"].configure(text=entry.get("guild") or "N/A")
            self.map_detail_bar.configure(
                text=f"{entry['name']} \u2014 Level {entry['level']}"
                     + ("" if entry.get("x") is not None else
                        "\n(no world-position data available for this entry)"))
        else:
            self.map_result_cards["guild"].configure(text=entry["name"])
            self.map_result_cards["player"].configure(text=entry.get("leader") or "N/A")
            base_word = "base" if entry.get("base_count") == 1 else "bases"
            self.map_result_cards["base"].configure(
                text=f"{entry.get('base_count', 0)} {base_word}" if entry.get("base_count") else "N/A")
            self.map_detail_bar.configure(
                text=f"{entry['name']} \u2014 led by {entry.get('leader') or 'unknown'}, "
                     f"{entry.get('player_count', 0)} member(s), {entry.get('base_count', 0)} base(s)"
                     + ("" if entry.get("x") is not None else
                        "\n(this guild's base location couldn't be resolved)"))
            if entry.get("x") is not None:
                w = self.map_canvas.winfo_width() or 800
                h = self.map_canvas.winfo_height() or 600
                self.map_zoom = max(self.map_zoom, 0.05)
                self.map_pan_x = w / 2 - entry["x"] * self.map_zoom
                self.map_pan_y = h / 2 - entry["y"] * self.map_zoom
                self._disp_zoom, self._disp_pan_x, self._disp_pan_y = (
                    self.map_zoom, self.map_pan_x, self.map_pan_y)
        self.render_map_canvas()

    def _exclusions_file_path(self):
        appdata = os.environ.get("APPDATA") or str(Path.home())
        return Path(appdata) / "PalworldSaveTools" / "configs" / "deletion_exclusions.json"

    def _load_exclusions(self):
        data = {"players": [], "guilds": [], "bases": []}
        path = self._exclusions_file_path()
        try:
            loaded = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                for kind in data:
                    values = loaded.get(kind, [])
                    if isinstance(values, list):
                        data[kind] = [str(value) for value in values if str(value)]
        except (OSError, ValueError, TypeError):
            pass
        self.exclusions = data
        return data

    def _save_exclusions(self):
        path = self._exclusions_file_path()
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(
                json.dumps(self.exclusions, indent=2, ensure_ascii=False),
                encoding="utf-8")
        except OSError as error:
            messagebox.showerror(
                "Save exclusions failed", f"{type(error).__name__}: {error}")
            return False
        return True

    def _build_exclusions(self, parent):
        frame = tk.Frame(parent, bg=COLOR["bg0"])
        self._load_exclusions()
        self.exclusion_search_vars = {}
        self.exclusion_trees = {}
        self.exclusion_sort_reverse = {
            "players": False, "guilds": False, "bases": False}
        body = tk.Frame(frame, bg=COLOR["bg0"])
        body.pack(fill="both", expand=True, padx=18, pady=20)
        for column in range(3):
            body.grid_columnconfigure(column, weight=1, uniform="exclusions")
        body.grid_rowconfigure(0, weight=1)
        definitions = (
            ("players", "Excluded Player UIDs:", "Excluded Player UID"),
            ("guilds", "Excluded Guild IDs:", "Excluded Guild ID"),
            ("bases", "Excluded Base IDs:", "Excluded Bases"),
        )
        for column, (kind, title, heading) in enumerate(definitions):
            panel = tk.Frame(body, bg=COLOR["bg0"])
            panel.grid(
                row=0, column=column, sticky="nsew",
                padx=(0 if column == 0 else 5, 0 if column == 2 else 5))
            header = tk.Frame(panel, bg=COLOR["bg0"])
            header.pack(fill="x", pady=(0, 10))
            tk.Label(
                header, text=title, bg="#12222c", fg=COLOR["accent"],
                font=("Segoe UI", 9, "bold"), padx=12, pady=8,
                highlightthickness=1,
                highlightbackground=COLOR["line_strong"],
            ).pack(side="left", padx=(0, 18))
            variable = tk.StringVar()
            self.exclusion_search_vars[kind] = variable
            entry = tk.Entry(
                header, textvariable=variable, bg=COLOR["bg1"],
                fg=COLOR["text1"], insertbackground=COLOR["accent"],
                relief="flat", bd=0, highlightthickness=1,
                highlightbackground=COLOR["line"],
                highlightcolor=COLOR["line_strong"], font=("Segoe UI", 9))
            entry.pack(side="left", fill="x", expand=True, ipady=8)
            entry.insert(0, "Type to search...")
            entry.bind(
                "<FocusIn>",
                lambda event, widget=entry:
                widget.delete(0, "end")
                if widget.get() == "Type to search..." else None)
            entry.bind(
                "<FocusOut>",
                lambda event, widget=entry:
                widget.insert(0, "Type to search...")
                if not widget.get() else None)
            variable.trace_add(
                "write", lambda *_args, category=kind:
                self._render_exclusion_rows(category))
            table = tk.Frame(
                panel, bg=COLOR["bg1"], highlightthickness=1,
                highlightbackground=COLOR["line"])
            table.pack(fill="both", expand=True)
            tree = ttk.Treeview(
                table, columns=("value",), show="headings", selectmode="browse")
            tree.heading(
                "value", text=heading,
                command=lambda category=kind:
                self._sort_exclusions(category))
            tree.column("value", anchor="center", stretch=True, minwidth=220)
            scroll = ttk.Scrollbar(
                table, orient="vertical", command=tree.yview)
            tree.configure(yscrollcommand=scroll.set)
            tree.pack(side="left", fill="both", expand=True)
            scroll.pack(side="right", fill="y")
            tree.bind(
                "<Button-3>",
                lambda event, category=kind:
                self._show_exclusion_context_menu(event, category))
            tree.bind(
                "<Button-2>",
                lambda event, category=kind:
                self._show_exclusion_context_menu(event, category))
            tree.bind(
                "<Delete>",
                lambda event, category=kind:
                self._remove_selected_exclusion(category))
            self.exclusion_trees[kind] = tree
        self._refresh_exclusions()
        return frame

    def _refresh_exclusions(self):
        if not hasattr(self, "exclusion_trees"):
            return
        self._load_exclusions()
        for kind in ("players", "guilds", "bases"):
            self._render_exclusion_rows(kind)

    def _render_exclusion_rows(self, kind):
        tree = getattr(self, "exclusion_trees", {}).get(kind)
        if tree is None:
            return
        tree.delete(*tree.get_children())
        query = self.exclusion_search_vars[kind].get().strip().casefold()
        if query == "type to search...":
            query = ""
        values = list(self.exclusions.get(kind, []))
        values.sort(key=str.casefold, reverse=self.exclusion_sort_reverse[kind])
        for value in values:
            if not query or query in value.casefold():
                tree.insert("", "end", values=(value,))

    def _sort_exclusions(self, kind):
        self.exclusion_sort_reverse[kind] = not self.exclusion_sort_reverse[kind]
        self._render_exclusion_rows(kind)

    def _show_exclusion_context_menu(self, event, kind):
        tree = self.exclusion_trees[kind]
        row = tree.identify_row(event.y)
        if not row:
            return
        tree.selection_set(row)
        tree.focus(row)
        value = str(tree.item(row, "values")[0])
        menu = tk.Menu(
            self, tearoff=0, bg=COLOR["bg2"], fg=COLOR["text0"],
            activebackground=COLOR["danger_dim"], activeforeground="#ffffff")
        menu.add_command(
            label="Remove Exclusion",
            command=lambda: self._remove_exclusion(kind, value))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _remove_selected_exclusion(self, kind):
        tree = self.exclusion_trees[kind]
        selected = tree.selection()
        if selected:
            self._remove_exclusion(
                kind, str(tree.item(selected[0], "values")[0]))
        return "break"

    def _add_exclusion(self, kind, value):
        value = str(value or "").strip()
        if not value:
            return
        values = self.exclusions.setdefault(kind, [])
        normalized = value.replace("-", "").casefold()
        if any(
                existing.replace("-", "").casefold() == normalized
                for existing in values):
            messagebox.showinfo(
                "Already Excluded", f"{value} is already in the exclusion list.")
            return
        values.append(value)
        if self._save_exclusions():
            self._refresh_exclusions()

    def _remove_exclusion(self, kind, value):
        values = self.exclusions.setdefault(kind, [])
        normalized = str(value).replace("-", "").casefold()
        match = next(
            (existing for existing in values
             if existing.replace("-", "").casefold() == normalized), None)
        if match is not None:
            values.remove(match)
            if self._save_exclusions():
                self._refresh_exclusions()

    def _show_add_exclusion_menu(self, event, kind, tree, lookup, key):
        row_id = tree.identify_row(event.y)
        if not row_id:
            return
        tree.selection_set(row_id)
        tree.focus(row_id)
        row = lookup.get(row_id, {})
        value = row.get(key)
        if not value:
            return
        menu = tk.Menu(
            self, tearoff=0, bg=COLOR["bg2"], fg=COLOR["text0"],
            activebackground=COLOR["accent_dim"], activeforeground="#ffffff")
        menu.add_command(
            label="Add to Exclusions",
            command=lambda: self._add_exclusion(kind, value))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

