    def _load_breeding_data(self):
        if self.breeding_data is not None:
            return self.breeding_data
        self._locate_technology_icon_source()
        try:
            if getattr(self, "_technology_icon_root", None):
                path = self._technology_icon_root / "breedingdata.json"
                self.breeding_data = json.loads(path.read_text(encoding="utf-8"))
            elif getattr(self, "_technology_icon_zip", None):
                member = next(
                    name for name in self._technology_icon_zip.namelist()
                    if name.replace("\\", "/").endswith(
                        "/resources/game_data/breedingdata.json"))
                self.breeding_data = json.loads(
                    self._technology_icon_zip.read(member).decode("utf-8"))
            else:
                self.breeding_data = {}
        except (OSError, KeyError, StopIteration, UnicodeError, ValueError):
            self.breeding_data = {}
        if not self.breeding_data:
            self.breeding_hint.configure(
                text="Breeding data was not found in PalworldSaveTools-2.2.1.zip.")
        return self.breeding_data

    def _set_breeding_mode(self, mode):
        self.breeding_mode = mode
        self.breeding_page = 0
        for key, button in self.breeding_mode_buttons.items():
            button.configure(fg=COLOR["accent"] if key == mode else "#94a3b8")
        self.breeding_tab_line.place_configure(x=2 if mode == "parents" else 78)
        self._render_breeding_results()

    def _open_breeding_pal_picker_table(self):
        data = self._load_breeding_data()
        info = data.get("pal_info", {}) if data else {}
        if not info:
            messagebox.showwarning(
                "Breeding data unavailable",
                "The breeding database could not be loaded from the supplied source.")
            return
        dialog = tk.Toplevel(self)
        dialog.title("Select a Pal")
        dialog.configure(bg=COLOR["bg0"])
        dialog.geometry("680x650")
        dialog.transient(self)
        dialog.grab_set()
        search_var = tk.StringVar()
        search = tk.Entry(
            dialog, textvariable=search_var, bg=COLOR["bg1"],
            fg=COLOR["text1"], insertbackground=COLOR["accent"],
            relief="flat", bd=0, highlightthickness=1,
            highlightbackground=COLOR["line"], font=("Segoe UI", 10))
        search.pack(fill="x", padx=16, pady=16, ipady=8)
        wrap = tk.Frame(dialog, bg=COLOR["bg1"])
        wrap.pack(fill="both", expand=True, padx=16, pady=(0, 16))
        tree = ttk.Treeview(
            wrap, columns=("name", "id"), show="headings", selectmode="browse")
        tree.heading("name", text="Pal")
        tree.heading("id", text="Internal ID")
        tree.column("name", width=330, anchor="w")
        tree.column("id", width=270, anchor="w")
        scroll = ttk.Scrollbar(wrap, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=scroll.set)
        tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        lookup = {}

        def populate(*_args):
            query = search_var.get().strip().casefold()
            tree.delete(*tree.get_children())
            lookup.clear()
            unique_children = {
                combo.get("child") for combo in data.get("unique_combos", [])}
            rows = []
            for tribe, pal in info.items():
                if pal.get("ignore_combi") and tribe not in unique_children:
                    continue
                name = str(pal.get("name") or tribe)
                if query and query not in name.casefold() and query not in tribe.casefold():
                    continue
                rows.append((name, tribe))
            for name, tribe in sorted(rows, key=lambda row: row[0].casefold()):
                item = tree.insert("", "end", values=(name, tribe))
                lookup[item] = tribe

        def choose(_event=None):
            selected = tree.selection()
            if not selected:
                return
            tribe = lookup.get(selected[0])
            pal = info.get(tribe, {})
            self.breeding_selected_tribe = tribe
            self.breeding_selected_label.configure(
                text=str(pal.get("name") or tribe))
            self.breeding_page = 0
            self.breeding_filter_var.set("")
            dialog.destroy()
            self._render_breeding_results()

        search_var.trace_add("write", populate)
        tree.bind("<Double-Button-1>", choose)
        tree.bind("<Return>", choose)
        tk.Button(
            dialog, text="Select", command=choose, bg=COLOR["accent_dim"],
            fg=COLOR["accent"], activebackground=COLOR["line_strong"],
            activeforeground="#ffffff", relief="flat", bd=0,
            font=("Segoe UI", 9, "bold"), padx=18, pady=8,
        ).pack(pady=(0, 16))
        populate()
        search.focus_set()

    def _open_breeding_pal_picker(self):
        data = self._load_breeding_data()
        info = data.get("pal_info", {}) if data else {}
        if not info:
            messagebox.showwarning(
                "Breeding data unavailable",
                "The breeding database could not be loaded from the supplied source.")
            return
        dialog = tk.Toplevel(self)
        dialog.title("Select a Pal...")
        dialog.configure(bg=COLOR["bg0"])
        dialog.geometry("860x650")
        dialog.minsize(720, 520)
        dialog.transient(self)
        dialog.grab_set()

        search_row = tk.Frame(dialog, bg=COLOR["bg0"])
        search_row.pack(fill="x", padx=9, pady=(10, 8))
        tk.Label(
            search_row, text="Search:", bg=COLOR["bg0"], fg="#e2e8f0",
            font=("Segoe UI", 9),
        ).pack(side="left", padx=(0, 8))
        search_var = tk.StringVar()
        search = tk.Entry(
            search_row, textvariable=search_var, bg=COLOR["bg1"],
            fg=COLOR["text1"], insertbackground=COLOR["accent"],
            relief="flat", bd=0, highlightthickness=1,
            highlightbackground=COLOR["line_strong"],
            highlightcolor=COLOR["accent"], font=("Segoe UI", 9))
        search.pack(side="left", fill="x", expand=False, ipady=7)
        search.configure(width=53)
        search.insert(0, "Type to filter pals...")
        search.bind(
            "<FocusIn>", lambda event:
            search.delete(0, "end")
            if search.get() == "Type to filter pals..." else None)
        search.bind(
            "<FocusOut>", lambda event:
            search.insert(0, "Type to filter pals...")
            if not search.get() else None)

        grid_shell = tk.Frame(
            dialog, bg=COLOR["bg1"], highlightthickness=1,
            highlightbackground=COLOR["line_strong"])
        grid_shell.pack(fill="both", expand=True, padx=9, pady=(0, 8))
        canvas = tk.Canvas(grid_shell, bg="#101419", highlightthickness=0)
        scroll = ttk.Scrollbar(
            grid_shell, orient="vertical", command=canvas.yview)
        cards = tk.Frame(canvas, bg="#101419")
        cards_window = canvas.create_window((0, 0), window=cards, anchor="nw")
        cards.bind(
            "<Configure>", lambda event:
            canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind(
            "<Configure>", lambda event:
            canvas.itemconfigure(cards_window, width=event.width))
        canvas.configure(yscrollcommand=scroll.set)
        canvas.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        self._bind_mousewheel(canvas)

        selected = {"tribe": None, "card": None}
        render_state = {"generation": 0, "after": None}
        unique_children = {
            combo.get("child") for combo in data.get("unique_combos", [])}
        all_rows = []
        for tribe, pal in info.items():
            if pal.get("ignore_combi") and tribe not in unique_children:
                continue
            if not self._breeding_icon_available(pal.get("icon")):
                continue
            all_rows.append((
                str(pal.get("name") or tribe), tribe, pal))
        all_rows.sort(key=lambda row: (row[0].casefold(), row[1].casefold()))

        def select_card(tribe, card):
            old = selected.get("card")
            if old and old.winfo_exists():
                old.configure(
                    highlightthickness=1,
                    highlightbackground=COLOR["line"])
            selected["tribe"] = tribe
            selected["card"] = card
            card.configure(
                highlightthickness=2,
                highlightbackground=COLOR["accent"])

        def choose(_event=None):
            tribe = selected.get("tribe")
            if not tribe:
                return
            pal = info.get(tribe, {})
            self.breeding_selected_tribe = tribe
            self.breeding_selected_label.configure(
                text=str(pal.get("name") or tribe))
            self.breeding_page = 0
            self.breeding_filter_var.set("")
            render_state["generation"] += 1
            pending = render_state.get("after")
            if pending:
                try:
                    dialog.after_cancel(pending)
                except Exception:
                    pass
            dialog.destroy()
            self._render_breeding_results()

        def populate():
            render_state["generation"] += 1
            generation = render_state["generation"]
            pending = render_state.get("after")
            if pending:
                try:
                    dialog.after_cancel(pending)
                except Exception:
                    pass
            for child in cards.winfo_children():
                child.destroy()
            selected["tribe"], selected["card"] = None, None
            query = search_var.get().strip().casefold()
            if query == "type to filter pals...":
                query = ""
            rows = [
                row for row in all_rows
                if not query or query in row[0].casefold()
                or query in row[1].casefold()]
            columns = max(7, min(10, (canvas.winfo_width() or 830) // 81))
            image_jobs = []
            rarity_colors = {
                1: "#94a3b8", 2: "#22c55e", 3: "#38bdf8",
                4: "#a855f7", 5: "#f59e0b", 6: "#ef4444",
                7: "#facc15", 8: "#f472b6", 9: "#67e8f9",
            }
            for index, (name, tribe, pal) in enumerate(rows):
                card = tk.Frame(
                    cards, bg="#111820", width=76, height=76,
                    highlightthickness=1, highlightbackground=COLOR["line"],
                    cursor="hand2")
                card.grid(
                    row=index // columns, column=index % columns,
                    padx=2, pady=2, sticky="nsew")
                card.grid_propagate(False)
                picture = tk.Label(
                    card, text="◉", bg="#111820", fg=COLOR["accent"],
                    font=("Segoe UI", 20), cursor="hand2")
                picture.place(x=5, y=4, width=64, height=51)
                badge = tk.Label(
                    card, text="◆", bg="#111820",
                    fg=rarity_colors.get(int(pal.get("rarity", 1) or 1),
                                         "#94a3b8"),
                    font=("Segoe UI Symbol", 7))
                badge.place(relx=1.0, x=-2, y=2, anchor="ne")
                display = name if len(name) <= 12 else name[:10] + "…"
                name_label = tk.Label(
                    card, text=display, bg="#111820", fg="#ffffff",
                    font=("Segoe UI", 8), cursor="hand2")
                name_label.place(x=2, y=56, width=72, height=17)
                for widget in (card, picture, badge, name_label):
                    widget.bind(
                        "<Button-1>",
                        lambda event, value=tribe, host=card:
                        select_card(value, host))
                    widget.bind("<Double-Button-1>", choose)
                image_jobs.append((picture, tribe))

            def load_batch(position=0):
                if generation != render_state["generation"] or not dialog.winfo_exists():
                    return
                end = min(position + 12, len(image_jobs))
                for picture, tribe in image_jobs[position:end]:
                    if not picture.winfo_exists():
                        continue
                    photo = self._breeding_pal_photo(tribe, 58)
                    if photo:
                        picture.configure(image=photo, text="")
                        picture._icon_ref = photo
                if end < len(image_jobs):
                    render_state["after"] = dialog.after_idle(
                        lambda: load_batch(end))
                else:
                    render_state["after"] = None

            canvas.yview_moveto(0)
            render_state["after"] = dialog.after_idle(load_batch)

        search_after = {"id": None}

        def schedule_populate(*_args):
            pending = search_after.get("id")
            if pending:
                try:
                    dialog.after_cancel(pending)
                except Exception:
                    pass
            search_after["id"] = dialog.after(150, populate)

        search_var.trace_add("write", schedule_populate)
        footer = tk.Frame(dialog, bg=COLOR["bg0"])
        footer.pack(fill="x", padx=9, pady=(0, 10))
        tk.Button(
            footer, text="Cancel", command=dialog.destroy,
            bg="#162530", fg=COLOR["accent"], activebackground="#203745",
            activeforeground="#ffffff", relief="flat", bd=0,
            highlightthickness=1, highlightbackground=COLOR["line_strong"],
            font=("Segoe UI", 9), padx=18, pady=8,
        ).pack(side="right")
        tk.Button(
            footer, text="Select", command=choose,
            bg="#162530", fg=COLOR["accent"], activebackground="#203745",
            activeforeground="#ffffff", relief="flat", bd=0,
            highlightthickness=1, highlightbackground=COLOR["line_strong"],
            font=("Segoe UI", 9), padx=18, pady=8,
        ).pack(side="right", padx=(0, 8))
        dialog.bind("<Escape>", lambda event: dialog.destroy())
        dialog.bind("<Return>", choose)
        dialog.after(50, populate)
        search.focus_set()

    def _schedule_breeding_render(self):
        pending = getattr(self, "_breeding_render_after", None)
        if pending:
            try:
                self.after_cancel(pending)
            except Exception:
                pass
        self._breeding_render_after = self.after(
            160, self._render_breeding_results)

    def _breeding_rows(self):
        data = self.breeding_data or {}
        target = self.breeding_selected_tribe
        if not target:
            return []
        if self.breeding_mode == "parents":
            rows, seen = [], set()
            sections = (
                ("Unique Combo",
                 data.get("child_to_parents_unique", {}).get(target, [])),
                ("Formula Combo",
                 data.get("child_to_parents_formula", {}).get(target, [])),
                ("Formula Combo",
                 data.get("child_to_parents_ignore", {}).get(target, [])),
            )
            for label, pairs in sections:
                for pair in pairs:
                    a, b = pair.get("parent_a"), pair.get("parent_b")
                    key = tuple(sorted((str(a), str(b))))
                    if a and b and key not in seen:
                        seen.add(key)
                        rows.append((label, a, b, target))
            return rows
        children = {}
        for label, mapping in (
                ("Unique Combo", data.get("child_to_parents_unique", {})),
                ("Formula Combo", data.get("child_to_parents_formula", {}))):
            for child, pairs in mapping.items():
                for pair in pairs:
                    a, b = pair.get("parent_a"), pair.get("parent_b")
                    if a == target or b == target:
                        partner = b if a == target else a
                        children[(child, partner)] = label
        for entry in data.get("parent_to_children_formula", {}).get(target, []):
            children[(entry.get("child"), entry.get("partner"))] = "Formula Combo"
        return [
            (label, target, partner, child)
            for (child, partner), label in children.items()
            if child and partner]

    def _breeding_pal_widget(self, parent, tribe, arrow=None):
        data = self.breeding_data or {}
        pal = data.get("pal_info", {}).get(tribe, {})
        box = tk.Frame(parent, bg="#151b22")
        photo = self._breeding_pal_photo(tribe, 42)
        image = tk.Label(
            box, image=photo or "", text="" if photo else "◉",
            bg="#151b22", fg=COLOR["accent"], width=48)
        image._icon_ref = photo
        image.pack(side="left", padx=(8, 5), pady=6)
        tk.Label(
            box, text=str(pal.get("name") or tribe), bg="#151b22",
            fg="#e2e8f0", font=("Segoe UI", 9, "bold"), anchor="w",
        ).pack(side="left", padx=(0, 8))
        if arrow:
            tk.Label(
                parent, text=arrow, bg="#101419", fg=COLOR["accent"],
                font=("Segoe UI", 15, "bold")).pack(side="left", padx=10)
        return box

    def _breeding_pal_photo(self, tribe, size):
        pal = (self.breeding_data or {}).get("pal_info", {}).get(tribe, {})
        icon = str(pal.get("icon") or "")
        if icon:
            if not hasattr(self, "_technology_photo_cache"):
                self._technology_photo_cache = {}
            self._locate_technology_icon_source()
            photo = self._technology_photo({
                "asset": f"breeding-pal:{tribe}:{int(size)}",
                "icon": icon,
            }, size)
            if photo:
                return photo
        return self.get_pal_photo(tribe, size)

    def _breeding_icon_available(self, icon):
        relative = str(icon or "").lstrip("/").replace("\\", "/")
        if not relative:
            return False
        self._locate_technology_icon_source()
        root = getattr(self, "_technology_icon_root", None)
        if root and (root / Path(relative)).is_file():
            return True
        suffix = ("/resources/game_data/" + relative).casefold()
        return any(
            normalized.casefold().endswith(suffix)
            for normalized in getattr(
                self, "_technology_icon_zip_names", {}).keys())

    def _render_breeding_results(self):
        if not hasattr(self, "breeding_results"):
            return
        for child in self.breeding_results.winfo_children():
            child.destroy()
        if not self.breeding_selected_tribe:
            self.breeding_filter.pack_forget()
            tk.Label(
                self.breeding_results,
                text="Select a pal to see breeding combinations",
                bg="#101419", fg="#64748b", font=("Segoe UI", 9),
            ).place(relx=.5, rely=.45, anchor="center")
            return
        self.breeding_filter.pack(
            before=self.breeding_results_canvas, fill="x",
            padx=20, pady=(0, 8), ipady=6)
        data = self._load_breeding_data()
        info = data.get("pal_info", {})
        target = self.breeding_selected_tribe
        target_name = info.get(target, {}).get("name", target)
        tk.Label(
            self.breeding_results,
            text=("Parents for " if self.breeding_mode == "parents"
                  else "Children for ") + str(target_name),
            bg="#101419", fg="#e2e8f0",
            font=("Segoe UI", 11, "bold"), anchor="w",
        ).pack(fill="x", pady=(6, 8))
        rows = self._breeding_rows()
        query = self.breeding_filter_var.get().strip().casefold()
        if query:
            rows = [
                row for row in rows
                if any(
                    query in str(info.get(tribe, {}).get("name", tribe)).casefold()
                    for tribe in row[1:])]
        total = len(rows)
        total_pages = max(1, math.ceil(total / self.breeding_page_size))
        self.breeding_page = min(self.breeding_page, total_pages - 1)
        start = self.breeding_page * self.breeding_page_size
        for label, first, second, child in rows[
                start:start + self.breeding_page_size]:
            card = tk.Frame(
                self.breeding_results, bg="#101419", highlightthickness=1,
                highlightbackground=COLOR["line"])
            card.pack(fill="x", pady=3)
            tk.Label(
                card, text=label, bg="#162530", fg="#94a3b8",
                font=("Segoe UI", 7), width=14,
            ).pack(side="left", fill="y")
            first_box = self._breeding_pal_widget(card, first)
            first_box.pack(side="left", padx=(10, 0), pady=4)
            tk.Label(
                card, text="+", bg="#101419", fg=COLOR["accent"],
                font=("Segoe UI", 14, "bold")).pack(side="left", padx=10)
            second_box = self._breeding_pal_widget(card, second)
            second_box.pack(side="left", pady=4)
            tk.Label(
                card, text="→", bg="#101419", fg=COLOR["accent"],
                font=("Segoe UI", 14, "bold")).pack(side="left", padx=10)
            child_box = self._breeding_pal_widget(card, child)
            child_box.pack(side="left", pady=4)
        if not rows:
            tk.Label(
                self.breeding_results, text="No breeding combinations found",
                bg="#101419", fg="#64748b", font=("Segoe UI", 9),
            ).pack(pady=30)
        nav = tk.Frame(self.breeding_results, bg="#101419")
        nav.pack(fill="x", pady=10)
        tk.Button(
            nav, text="<", command=lambda: self._change_breeding_page(-1),
            state="normal" if self.breeding_page > 0 else "disabled",
            bg=COLOR["accent_dim"], fg=COLOR["accent"], relief="flat",
            bd=0, width=3).pack(side="left")
        tk.Label(
            nav, text=f"Page {self.breeding_page + 1} of {total_pages}",
            bg="#101419", fg="#94a3b8", font=("Segoe UI", 8),
        ).pack(side="left", padx=8)
        tk.Button(
            nav, text=">", command=lambda: self._change_breeding_page(1),
            state="normal" if self.breeding_page + 1 < total_pages else "disabled",
            bg=COLOR["accent_dim"], fg=COLOR["accent"], relief="flat",
            bd=0, width=3).pack(side="left")
        tk.Label(
            nav, text=f"{total} combo(s)", bg="#101419", fg="#64748b",
            font=("Segoe UI", 8)).pack(side="left", padx=10)

    def _change_breeding_page(self, change):
        self.breeding_page = max(0, self.breeding_page + change)
        self._render_breeding_results()
        self.breeding_results_canvas.yview_moveto(0)

