    def _auto_locate_oodle_library(self):
        system = platform.system()
        if system == "Windows":
            candidate_names = ["oo2core_8_win64.dll", "oo2core_9_win64.dll",
                                "oo2core_7_win64.dll", "oo2core_6_win64.dll"]
        elif system == "Darwin":
            candidate_names = ["liboo2coremac64.dylib"]
        else:
            candidate_names = ["liboo2corelinux64.so"]

        search_dirs = []
        try:
            search_dirs.append(os.path.dirname(os.path.abspath(__file__)))
        except NameError:
            pass
        search_dirs.append(os.getcwd())

        for d in search_dirs:
            for name in candidate_names:
                candidate = os.path.join(d, name)
                if os.path.isfile(candidate):
                    try:
                        self.oodle_decompressor = OodleDecompressor(candidate)
                        return
                    except OSError:
                        continue

    def load_oodle_library(self):
        if platform.system() == "Windows":
            filetypes = [("Oodle library", "*.dll"), ("All files", "*.*")]
        else:
            filetypes = [("Oodle library", "*.so*"), ("All files", "*.*")]
        path = filedialog.askopenfilename(title="Locate the Oodle library (oo2core)", filetypes=filetypes)
        if not path:
            return
        try:
            self.oodle_decompressor = OodleDecompressor(path)
        except OSError as e:
            messagebox.showerror("Couldn't load Oodle library",
                                  f"Found the file but couldn't load it as a shared library:\n{e}")
            self.oodle_decompressor = None
            return
        messagebox.showinfo("Oodle library loaded",
                             f"Loaded:\n{path}\n\nOodle-compressed saves can now be decompressed.")
        self._render_tools_status()

    def _debounce(self, key, callback, delay=180):
        previous = self._debounce_jobs.pop(key, None)
        if previous is not None:
            try:
                self.after_cancel(previous)
            except Exception:
                pass
        def run():
            self._debounce_jobs.pop(key, None)
            callback()
        self._debounce_jobs[key] = self.after(delay, run)

    def _bounded_cache_put(self, cache, key, value, limit):
        cache[key] = value
        cache.move_to_end(key)
        while len(cache) > limit:
            cache.popitem(last=False)

    def _get_cached_source_image(self, path):
        """Load an icon file once and reuse its decoded RGBA pixels."""
        if not PIL_AVAILABLE or not path:
            return None
        cached = self._source_image_cache.get(path)
        if cached is not None:
            self._source_image_cache.move_to_end(path)
            return cached
        try:
            with Image.open(path) as opened:
                image = opened.convert("RGBA").copy()
        except Exception:
            return None
        self._bounded_cache_put(
            self._source_image_cache, path, image, self._source_image_cache_limit
        )
        return image

    def _persistent_thumbnail_path(self, source_path, size, variant="square", ring_color=None):
        if not self._thumbnail_cache_root or not source_path or not PIL_AVAILABLE:
            return source_path
        try:
            stat = os.stat(source_path)
            token = f"{os.path.abspath(source_path)}|{stat.st_mtime_ns}|{stat.st_size}|{size}|{variant}|{ring_color}"
            name = hashlib.sha1(token.encode("utf-8", "surrogatepass")).hexdigest() + ".png"
            target = self._thumbnail_cache_root / str(int(size)) / name
            if target.is_file():
                return str(target)
            target.parent.mkdir(parents=True, exist_ok=True)
            with Image.open(source_path) as opened:
                image = opened.convert("RGBA")
                image.thumbnail((size, size), Image.Resampling.LANCZOS)
                if variant == "circular":
                    square = Image.new("RGBA", (size, size), (0, 0, 0, 0))
                    square.paste(image, ((size-image.width)//2, (size-image.height)//2), image)
                    mask = Image.new("L", (size, size), 0)
                    ImageDraw.Draw(mask).ellipse((0, 0, size-1, size-1), fill=255)
                    square.putalpha(mask)
                    if ring_color:
                        ImageDraw.Draw(square).ellipse((0,0,size-1,size-1), outline=ring_color, width=2)
                    image = square
                image.save(target, "PNG", optimize=True)
            return str(target)
        except Exception:
            return source_path

    def _get_cached_photo_from_path(self, path, size, variant="square", ring_color=None):
        """Return one shared Tk PhotoImage for a path/size/variant combination."""
        if not path or size <= 0:
            return None
        original_path = path
        path = self._persistent_thumbnail_path(path, size, variant, ring_color)
        key = (original_path, int(size), variant, ring_color)
        if key in self._photo_image_cache:
            photo = self._photo_image_cache[key]
            self._photo_image_cache.move_to_end(key)
            return photo
        source = self._get_cached_source_image(path)
        if source is None:
            return None
        try:
            image = source.copy()
            image.thumbnail((size, size), Image.Resampling.LANCZOS)
            if variant == "circular" and path == original_path:
                square = Image.new("RGBA", (size, size), (0, 0, 0, 0))
                square.paste(image, ((size - image.width) // 2, (size - image.height) // 2), image)
                mask = Image.new("L", (size, size), 0)
                ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
                square.putalpha(mask)
                if ring_color:
                    ImageDraw.Draw(square).ellipse(
                        (0, 0, size - 1, size - 1), outline=ring_color, width=2
                    )
                image = square
            photo = ImageTk.PhotoImage(image)
        except Exception:
            return None
        self._bounded_cache_put(
            self._photo_image_cache, key, photo, self._photo_image_cache_limit
        )
        return photo

    def _clear_global_icon_caches(self):
        self._pal_image_cache.clear()
        self._pal_image_file_index = None
        self._item_image_cache.clear()
        self._image_path_cache.clear()
        self._source_image_cache.clear()
        self._photo_image_cache.clear()

    def _schedule_docs_icon_prewarm(self):
        """Warm Docs thumbnails in small idle batches without freezing Tk."""
        if self._docs_prewarm_after is not None:
            try:
                self.after_cancel(self._docs_prewarm_after)
            except Exception:
                pass
        queue = []
        if self.pal_image_dir:
            queue.extend(("pal", p.get("spawn_id")) for p in wiki_pals if p.get("spawn_id"))
        if self.item_image_dir:
            queue.extend(("item", i.get("game_id")) for i in wiki_items if i.get("game_id"))
        self._docs_icon_prewarm_queue = queue

        def warm_batch():
            self._docs_prewarm_after = None
            for _ in range(10):
                if not self._docs_icon_prewarm_queue:
                    return
                kind, identity = self._docs_icon_prewarm_queue.pop(0)
                if kind == "pal":
                    self.get_pal_photo(identity, 28)
                else:
                    self.get_item_photo(identity, 28)
            self._docs_prewarm_after = self.after(8, warm_batch)

        self._docs_prewarm_after = self.after(50, warm_batch)

    def set_pal_image_dir(self):
        if not PIL_AVAILABLE:
            messagebox.showerror("Pillow not installed",
                                  "This feature needs the Pillow library to load and resize "
                                  "images. Install it with:\n\npip install Pillow\n\nthen "
                                  "restart the app.")
            return
        path = filedialog.askdirectory(title="Choose your pal images folder")
        if not path:
            return
        self.pal_image_dir = path
        self._clear_global_icon_caches()
        matches = sum(1 for p in wiki_pals
                      if p.get("spawn_id") and p["spawn_id"] != "\u2014"
                      and self._find_pal_image_path(p["spawn_id"]))
        messagebox.showinfo("Pal image folder set",
                             f"Using:\n{path}\n\nFound matching images for {matches} of "
                             f"{len(wiki_pals)} pals. Anything else keeps its emoji icon.")
        self.render_all()
        if hasattr(self, "render_docs"):
            self.render_docs()

    def _ensure_reference_pal_assets(self, script_dir):
        if not PIL_AVAILABLE:
            return None
        cache_dir = Path.home() / ".palworld_save_editor" / "pal_icons"
        try:
            cache_dir.mkdir(parents=True, exist_ok=True)
            if sum(1 for _ in cache_dir.glob("*.*")) >= 250:
                return str(cache_dir)
        except OSError:
            return None
        candidates = [
            Path(script_dir) / "PalworldSaveTools-2.2.1.zip",
            Path(script_dir).parent / "PalworldSaveTools-2.2.1.zip",
            Path.home() / "Downloads" / "PalworldSaveTools-2.2.1.zip",
            Path("D:/Ayden/Downloads/PalworldSaveTools-2.2.1.zip"),
        ]
        archive_path = next((path for path in candidates if path.is_file()), None)
        if archive_path is None:
            return None
        try:
            with zipfile.ZipFile(archive_path, "r") as archive:
                members = [
                    name for name in archive.namelist()
                    if "/resources/game_data/icons/pals/" in name.replace("\\", "/")
                    and name.lower().endswith((".png", ".webp", ".jpg", ".jpeg"))
                ]
                for member in members:
                    destination = cache_dir / Path(member).name
                    if destination.is_file() and destination.stat().st_size:
                        continue
                    with archive.open(member) as source, destination.open("wb") as output:
                        shutil.copyfileobj(source, output)
            return str(cache_dir)
        except (OSError, zipfile.BadZipFile, KeyError):
            return None

    @staticmethod
    def _normalise_pal_icon_key(value):
        key = str(value or "").strip().casefold()
        for prefix in ("boss_", "predator_", "raidboss_"):
            if key.startswith(prefix):
                key = key[len(prefix):]
        if key.startswith("t_"):
            key = key[2:]
        for suffix in ("_icon_normal", "_icon"):
            if key.endswith(suffix):
                key = key[:-len(suffix)]
        return re.sub(r"[^a-z0-9]+", "", key)

    def _find_pal_image_path(self, spawn_id):
        if not self.pal_image_dir or not spawn_id or spawn_id == "—":
            return None
        key = ("pal", self.pal_image_dir, spawn_id)
        if key in self._image_path_cache:
            return self._image_path_cache[key]
        if self._pal_image_file_index is None:
            index = {}
            try:
                for root, _directories, filenames in os.walk(self.pal_image_dir):
                    for filename in filenames:
                        if not filename.lower().endswith((".png", ".jpg", ".jpeg", ".webp")):
                            continue
                        full_path = os.path.join(root, filename)
                        stem = os.path.splitext(filename)[0]
                        index.setdefault(self._normalise_pal_icon_key(stem), full_path)
                        index.setdefault(stem.casefold(), full_path)
            except OSError:
                index = {}
            self._pal_image_file_index = index
        path = self._pal_image_file_index.get(self._normalise_pal_icon_key(spawn_id))
        if path is None:
            path = self._pal_image_file_index.get(str(spawn_id).casefold())
        self._image_path_cache[key] = path
        return path

    def get_pal_photo(self, spawn_id, size):
        if not PIL_AVAILABLE or not spawn_id:
            return None
        cache_key = (spawn_id, size)
        if cache_key in self._pal_image_cache:
            return self._pal_image_cache[cache_key]
        path = self._find_pal_image_path(spawn_id) if self.pal_image_dir else None
        photo = self._get_cached_photo_from_path(path, size) if path else None
        if photo is None:
            photo = self._get_source_pal_photo(spawn_id, size)
        if photo is None:
            # Some newer/internal records are present in characters.json but
            # their declared portrait files are absent from the supplied
            # source. Use the supplied/local Pal dummy artwork so catalogue
            # rows never appear as if their image failed to load.
            unknown_path = (
                self._find_pal_image_path("unknown")
                if self.pal_image_dir else None)
            if unknown_path:
                photo = self._get_cached_photo_from_path(unknown_path, size)
            if photo is None:
                photo = self._docs_active_skill_photo({
                    "asset": "__unknown_pal__",
                    "icon": "/icons/pals/T_dummy_icon.webp",
                }, size)
        if photo is not None:
            self._pal_image_cache[cache_key] = photo
        return photo

    def _get_source_pal_photo(self, spawn_id, size):
        """Load a Pal portrait from the supplied PalworldSaveTools data."""
        if not PIL_AVAILABLE or not spawn_id:
            return None
        self._load_docs_pal_source_data()
        icon_path = getattr(
            self, "_source_pal_icon_files", {}).get(str(spawn_id).casefold())
        if not icon_path:
            return None
        relative = str(icon_path).lstrip("/").replace("\\", "/")
        try:
            image = None
            root = getattr(self, "_technology_icon_root", None)
            archive = getattr(self, "_technology_icon_zip", None)
            if root:
                source_path = root / Path(relative)
                if source_path.is_file():
                    with Image.open(source_path) as source:
                        image = source.convert("RGBA")
            if image is None and archive:
                suffix = ("/resources/game_data/" + relative).casefold()
                archive_name = next(
                    (actual for normalized, actual
                     in self._technology_icon_zip_names.items()
                     if normalized.casefold().endswith(suffix)),
                    None)
                if archive_name:
                    with archive.open(archive_name) as handle:
                        with Image.open(io.BytesIO(handle.read())) as source:
                            image = source.convert("RGBA")
            if image is None:
                return None
            image.thumbnail((size, size), Image.Resampling.LANCZOS)
            return ImageTk.PhotoImage(image)
        except (OSError, KeyError, ValueError):
            return None

    def get_circular_pal_photo(self, spawn_id, size, ring_color=None):
        if not PIL_AVAILABLE or not self.pal_image_dir or not spawn_id:
            return None
        cache_key = (spawn_id, size, "circular", ring_color)
        if cache_key in self._pal_image_cache:
            return self._pal_image_cache[cache_key]
        path = self._find_pal_image_path(spawn_id)
        photo = self._get_cached_photo_from_path(path, size, "circular", ring_color) if path else None
        self._pal_image_cache[cache_key] = photo
        return photo

    def set_item_image_dir(self):
        if not PIL_AVAILABLE:
            messagebox.showerror("Pillow not installed",
                                  "This feature needs the Pillow library to load and resize "
                                  "images. Install it with:\n\npip install Pillow\n\nthen "
                                  "restart the app.")
            return
        path = filedialog.askdirectory(title="Choose your item icons folder")
        if not path:
            return
        self.item_image_dir = path
        self._clear_global_icon_caches()
        messagebox.showinfo("Item icon folder set",
                             f"Using:\n{path}\n\nName each file by item static ID to match it up, "
                             f"e.g. Money.png, Stone.png, PalSphere.png. Anything without a "
                             f"matching file keeps a placeholder icon.")
        if hasattr(self, "render_inventory"):
            self.render_inventory()
        self._schedule_docs_icon_prewarm()

    def _find_item_image_path(self, item_id):
        if not self.item_image_dir or not item_id:
            return None
        key = ("item", self.item_image_dir, item_id)
        if key in self._image_path_cache:
            return self._image_path_cache[key]
        icon_file = ITEM_ICON_FILES.get(item_id)
        names = []
        if icon_file:
            names.append(os.path.splitext(icon_file)[0])
        names.append(item_id)
        path = None
        for name in names:
            for ext in (".png", ".jpg", ".jpeg", ".webp"):
                candidate = os.path.join(self.item_image_dir, name + ext)
                if os.path.isfile(candidate):
                    path = candidate
                    break
            if path:
                break
        if not path:
            unknown = os.path.join(self.item_image_dir, "T_icon_unknown.png")
            path = unknown if os.path.isfile(unknown) else None
        self._image_path_cache[key] = path
        return path

    def get_item_photo(self, item_id, size):
        if not item_id:
            return None
        cache_key = (item_id, size)
        if cache_key in self._item_image_cache:
            return self._item_image_cache[cache_key]
        path = self._find_item_image_path(item_id) if self.item_image_dir else None
        if PIL_AVAILABLE:
            # A selected local icon folder uses T_icon_unknown as its fallback.
            # Do not let that generic cube hide an exact image available in
            # the supplied PalworldSaveTools source archive.
            is_local_placeholder = bool(
                path and os.path.splitext(os.path.basename(path))[0].lower()
                == "t_icon_unknown"
            )
            if path and not is_local_placeholder:
                photo = self._get_cached_photo_from_path(path, size)
            else:
                photo = self._get_source_item_photo(item_id, size)
                if photo is None and path:
                    photo = self._get_cached_photo_from_path(path, size)
        else:
            try:
                photo = tk.PhotoImage(file=path) if path else None
            except Exception:
                photo = None
        # Do not permanently cache a miss. Source discovery may become
        # possible later when Level.sav identifies a redirected drive.
        if photo is not None:
            self._item_image_cache[cache_key] = photo
        return photo

    def _get_source_item_photo(self, item_id, size):
        """Load the exact item icon from the supplied source tree/archive."""
        if not PIL_AVAILABLE or not item_id:
            return None
        self._locate_technology_icon_source()
        icon_path = getattr(self, "_source_item_icon_files", {}).get(str(item_id))
        if not icon_path:
            icon_file = ITEM_ICON_FILES.get(str(item_id))
            icon_path = f"/icons/items/{icon_file}" if icon_file else None
        if not icon_path:
            return None
        relative = str(icon_path).lstrip("/").replace("\\", "/")
        try:
            image = None
            root = getattr(self, "_technology_icon_root", None)
            archive = getattr(self, "_technology_icon_zip", None)
            if root:
                source_path = root / Path(relative)
                if source_path.is_file():
                    with Image.open(source_path) as source:
                        image = source.convert("RGBA")
            elif archive:
                suffix = "/resources/game_data/" + relative
                archive_name = next(
                    (actual for normalized, actual
                     in self._technology_icon_zip_names.items()
                     if normalized.endswith(suffix)),
                    None,
                )
                if archive_name:
                    with archive.open(archive_name) as handle:
                        with Image.open(io.BytesIO(handle.read())) as source:
                            image = source.convert("RGBA")
            # Four catalogue entries in the supplied source metadata do not
            # have a dedicated image file. Use the source application's own
            # unknown-item artwork so every picker row still has a picture.
            if image is None:
                fallback = "icons/T_icon_unknown.webp"
                if root:
                    fallback_path = root / Path(fallback)
                    if fallback_path.is_file():
                        with Image.open(fallback_path) as source:
                            image = source.convert("RGBA")
                elif archive:
                    fallback_suffix = "/resources/game_data/" + fallback
                    fallback_name = next(
                        (actual for normalized, actual
                         in self._technology_icon_zip_names.items()
                         if normalized.endswith(fallback_suffix)),
                        None,
                    )
                    if fallback_name:
                        with archive.open(fallback_name) as handle:
                            with Image.open(io.BytesIO(handle.read())) as source:
                                image = source.convert("RGBA")
            if image is None:
                return None
            image.thumbnail((size, size), Image.Resampling.LANCZOS)
            return ImageTk.PhotoImage(image)
        except (OSError, KeyError, ValueError):
            return None


    def _set_profile_player_name(self, name):
        name = str(name or "").strip()
        if not name:
            name = "No player loaded"
        if hasattr(self, "profile_chip"):
            self.profile_chip.configure(text=name)
            if hasattr(self, "pal_editor_profile_chip"):
                self.pal_editor_profile_chip.configure(text=name)

    def _update_profile_chip_from_world(self, map_data=None):
        """Show the in-game player name as soon as Level.sav is decoded."""
        try:
            data = map_data if map_data is not None else self.map_entries
            players = data.get("players", []) or []
        except (AttributeError, TypeError):
            players = []
        if not players:
            self._set_profile_player_name(None)
            return
        # A local/single-player world normally has one player. For multiplayer
        # worlds, retain a stable first entry until the user selects another.
        player = players[0]
        self._set_profile_player_name(player.get("name") or "Unnamed Survivor")

    def load_sav_file(self):
        path = filedialog.askopenfilename(
            title="Load Palworld save file",
            filetypes=[("Palworld save files", "*.sav"), ("All files", "*.*")],
        )
        if not path:
            return  # user cancelled
        self.configure(cursor="arrow")
        # Return from the native file dialog immediately. Queue/process
        # construction can briefly block Windows if performed in this same
        # callback, even when the actual decoder runs elsewhere.
        self.after(1, lambda selected=path:
                   self._begin_async_sav_load(selected))

    def _begin_async_sav_load(self, path):
        token = uuid.uuid4().hex
        self._sav_load_token = token
        self._sav_load_result = None
        self._set_profile_player_name("Loading save...")
        if hasattr(self, "tools_status_label"):
            self.tools_status_label.configure(text="Loading and indexing save...")

        player_ids = dict(getattr(self, "player_container_ids", {}) or {})
        oodle_path = (self.oodle_decompressor.lib_path
                      if self.oodle_decompressor else None)
        self._sav_load_queue = None
        self._sav_load_process = None
        self._sav_process_started = False
        self._sav_result_ready = False
        self._sav_process_start_error = None

        def run_decoder_and_receive():
            result_queue = None
            process = None
            try:
                # Constructing a multiprocessing Queue invokes Windows kernel
                # objects and was the final synchronous pause after the file
                # picker closed. Do all process infrastructure here too.
                context = multiprocessing.get_context("spawn")
                result_queue = context.Queue(maxsize=1)
                process = context.Process(
                    target=_decode_save_in_process,
                    args=(path, oodle_path, player_ids, result_queue),
                    name="PalSaveDecoder",
                    daemon=True,
                )
                self._sav_load_queue = result_queue
                self._sav_load_process = process
                process.start()
                self._sav_process_started = True
                result = None
                while getattr(self, "_sav_load_token", None) == token:
                    try:
                        # Receiving the result also reconstructs the very large
                        # parsed Python object. Keep that work off Tk's thread.
                        result = result_queue.get(timeout=0.1)
                        break
                    except queue.Empty:
                        if not process.is_alive():
                            try:
                                result = result_queue.get(timeout=0.5)
                            except queue.Empty:
                                result = {
                                    "ok": False,
                                    "error": ("The save decoder process stopped "
                                              "unexpectedly."),
                                }
                            break
                if getattr(self, "_sav_load_token", None) == token:
                    self._sav_load_result = result
            except Exception as exc:
                self._sav_process_start_error = str(exc)
            finally:
                self._sav_process_started = True
                self._sav_result_ready = True
                try:
                    if process is not None:
                        process.join(timeout=0.5)
                except Exception:
                    pass
                try:
                    if result_queue is not None:
                        result_queue.close()
                except Exception:
                    pass

        threading.Thread(
            target=run_decoder_and_receive,
            name="PalSaveDecoderStarter",
            daemon=True,
        ).start()
        self.after(35, lambda: self._poll_async_sav_load(token))

    def _poll_async_sav_load(self, token):
        if getattr(self, "_sav_load_token", None) != token:
            return
        if not getattr(self, "_sav_process_started", False):
            self.after(35, lambda: self._poll_async_sav_load(token))
            return
        start_error = getattr(self, "_sav_process_start_error", None)
        if start_error:
            self._sav_process_start_error = None
            self._set_profile_player_name(None)
            messagebox.showerror("Couldn't start save decoder", start_error)
            return
        if not getattr(self, "_sav_result_ready", False):
            self.after(35, lambda: self._poll_async_sav_load(token))
            return
        result = getattr(self, "_sav_load_result", None)
        self._sav_load_process = None
        self._sav_load_queue = None
        if result is None:
            self._set_profile_player_name(None)
            messagebox.showerror(
                "Couldn't load save",
                "The background save decoder returned no result.")
            return
        if not result.get("ok"):
            self._set_profile_player_name(None)
            messagebox.showerror("Couldn't load save", result.get(
                "error", "The save could not be decoded."))
            return
        self._apply_prepared_sav(result)

    def _apply_prepared_sav(self, prepared):
        global entries, selected_id
        self._data_revision = getattr(self, "_data_revision", 0) + 1
        self.loaded_sav_path = prepared["path"]
        self.loaded_sav_bytes = prepared["gvas"]
        self.loaded_sav_raw_size = prepared["raw_size"]
        self.loaded_sav_method = prepared["method"]
        self.loaded_sav_matches = []
        self.loaded_sav_json = prepared["json"]
        self.map_entries = prepared["map_entries"]
        self._map_entries_source_id = id(self.loaded_sav_json)
        self._update_profile_chip_from_world(self.map_entries)
        self.pal_field_refs = prepared["field_refs"]
        self._palbox_container_id = prepared["palbox_id"]
        self._party_container_ids = prepared["party_ids"]
        self.inventory_containers = prepared["containers"]
        self.inventory_slot_refs = prepared["slot_refs"]
        self.inventory_slots_field_values = prepared["slot_values"]

        pal_entries = prepared["pal_entries"]
        if not pal_entries:
            messagebox.showwarning(
                "No editable pals found",
                "Loaded the save, but couldn't find any decodable Pal records.")
            return
        entries.clear()
        entries.extend(pal_entries)
        selected_id = entries[0]["id"]

        previous_job = getattr(self, "_auto_player_match_after", None)
        if previous_job is not None:
            try:
                self.after_cancel(previous_job)
            except tk.TclError:
                pass
        self._auto_player_match_after = self.after(
            75, self._finish_deferred_player_match)

        current_view = getattr(self, "_current_view_key", None)
        refresh_steps = []
        if current_view == "editor":
            # Rebuild the four editor regions separately so Tk can repaint
            # between them instead of presenting one long blocking redraw.
            refresh_steps.extend([
                self.render_roster,
                self.render_box_grid,
                self.render_detail,
                self.render_results,
            ])
        elif current_view == "inventory":
            refresh_steps.append(self.render_inventory)
        elif current_view == "map":
            refresh_steps.append(self.load_map_data)
        if hasattr(self, "tools_status_frame"):
            refresh_steps.append(self._render_tools_status)

        n_items = sum(container["item_count"]
                      for container in self.inventory_containers)
        summary = (
            f"Loaded {len(pal_entries)} Pal/character records and "
            f"{n_items} item stacks across "
            f"{len(self.inventory_containers)} containers.")

        def finish_step(index=0):
            if index < len(refresh_steps):
                refresh_steps[index]()
                self.after(1, lambda: finish_step(index + 1))
                return
            if current_view:
                self._view_render_revision[current_view] = self._data_revision
            self.after(
                1, lambda: messagebox.showinfo("Save loaded", summary))

        # Return control to Tk before performing any visible refresh. This
        # guarantees that the decoded result can be applied without holding
        # the window in a busy/non-painting state.
        self.after_idle(finish_step)

    def _auto_locate_matching_player_save(self):
        """After a world save is loaded, scan a folder named ``Players`` for a
        player .sav whose referenced inventory container GUIDs match Level.sav.

        This deliberately does no filesystem scan at application startup.
        """
        if not getattr(self, "loaded_sav_json", None):
            return False

        try:
            app_dir = os.path.dirname(os.path.abspath(__file__))
        except NameError:
            app_dir = os.getcwd()

        player_dirs = [os.path.join(app_dir, "Players")]
        if getattr(self, "loaded_sav_path", None):
            level_player_dir = os.path.join(
                os.path.dirname(os.path.abspath(self.loaded_sav_path)),
                "Players",
            )
            if os.path.normcase(level_player_dir) != os.path.normcase(player_dirs[0]):
                player_dirs.append(level_player_dir)

        candidates = []
        for player_dir in player_dirs:
            try:
                candidates.extend(
                    os.path.join(player_dir, name)
                    for name in os.listdir(player_dir)
                    if name.lower().endswith(".sav")
                    and not name.lower().endswith("_dps.sav")
                )
            except OSError:
                continue

        loaded_path = os.path.normcase(os.path.abspath(self.loaded_sav_path)) \
            if getattr(self, "loaded_sav_path", None) else ""
        candidates = [
            path for path in candidates
            if os.path.normcase(os.path.abspath(path)) != loaded_path
        ]
        if not candidates:
            return False

        level_container_ids = {
            c.get("container_id")
            for c in getattr(self, "inventory_containers", [])
            if c.get("container_id")
        }
        if not level_container_ids:
            return False

        best = None
        for path in candidates:
            try:
                with open(path, "rb") as f:
                    raw = f.read()
                gvas, _method = decompress_sav(raw, oodle=self.oodle_decompressor)
                player_json = sav_to_json_dict(gvas)
                container_ids = extract_player_container_ids(player_json)
            except Exception:
                continue

            if not container_ids:
                continue
            matched = len(level_container_ids.intersection(container_ids.values()))
            if matched <= 0:
                continue

            score = (matched, len(container_ids))
            if best is None or score > best[0]:
                best = (score, path, container_ids)

        if best is None:
            return False

        (_matched, _total), path, container_ids = best
        self.player_container_ids = container_ids
        self.auto_player_sav_path = path
        self.inventory_containers, self.inventory_slot_refs, self.inventory_slots_field_values = \
            build_inventory_from_json(self.loaded_sav_json, self.player_container_ids)
        if not getattr(self, "_auto_match_background", False):
            if (hasattr(self, "render_inventory")
                    and getattr(self, "_current_view_key", None) == "inventory"):
                self.render_inventory()
            if hasattr(self, "tools_status_frame"):
                self._render_tools_status()
        return True

    def _load_player_sav_path(self, path, quiet=False):
        with open(path, "rb") as f:
            raw = f.read()
        gvas, method = decompress_sav(raw, oodle=self.oodle_decompressor)
        player_json = sav_to_json_dict(gvas)
        self.loaded_player_sav_json = player_json
        container_ids = extract_player_container_ids(player_json)
        if not container_ids:
            raise ValueError("No player inventory container IDs were found in this save.")
        self.player_container_ids = container_ids
        self.auto_player_sav_path = Path(path)
        self._data_revision = getattr(self, "_data_revision", 0) + 1
        try:
            stem = self._normalise_player_guid(Path(path).stem)
            for row in getattr(self, "player_search_rows", []):
                candidates = {self._normalise_player_guid(row.get("uid"))}
                uid = self._normalise_player_guid(row.get("uid"))
                if uid:
                    try:
                        converted = _guid_from_pal_bytes(bytes.fromhex(uid))
                        candidates.add(self._normalise_player_guid(converted))
                    except Exception:
                        pass
                if stem in candidates:
                    self._set_profile_player_name(row.get("name"))
                    break
        except Exception:
            pass
        if getattr(self, "loaded_sav_json", None):
            self.inventory_containers, self.inventory_slot_refs, self.inventory_slots_field_values = \
                build_inventory_from_json(self.loaded_sav_json, self.player_container_ids)
            if hasattr(self, "render_inventory"):
                self.render_inventory()
                if getattr(self, "_current_view_key", None) == "inventory":
                    self._view_render_revision["inventory"] = self._data_revision
            self.load_map_data()
            if hasattr(self, "tools_status_frame"):
                self._render_tools_status()
        if not quiet:
            messagebox.showinfo("Player save loaded", f"Loaded {Path(path).name}.")
        return True

    def load_player_sav_file(self):
        path = filedialog.askopenfilename(
            title="Load the player's own save file (Players\\<id>.sav)",
            filetypes=[("Palworld save files", "*.sav"), ("All files", "*.*")],
        )
        if not path:
            return
        try:
            self._load_player_sav_path(path, quiet=False)
        except (OSError, ValueError) as exc:
            messagebox.showerror("Couldn't load player save", str(exc))


    def _load_pals_into_editor(self):
        global entries, selected_id
        self.loaded_sav_json = sav_to_json_dict(self.loaded_sav_bytes)
        self.map_entries = build_map_entries_from_json(self.loaded_sav_json)
        self._map_entries_source_id = id(self.loaded_sav_json)
        self._update_profile_chip_from_world(self.map_entries)
        pal_entries, field_refs = build_pal_entries_from_json(self.loaded_sav_json)
        self.pal_field_refs = field_refs
        self._palbox_container_id = find_palbox_container_id(self.loaded_sav_json)
        self._party_container_ids = find_party_container_ids(self.loaded_sav_json)

        self.inventory_containers, self.inventory_slot_refs, self.inventory_slots_field_values = \
            build_inventory_from_json(self.loaded_sav_json, self.player_container_ids)

        # Player-save matching is useful but not required to finish opening
        # Level.sav. Run it after the initial UI response instead of blocking
        # the save-load operation and redraw.
        previous_job = getattr(self, "_auto_player_match_after", None)
        if previous_job is not None:
            try:
                self.after_cancel(previous_job)
            except tk.TclError:
                pass
        self._auto_player_match_after = self.after(
            50, self._finish_deferred_player_match)

        if not pal_entries:
            messagebox.showwarning(
                "No editable pals found",
                "Loaded the save, but couldn't find any decodable pal records "
                "in it (CharacterSaveParameterMap may be missing or in a "
                "format this parser doesn't recognize). The Pal Editor tab "
                "still shows the sample data.",
            )
            return
        entries.clear()
        entries.extend(pal_entries)
        selected_id = entries[0]["id"]
        if getattr(self, "_current_view_key", None) == "editor":
            self.render_all()
        elif getattr(self, "_current_view_key", None) == "inventory":
            self.render_inventory()
        if hasattr(self, "tools_status_frame"):
            self._render_tools_status()
        n_items = sum(c["item_count"] for c in self.inventory_containers)
        messagebox.showinfo(
            "Pals loaded",
            f"Loaded {len(pal_entries)} pal/character record(s) into the Pal "
            f"Editor tab, and {n_items} item stacks across "
            f"{len(self.inventory_containers)} containers into the Inventory tab. "
            f"Edit them there, then use \"Export Save\" (or Tools \u2192 Convert "
            f"to .json / JSON Editor) to write your changes back to a .sav file.",
        )

    def _finish_deferred_player_match(self):
        self._auto_player_match_after = None
        token = uuid.uuid4().hex
        self._auto_match_token = token
        self._auto_match_result = None
        try:
            app_dir = os.path.dirname(os.path.abspath(__file__))
        except NameError:
            app_dir = os.getcwd()
        player_dirs = [os.path.join(app_dir, "Players")]
        if getattr(self, "loaded_sav_path", None):
            adjacent = os.path.join(
                os.path.dirname(os.path.abspath(self.loaded_sav_path)),
                "Players")
            if os.path.normcase(adjacent) != os.path.normcase(player_dirs[0]):
                player_dirs.append(adjacent)
        candidates = []
        for player_dir in player_dirs:
            try:
                candidates.extend(
                    os.path.join(player_dir, name)
                    for name in os.listdir(player_dir)
                    if name.lower().endswith(".sav")
                    and not name.lower().endswith("_dps.sav"))
            except OSError:
                pass
        loaded_path = (
            os.path.normcase(os.path.abspath(self.loaded_sav_path))
            if getattr(self, "loaded_sav_path", None) else "")
        candidates = [
            path for path in candidates
            if os.path.normcase(os.path.abspath(path)) != loaded_path]
        level_container_ids = [
            container.get("container_id")
            for container in getattr(self, "inventory_containers", [])
            if container.get("container_id")]
        if not candidates or not level_container_ids:
            return
        oodle_path = (
            self.oodle_decompressor.lib_path
            if self.oodle_decompressor else None)

        def worker():
            result_queue = None
            process = None
            try:
                context = multiprocessing.get_context("spawn")
                result_queue = context.Queue(maxsize=1)
                process = context.Process(
                    target=_match_player_save_in_process,
                    args=(
                        candidates, level_container_ids,
                        oodle_path, result_queue),
                    name="PalPlayerSaveMatcher",
                    daemon=True)
                process.start()
                while True:
                    try:
                        result = result_queue.get(timeout=0.15)
                        break
                    except queue.Empty:
                        if not process.is_alive():
                            result = {
                                "ok": False,
                                "error": "Player-save matcher stopped unexpectedly."}
                            break
            except Exception as exc:
                result = {"ok": False, "error": str(exc)}
            finally:
                try:
                    if process is not None:
                        process.join(timeout=0.5)
                except Exception:
                    pass
                try:
                    if result_queue is not None:
                        result_queue.close()
                except Exception:
                    pass
            if getattr(self, "_auto_match_token", None) == token:
                self._auto_match_result = result

        threading.Thread(
            target=worker, name="PalPlayerSaveMatcher", daemon=True).start()
        self.after(40, lambda: self._poll_deferred_player_match(token))

    def _poll_deferred_player_match(self, token):
        if getattr(self, "_auto_match_token", None) != token:
            return
        result = getattr(self, "_auto_match_result", None)
        if result is None:
            self.after(40, lambda: self._poll_deferred_player_match(token))
            return
        self._auto_match_result = None
        if result.get("ok") and result.get("matched"):
            self.player_container_ids = result["container_ids"]
            self.auto_player_sav_path = result["path"]
            (self.inventory_containers,
             self.inventory_slot_refs,
             self.inventory_slots_field_values) = build_inventory_from_json(
                 self.loaded_sav_json, self.player_container_ids)
            self._data_revision = getattr(self, "_data_revision", 0) + 1
            if getattr(self, "_current_view_key", None) == "inventory":
                self.render_inventory()
                self._view_render_revision["inventory"] = self._data_revision
            if hasattr(self, "tools_status_frame"):
                self._render_tools_status()

    def convert_sav_to_json(self):
        if not self.loaded_sav_bytes:
            messagebox.showwarning("No save loaded", "Load a .sav file first.")
            return

        parsed = sav_to_json_dict(self.loaded_sav_bytes)
        if "_parse_error" in parsed:
            proceed = messagebox.askyesno(
                "Couldn't parse this save's header",
                f"The GVAS header parser hit an error: {parsed['_parse_error']}\n\n"
                f"The raw decompressed bytes are still saved losslessly inside the JSON "
                f"(base64-encoded), so nothing is lost, but there won't be any editable "
                f"fields \u2014 just the raw blob. Save it anyway?",
            )
            if not proceed:
                return

        default_name = os.path.splitext(os.path.basename(self.loaded_sav_path))[0] + ".json"
        out_path = filedialog.asksaveasfilename(
            title="Save as JSON", defaultextension=".json", initialfile=default_name,
            filetypes=[("JSON files", "*.json"), ("All files", "*.*")],
        )
        if not out_path:
            return

        try:
            with open(out_path, "w", encoding="utf-8") as f:
                json.dump(parsed, f, indent=2)
        except OSError as e:
            messagebox.showerror("Couldn't write JSON", str(e))
            return

        props = parsed.get("properties", [])
        n_props = len(props)
        hit_raw_tail = bool(props) and props[-1].get("type") == "__RAW_TAIL__"
        if "_parse_error" in parsed:
            summary = "Saved as a raw byte blob (header parser couldn't read the property list)."
        elif hit_raw_tail:
            summary = (f"{n_props - 1} properties parsed before the parser hit something it "
                       f"didn't recognize; everything from that point on is preserved as an "
                       f"exact raw byte tail (nothing lost, just not broken out into fields).")
        else:
            summary = f"All {n_props} top-level properties parsed cleanly."
        messagebox.showinfo("Converted to JSON", f"Saved:\n{out_path}\n\n{summary}")

    def convert_json_to_sav(self):
        json_path = filedialog.askopenfilename(
            title="Choose the JSON file to convert",
            filetypes=[("JSON files", "*.json"), ("All files", "*.*")],
        )
        if not json_path:
            return

        try:
            with open(json_path, "r", encoding="utf-8") as f:
                obj = json.load(f)
        except (OSError, json.JSONDecodeError) as e:
            messagebox.showerror("Couldn't read JSON", str(e))
            return

        try:
            gvas_bytes = json_dict_to_gvas_bytes(obj)
        except ValueError as e:
            messagebox.showerror("Couldn't rebuild save", str(e))
            return

        sav_bytes = compress_sav(gvas_bytes, save_type=0x31)

        default_name = os.path.splitext(os.path.basename(json_path))[0] + ".sav"
        out_path = filedialog.asksaveasfilename(
            title="Save as .sav", defaultextension=".sav", initialfile=default_name,
            filetypes=[("Palworld save files", "*.sav"), ("All files", "*.*")],
        )
        if not out_path:
            return

        try:
            with open(out_path, "wb") as f:
                f.write(sav_bytes)
        except OSError as e:
            messagebox.showerror("Couldn't write .sav", str(e))
            return

        messagebox.showinfo("Converted to .sav",
                             f"Saved:\n{out_path}\n\n"
                             f"Written as single-pass zlib (Palworld reads this regardless of "
                             f"whether the original file was zlib or Oodle-compressed).\n\n"
                             f"Back up your original save before replacing it with this one.")

    def _render_tools_status(self):
        if hasattr(self, "tools_world_info_label"):
            if getattr(self, "loaded_sav_path", None):
                self.tools_world_info_label.configure(
                    text=f"Loaded: {os.path.basename(self.loaded_sav_path)}\n{self.loaded_sav_path}",
                    fg=COLOR["good"])
                self.tools_json_export_info_label.configure(text="Ready: a save is loaded.", fg=COLOR["good"])
            else:
                self.tools_world_info_label.configure(text="Status: No world save loaded.", fg=COLOR["text2"])
                self.tools_json_export_info_label.configure(text="Load a world save first.", fg=COLOR["text2"])
            player_path = getattr(self, "auto_player_sav_path", None)
            if player_path:
                self.tools_player_info_label.configure(
                    text=f"Matched automatically: {os.path.basename(player_path)}", fg=COLOR["good"])
            elif getattr(self, "player_container_ids", None):
                self.tools_player_info_label.configure(text="Player save data loaded.", fg=COLOR["good"])
            else:
                self.tools_player_info_label.configure(text="Status: No matching player save loaded yet.", fg=COLOR["text2"])
            self.tools_json_import_info_label.configure(text="Select a JSON file when ready.", fg=COLOR["text1"])
            if self.oodle_decompressor:
                self.tools_oodle_info_label.configure(
                    text=f"Loaded: {os.path.basename(self.oodle_decompressor.lib_path)}", fg=COLOR["good"])
            else:
                self.tools_oodle_info_label.configure(text="Status: Not loaded (optional).", fg=COLOR["text2"])
            if PIL_AVAILABLE:
                image_dir = getattr(self, "pal_image_dir", None)
                self.tools_images_info_label.configure(
                    text=f"Folder: {image_dir}" if image_dir else "Status: Using built-in icons.",
                    fg=COLOR["good"] if image_dir else COLOR["text2"])
            else:
                self.tools_images_info_label.configure(text="Pillow is not installed; image folders are unavailable.", fg=COLOR["warn"])

        for w in self.tools_status_frame.winfo_children():
            w.destroy()

        oodle_row = tk.Frame(self.tools_status_frame, bg=COLOR["bg1"])
        oodle_row.pack(fill="x", anchor="w", pady=(0, 14))
        if self.oodle_decompressor:
            tk.Label(oodle_row, text="\u25CF Oodle library loaded: ", bg=COLOR["bg1"],
                     fg=COLOR["good"], font=("Segoe UI", 9)).pack(side="left")
            tk.Label(oodle_row, text=os.path.basename(self.oodle_decompressor.lib_path),
                     bg=COLOR["bg1"], fg=COLOR["text1"], font=FONT_MONO).pack(side="left")
        else:
            tk.Label(oodle_row, text="\u25CB Oodle library not loaded (only needed for Oodle-compressed saves)",
                     bg=COLOR["bg1"], fg=COLOR["text2"], font=("Segoe UI", 9)).pack(side="left")

        if not self.loaded_sav_path:
            tk.Label(self.tools_status_frame, text="No save file loaded yet.",
                     bg=COLOR["bg1"], fg=COLOR["text2"], font=FONT_UI).pack(anchor="w")
            return

        card = tk.Frame(self.tools_status_frame, bg=COLOR["bg1"], highlightthickness=1,
                         highlightbackground=COLOR["line"])
        card.pack(fill="x", anchor="w")

        def info_row(label, value):
            row = tk.Frame(card, bg=COLOR["bg1"])
            row.pack(fill="x", padx=14, pady=4)
            tk.Label(row, text=label, bg=COLOR["bg1"], fg=COLOR["text2"],
                     font=("Segoe UI", 9), width=16, anchor="w").pack(side="left")
            tk.Label(row, text=value, bg=COLOR["bg1"], fg=COLOR["text0"],
                     font=FONT_MONO, anchor="w", wraplength=520, justify="left").pack(side="left", fill="x")

        tk.Frame(card, bg=COLOR["bg1"], height=10).pack()  # top padding
        info_row("File", os.path.basename(self.loaded_sav_path))
        info_row("Full path", self.loaded_sav_path)
        info_row("Raw size", f"{self.loaded_sav_raw_size:,} bytes")
        info_row("Decompressed", f"{len(self.loaded_sav_bytes):,} bytes")
        info_row("Method", self.loaded_sav_method)
        tk.Frame(card, bg=COLOR["bg1"], height=10).pack()  # bottom padding


    def _build_json_editor(self, parent):
        """Build a structured, expandable JSON tree instead of a raw text editor."""
        frame = tk.Frame(parent, bg=COLOR["bg0"])
        self.json_editor_source_path = None
        self.json_editor_data = None
        self._json_tree_paths = {}
        self._json_tree_search_matches = []
        self._json_tree_search_index = -1

        toolbar = tk.Frame(frame, bg=COLOR["bg0"])
        toolbar.pack(fill="x", padx=20, pady=(18, 8))

        def mk_btn(parent_, text, cmd, primary=False):
            button = tk.Button(
                parent_, text=text, command=cmd,
                bg=COLOR["accent"] if primary else COLOR["bg3"],
                fg="#ffffff" if primary else COLOR["text0"],
                activebackground=COLOR["accent"] if primary else COLOR["bg3"],
                activeforeground="#ffffff" if primary else COLOR["text0"],
                relief="flat", bd=0, font=("Segoe UI", 9, "bold" if primary else "normal"),
                padx=12, pady=7, cursor="hand2",
            )
            button.pack(side="left", padx=(0, 8))
            return button

        mk_btn(toolbar, "Refresh from Save", self.json_editor_load_from_sav, primary=True)
        mk_btn(toolbar, "Export JSON", self.json_editor_save_file)
        mk_btn(toolbar, "Import JSON", self.json_editor_open_file)
        mk_btn(toolbar, "Export as .sav", self.json_editor_export_sav)
        mk_btn(toolbar, "Clear", self.json_editor_clear)

        self.json_editor_status = tk.Label(
            toolbar, text="No JSON loaded yet.", bg=COLOR["bg0"], fg=COLOR["text2"],
            font=("Segoe UI", 9), anchor="e",
        )
        self.json_editor_status.pack(side="right", fill="x", expand=True)

        search_row = tk.Frame(frame, bg=COLOR["bg0"])
        search_row.pack(fill="x", padx=20, pady=(0, 8))
        self.json_editor_search_var = tk.StringVar()
        search_entry = tk.Entry(
            search_row, textvariable=self.json_editor_search_var, font=FONT_UI,
            bg=COLOR["bg2"], fg=COLOR["text0"], insertbackground=COLOR["text0"],
            relief="flat",
        )
        search_entry.pack(side="left", fill="x", expand=True, ipady=6)
        self._set_placeholder(search_entry, "Search...")
        search_entry.bind("<Return>", lambda _e: self.json_editor_find_next())
        search_entry.bind(
            "<KeyRelease>",
            lambda _e: self._debounce("json_tree_search", self._json_editor_search_reset, 180),
        )
        mk_btn(search_row, "▲", self.json_editor_find_prev)
        mk_btn(search_row, "▼", self.json_editor_find_next)

        tree_wrap = tk.Frame(
            frame, bg=COLOR["bg1"], highlightthickness=1,
            highlightbackground=COLOR["line"],
        )
        tree_wrap.pack(fill="both", expand=True, padx=20, pady=(0, 20))

        self.json_editor_tree = ttk.Treeview(
            tree_wrap, columns=("value", "type"), show="tree headings", selectmode="browse",
        )
        self.json_editor_tree.heading("#0", text="Key", anchor="w")
        self.json_editor_tree.heading("value", text="Value", anchor="w")
        self.json_editor_tree.heading("type", text="Type", anchor="w")
        self.json_editor_tree.column("#0", width=340, minwidth=150, stretch=True, anchor="w")
        self.json_editor_tree.column("value", width=470, minwidth=150, stretch=True, anchor="w")
        self.json_editor_tree.column("type", width=150, minwidth=90, stretch=False, anchor="w")

        y_scroll = ttk.Scrollbar(tree_wrap, orient="vertical", command=self.json_editor_tree.yview)
        x_scroll = ttk.Scrollbar(tree_wrap, orient="horizontal", command=self.json_editor_tree.xview)
        self.json_editor_tree.configure(yscrollcommand=y_scroll.set, xscrollcommand=x_scroll.set)
        self.json_editor_tree.grid(row=0, column=0, sticky="nsew")
        y_scroll.grid(row=0, column=1, sticky="ns")
        x_scroll.grid(row=1, column=0, sticky="ew")
        tree_wrap.grid_rowconfigure(0, weight=1)
        tree_wrap.grid_columnconfigure(0, weight=1)

        self.json_editor_tree.bind("<<TreeviewOpen>>", self._json_tree_on_open)
        self.json_editor_tree.bind("<Double-1>", self._json_tree_begin_edit)
        self.json_editor_tree.bind("<Return>", self._json_tree_begin_edit)
        return frame

    @staticmethod
    def _json_tree_type(value):
        if isinstance(value, dict):
            return f"dict ({len(value)})"
        if isinstance(value, list):
            return f"list ({len(value)})"
        if value is None:
            return "null"
        if isinstance(value, bool):
            return "bool"
        if isinstance(value, int):
            return "int"
        if isinstance(value, float):
            return "float"
        return "str"

    @staticmethod
    def _json_tree_value_preview(value):
        if isinstance(value, dict):
            return "{...}"
        if isinstance(value, list):
            return "[...]"
        if value is None:
            return "null"
        if isinstance(value, bool):
            return "true" if value else "false"
        text = str(value)
        return text if len(text) <= 220 else text[:217] + "..."

    def _json_tree_get_value(self, path):
        value = self.json_editor_data
        for key in path:
            value = value[key]
        return value

    def _json_tree_set_value(self, path, value):
        if not path:
            self.json_editor_data = value
            return
        parent = self._json_tree_get_value(path[:-1])
        parent[path[-1]] = value

    def _json_tree_insert_node(self, parent_iid, key, value, path):
        iid = self.json_editor_tree.insert(
            parent_iid, "end", text=str(key),
            values=(self._json_tree_value_preview(value), self._json_tree_type(value)),
        )
        self._json_tree_paths[iid] = tuple(path)
        if isinstance(value, (dict, list)) and value:
            self.json_editor_tree.insert(iid, "end", text="", values=("", ""), tags=("json_dummy",))
        return iid

    def _json_tree_populate_children(self, iid):
        children = self.json_editor_tree.get_children(iid)
        if not children:
            return
        if not any("json_dummy" in self.json_editor_tree.item(child, "tags") for child in children):
            return
        for child in children:
            self.json_editor_tree.delete(child)
            self._json_tree_paths.pop(child, None)
        path = self._json_tree_paths.get(iid, ())
        value = self._json_tree_get_value(path)
        iterable = value.items() if isinstance(value, dict) else enumerate(value)
        for key, child_value in iterable:
            self._json_tree_insert_node(iid, key, child_value, path + (key,))

    def _json_tree_on_open(self, _event=None):
        iid = self.json_editor_tree.focus()
        if iid:
            self._json_tree_populate_children(iid)

    def _json_tree_render(self):
        tree = self.json_editor_tree
        tree.delete(*tree.get_children())
        self._json_tree_paths.clear()
        self._json_tree_search_matches = []
        self._json_tree_search_index = -1
        if self.json_editor_data is None:
            return
        root = self._json_tree_insert_node("", "{...}" if isinstance(self.json_editor_data, dict) else "[...]",
                                           self.json_editor_data, ())
        tree.item(root, open=True)
        self._json_tree_populate_children(root)

    def _json_tree_begin_edit(self, event=None):
        tree = self.json_editor_tree
        iid = tree.focus()
        if event is not None and getattr(event, "y", None) is not None:
            clicked = tree.identify_row(event.y)
            if clicked:
                iid = clicked
                tree.selection_set(iid)
                tree.focus(iid)
        path = self._json_tree_paths.get(iid)
        if path is None:
            return
        value = self._json_tree_get_value(path)
        if isinstance(value, (dict, list)):
            tree.item(iid, open=not tree.item(iid, "open"))
            if tree.item(iid, "open"):
                self._json_tree_populate_children(iid)
            return

        editor = tk.Toplevel(self)
        editor.title("Edit JSON Value")
        editor.configure(bg=COLOR["bg1"])
        editor.transient(self)
        editor.resizable(True, False)
        editor.geometry("620x190")
        editor.grab_set()

        tk.Label(editor, text="Path", bg=COLOR["bg1"], fg=COLOR["text2"],
                 font=("Segoe UI", 8)).pack(anchor="w", padx=16, pady=(14, 2))
        path_text = ".".join(str(part) for part in path) or "root"
        tk.Label(editor, text=path_text, bg=COLOR["bg1"], fg=COLOR["text0"],
                 font=FONT_MONO, anchor="w").pack(fill="x", padx=16)

        value_type = self._json_tree_type(value)
        tk.Label(editor, text=f"Value ({value_type})", bg=COLOR["bg1"], fg=COLOR["text2"],
                 font=("Segoe UI", 8)).pack(anchor="w", padx=16, pady=(10, 2))
        value_var = tk.StringVar(value=self._json_tree_value_preview(value))
        if isinstance(value, bool) or value is None:
            value_widget = ttk.Combobox(editor, textvariable=value_var, state="readonly",
                                        values=("true", "false", "null"))
        else:
            value_widget = tk.Entry(editor, textvariable=value_var, bg=COLOR["bg2"],
                                    fg=COLOR["text0"], insertbackground=COLOR["text0"],
                                    relief="flat", font=FONT_MONO)
        value_widget.pack(fill="x", padx=16, ipady=5)
        value_widget.focus_set()
        if isinstance(value_widget, tk.Entry):
            value_widget.selection_range(0, "end")

        def save_edit():
            raw = value_var.get()
            try:
                if value is None:
                    converted = None if raw == "null" else raw == "true"
                elif isinstance(value, bool):
                    converted = raw == "true"
                elif isinstance(value, int) and not isinstance(value, bool):
                    converted = int(raw)
                elif isinstance(value, float):
                    converted = float(raw)
                else:
                    converted = raw
            except ValueError:
                messagebox.showerror("Invalid value", f"Enter a valid {value_type} value.", parent=editor)
                return
            self._json_tree_set_value(path, converted)
            tree.item(iid, values=(self._json_tree_value_preview(converted), self._json_tree_type(converted)))
            self._json_editor_set_status(f"Updated {path_text}", "good")
            editor.destroy()

        buttons = tk.Frame(editor, bg=COLOR["bg1"])
        buttons.pack(fill="x", padx=16, pady=14)
        tk.Button(buttons, text="Save", command=save_edit, bg=COLOR["accent"], fg="#ffffff",
                  relief="flat", bd=0, padx=16, pady=6).pack(side="left")
        tk.Button(buttons, text="Cancel", command=editor.destroy, bg=COLOR["bg3"],
                  fg=COLOR["text0"], relief="flat", bd=0, padx=16, pady=6).pack(side="left", padx=8)
        editor.bind("<Return>", lambda _e: save_edit())
        editor.bind("<Escape>", lambda _e: editor.destroy())

    def _json_editor_search_reset(self):
        self._json_tree_search_matches = []
        self._json_tree_search_index = -1
        if self.json_editor_search_var.get().strip() and self.json_editor_search_var.get() != "Search...":
            self._json_tree_build_search_matches()
        else:
            self._json_editor_set_status("JSON loaded." if self.json_editor_data is not None else "No JSON loaded yet.")

    def _json_tree_walk(self, value, path=()):
        yield path, value
        if isinstance(value, dict):
            for key, child in value.items():
                yield from self._json_tree_walk(child, path + (key,))
        elif isinstance(value, list):
            for index, child in enumerate(value):
                yield from self._json_tree_walk(child, path + (index,))

    def _json_tree_build_search_matches(self):
        query = self.json_editor_search_var.get().strip().lower()
        if not query or query == "search..." or self.json_editor_data is None:
            return
        matches = []
        for path, value in self._json_tree_walk(self.json_editor_data):
            key_text = str(path[-1]).lower() if path else "root"
            value_text = self._json_tree_value_preview(value).lower()
            if query in key_text or query in value_text:
                matches.append(path)
        self._json_tree_search_matches = matches
        self._json_tree_search_index = -1
        self._json_editor_set_status(f"{len(matches)} match{'es' if len(matches) != 1 else ''}.")

    def _json_tree_reveal_path(self, path):
        tree = self.json_editor_tree
        roots = tree.get_children("")
        if not roots:
            return None
        iid = roots[0]
        tree.item(iid, open=True)
        self._json_tree_populate_children(iid)
        current_path = ()
        for component in path:
            target_path = current_path + (component,)
            found = None
            for child in tree.get_children(iid):
                if self._json_tree_paths.get(child) == target_path:
                    found = child
                    break
            if found is None:
                return None
            iid = found
            current_path = target_path
            if current_path != path:
                tree.item(iid, open=True)
                self._json_tree_populate_children(iid)
        tree.selection_set(iid)
        tree.focus(iid)
        tree.see(iid)
        return iid

    def json_editor_find_next(self):
        if not self._json_tree_search_matches:
            self._json_tree_build_search_matches()
        if not self._json_tree_search_matches:
            return
        self._json_tree_search_index = (self._json_tree_search_index + 1) % len(self._json_tree_search_matches)
        self._json_tree_reveal_path(self._json_tree_search_matches[self._json_tree_search_index])
        self._json_editor_set_status(
            f"Match {self._json_tree_search_index + 1} of {len(self._json_tree_search_matches)}"
        )

    def json_editor_find_prev(self):
        if not self._json_tree_search_matches:
            self._json_tree_build_search_matches()
        if not self._json_tree_search_matches:
            return
        self._json_tree_search_index = (self._json_tree_search_index - 1) % len(self._json_tree_search_matches)
        self._json_tree_reveal_path(self._json_tree_search_matches[self._json_tree_search_index])
        self._json_editor_set_status(
            f"Match {self._json_tree_search_index + 1} of {len(self._json_tree_search_matches)}"
        )

    def json_editor_format(self):
        self._json_tree_render()
        self._json_editor_set_status("Tree refreshed.", "good")

    def _json_editor_set_status(self, text, kind="info"):
        color = {"info": COLOR["text2"], "good": COLOR["good"], "bad": COLOR["danger"]}.get(kind, COLOR["text2"])
        self.json_editor_status.configure(text=text, fg=color)

    def json_editor_load_from_sav(self):
        if not getattr(self, "loaded_sav_bytes", None):
            messagebox.showwarning("No save loaded", "Load a .sav file in the Tools tab first.")
            return
        parsed = sav_to_json_dict(self.loaded_sav_bytes)
        self.json_editor_data = parsed
        self.json_editor_source_path = None
        self._json_tree_render()
        props = parsed.get("properties", []) if isinstance(parsed, dict) else []
        hit_tail = bool(props) and isinstance(props[-1], dict) and props[-1].get("type") == "__RAW_TAIL__"
        if isinstance(parsed, dict) and "_parse_error" in parsed:
            self._json_editor_set_status(f"Loaded with parse warning: {parsed['_parse_error']}", "bad")
        elif hit_tail:
            self._json_editor_set_status(f"JSON loaded from save — {len(props) - 1} properties plus raw tail.", "info")
        else:
            self._json_editor_set_status(f"JSON loaded from save — {len(props)} properties.", "good")

    def json_editor_open_file(self):
        path = filedialog.askopenfilename(title="Import JSON", filetypes=[("JSON files", "*.json"), ("All files", "*.*")])
        if not path:
            return
        try:
            with open(path, "r", encoding="utf-8") as handle:
                parsed = json.load(handle)
        except (OSError, json.JSONDecodeError) as error:
            messagebox.showerror("Couldn't import JSON", str(error))
            return
        self.json_editor_data = parsed
        self.json_editor_source_path = path
        self._json_tree_render()
        self._json_editor_set_status(f"Imported {os.path.basename(path)}", "good")

    def json_editor_validate(self):
        if self.json_editor_data is None:
            self._json_editor_set_status("Nothing to validate — no JSON is loaded.", "info")
            return None
        try:
            json.dumps(self.json_editor_data)
        except (TypeError, ValueError) as error:
            self._json_editor_set_status(f"Invalid JSON value: {error}", "bad")
            return None
        count = len(self.json_editor_data.get("properties", [])) if isinstance(self.json_editor_data, dict) else None
        self._json_editor_set_status(
            f"Valid JSON — {count} top-level properties." if count is not None else "Valid JSON.", "good"
        )
        return self.json_editor_data

    def json_editor_save_file(self):
        obj = self.json_editor_validate()
        if obj is None:
            messagebox.showwarning("Nothing to export", "Load JSON before exporting it.")
            return
        default_name = os.path.basename(self.json_editor_source_path) if self.json_editor_source_path else "save.json"
        out_path = filedialog.asksaveasfilename(
            title="Export JSON", defaultextension=".json", initialfile=default_name,
            filetypes=[("JSON files", "*.json"), ("All files", "*.*")],
        )
        if not out_path:
            return
        try:
            with open(out_path, "w", encoding="utf-8") as handle:
                json.dump(obj, handle, indent=2, ensure_ascii=False)
        except OSError as error:
            messagebox.showerror("Couldn't export JSON", str(error))
            return
        self.json_editor_source_path = out_path
        self._json_editor_set_status(f"Exported {os.path.basename(out_path)}", "good")

    def json_editor_export_sav(self):
        obj = self.json_editor_validate()
        if obj is None:
            messagebox.showerror("Can't export", "Load valid JSON first.")
            return
        try:
            gvas_bytes = json_dict_to_gvas_bytes(obj)
        except ValueError as error:
            messagebox.showerror("Couldn't rebuild save", str(error))
            return
        sav_bytes = compress_sav(gvas_bytes, save_type=0x31)
        default_name = (os.path.splitext(os.path.basename(self.json_editor_source_path))[0] + ".sav"
                        if self.json_editor_source_path else "save.sav")
        out_path = filedialog.asksaveasfilename(
            title="Export as .sav", defaultextension=".sav", initialfile=default_name,
            filetypes=[("Palworld save files", "*.sav"), ("All files", "*.*")],
        )
        if not out_path:
            return
        try:
            with open(out_path, "wb") as handle:
                handle.write(sav_bytes)
        except OSError as error:
            messagebox.showerror("Couldn't write .sav", str(error))
            return
        messagebox.showinfo("Exported", f"Saved:\n{out_path}\n\nBack up your original save before replacing it.")

    def json_editor_clear(self):
        if self.json_editor_data is not None:
            if not messagebox.askyesno("Clear editor", "Discard the currently loaded JSON tree?"):
                return
        self.json_editor_data = None
        self.json_editor_source_path = None
        self.json_editor_search_var.set("")
        self._json_tree_render()
        self._json_editor_set_status("No JSON loaded yet.", "info")

    def _build_docs(self, parent):
        frame = tk.Frame(parent, bg=COLOR["bg0"])

        cat_panel = tk.Frame(frame, bg=COLOR["bg1"], width=160,
                              highlightthickness=1, highlightbackground=COLOR["line"])
        cat_panel.pack(side="left", fill="y")
        cat_panel.pack_propagate(False)

        categories = ["Pals", "Items", "Buildings", "Active Skills",
                      "Passive Skills", "Technologies", "Elements", "Work Suitability"]
        self.doc_cat_buttons = {}
        for cat in categories:
            key = cat.lower().replace(" ", "_")
            btn = tk.Label(cat_panel, text=cat, bg=COLOR["bg1"], fg=COLOR["text1"],
                            font=FONT_UI, anchor="w", padx=14, pady=8, cursor="hand2")
            btn.pack(fill="x")
            btn.bind("<Button-1>", lambda e, k=key: self.select_doc_category(k))
            self.doc_cat_buttons[key] = btn

        list_panel = tk.Frame(frame, bg=COLOR["bg1"], width=360,
                               highlightthickness=1, highlightbackground=COLOR["line"])
        list_panel.pack(side="left", fill="y")
        list_panel.pack_propagate(False)

        search_row = tk.Frame(list_panel, bg=COLOR["bg1"])
        search_row.pack(fill="x", padx=10, pady=10)
        self.doc_search_var = tk.StringVar()
        search_entry = tk.Entry(search_row, textvariable=self.doc_search_var, font=FONT_UI,
                                 bg=COLOR["bg2"], fg=COLOR["text0"], relief="flat",
                                 insertbackground=COLOR["text0"])
        search_entry.insert(0, "")
        search_entry.pack(fill="x", ipady=4)
        search_entry.bind("<KeyRelease>", lambda e: self._debounce("docs_search", self.render_docs_list, 180))
        self._set_placeholder(search_entry, "Search...")

        sort_row = tk.Frame(list_panel, bg=COLOR["bg1"])
        sort_row.pack(fill="x", padx=10, pady=(0, 6))
        self.doc_sort_key = "num"
        self.doc_sort_reverse = False
        self.doc_sort_buttons = {}
        self.doc_sort_labels = {"name": "Name", "num": "#",
                                "rank": "Rank", "hp": "HP",
                                "power": "Power", "cooldown": "Cooldown",
                                "tier": "Tier", "level_cap": "Lv.Cap",
                                "cost": "Cost"}
        for key, label in self.doc_sort_labels.items():
            btn = tk.Label(sort_row, text=label, font=("Segoe UI", 8, "bold"),
                            padx=8, pady=2, cursor="hand2")
            btn.bind("<Button-1>", lambda e, k=key: self.set_doc_sort(k))
            self.doc_sort_buttons[key] = btn
        self._configure_doc_sort_buttons(("name", "num"))
        self._refresh_sort_buttons()

        filter_row = tk.Frame(list_panel, bg=COLOR["bg1"])
        filter_row.pack(fill="x", padx=10, pady=(0, 8))
        tk.Label(filter_row, text="Element:", bg=COLOR["bg1"], fg=COLOR["text2"],
                 font=("Segoe UI", 8)).pack(side="left")
        element_dots = [COLOR["text1"], "#c56bd6", COLOR["warn"], COLOR["danger"],
                         "#4fd1e0", COLOR["good"], COLOR["text1"], COLOR["accent"]]
        for c in element_dots:
            tk.Label(filter_row, text="\u25CF", bg=COLOR["bg1"], fg=c, font=("Segoe UI", 10)).pack(side="left", padx=2)
        self.doc_pal_filter_row = filter_row

        self.doc_item_cat_frame = tk.Frame(list_panel, bg=COLOR["bg1"])

        list_canvas = tk.Canvas(list_panel, bg=COLOR["bg1"], highlightthickness=0)
        self.doc_list_canvas = list_canvas
        list_scroll = ttk.Scrollbar(list_panel, orient="vertical", command=list_canvas.yview)
        self.doc_list_frame = tk.Frame(list_canvas, bg=COLOR["bg1"])
        self.doc_list_frame.bind("<Configure>", lambda e: list_canvas.configure(scrollregion=list_canvas.bbox("all")))
        list_canvas.create_window((0, 0), window=self.doc_list_frame, anchor="nw", width=336)
        list_canvas.configure(yscrollcommand=list_scroll.set)
        list_canvas.pack(side="left", fill="both", expand=True, padx=(6, 0))
        list_scroll.pack(side="right", fill="y")
        self.doc_list_scroll = list_scroll

        self.doc_building_tree = ttk.Treeview(
            list_panel, show="tree", selectmode="browse")
        self.doc_building_tree.column("#0", width=326, minwidth=220,
                                      stretch=True)
        self.doc_building_scroll = ttk.Scrollbar(
            list_panel, orient="vertical",
            command=self.doc_building_tree.yview)
        self.doc_building_tree.configure(
            yscrollcommand=self.doc_building_scroll.set)
        self.doc_building_tree.bind(
            "<<TreeviewSelect>>", self._on_doc_catalog_tree_select)

        def _on_list_mousewheel(event):
            delta = event.delta
            if delta == 0:
                return
            step = -int(delta / 120) if abs(delta) >= 100 else (-1 if delta > 0 else 1)
            list_canvas.yview_scroll(step, "units")

        def _bind_list_wheel(_e=None):
            list_canvas.bind_all("<MouseWheel>", _on_list_mousewheel)
            list_canvas.bind_all("<Button-4>", lambda e: list_canvas.yview_scroll(-1, "units"))
            list_canvas.bind_all("<Button-5>", lambda e: list_canvas.yview_scroll(1, "units"))

        def _unbind_list_wheel(_e=None):
            list_canvas.unbind_all("<MouseWheel>")
            list_canvas.unbind_all("<Button-4>")
            list_canvas.unbind_all("<Button-5>")

        list_canvas.bind("<Enter>", _bind_list_wheel)
        list_canvas.bind("<Leave>", _unbind_list_wheel)

        detail_wrap = tk.Frame(frame, bg=COLOR["bg0"])
        detail_wrap.pack(side="left", fill="both", expand=True)

        detail_canvas = tk.Canvas(detail_wrap, bg=COLOR["bg0"], highlightthickness=0)
        detail_scroll = ttk.Scrollbar(detail_wrap, orient="vertical", command=detail_canvas.yview)
        self.doc_detail_inner = tk.Frame(detail_canvas, bg=COLOR["bg0"])

        def _on_detail_configure(_e=None):
            detail_canvas.configure(scrollregion=detail_canvas.bbox("all"))

        def _on_canvas_resize(e):
            detail_canvas.itemconfig(detail_window, width=max(0, e.width - 48))

        self.doc_detail_inner.bind("<Configure>", _on_detail_configure)
        detail_window = detail_canvas.create_window((24, 20), window=self.doc_detail_inner, anchor="nw")
        detail_canvas.bind("<Configure>", _on_canvas_resize)
        detail_canvas.configure(yscrollcommand=detail_scroll.set)
        detail_canvas.pack(side="left", fill="both", expand=True)
        detail_scroll.pack(side="right", fill="y")

        def _on_mousewheel(event):
            delta = event.delta
            if delta == 0:
                return
            step = -1 if delta > 0 else 1
            if abs(delta) >= 100:  # normalize Windows/Linux large-delta events
                step = -int(delta / 120) if delta else 0
            detail_canvas.yview_scroll(step, "units")

        def _bind_wheel(_e=None):
            detail_canvas.bind_all("<MouseWheel>", _on_mousewheel)
            detail_canvas.bind_all("<Button-4>", lambda e: detail_canvas.yview_scroll(-1, "units"))
            detail_canvas.bind_all("<Button-5>", lambda e: detail_canvas.yview_scroll(1, "units"))

        def _unbind_wheel(_e=None):
            detail_canvas.unbind_all("<MouseWheel>")
            detail_canvas.unbind_all("<Button-4>")
            detail_canvas.unbind_all("<Button-5>")

        detail_canvas.bind("<Enter>", _bind_wheel)
        detail_canvas.bind("<Leave>", _unbind_wheel)

        # Configure the initial category without loading its full catalogue
        # while the Docs page is still hidden at application startup.
        self._docs_defer_initial_render = True
        self.select_doc_category("pals")
        self._docs_defer_initial_render = False
        return frame

    def _set_placeholder(self, entry, text):
        entry.configure(fg=COLOR["text2"])
        entry.insert(0, text)

        def on_focus_in(_e):
            if entry.get() == text:
                entry.delete(0, "end")
                entry.configure(fg=COLOR["text0"])

        def on_focus_out(_e):
            if not entry.get():
                entry.insert(0, text)
                entry.configure(fg=COLOR["text2"])

        entry.bind("<FocusIn>", on_focus_in)
        entry.bind("<FocusOut>", on_focus_out)

    def select_doc_category(self, key):
        global docs_category, selected_wiki_item_slug
        if getattr(self, "_docs_rendered_category", None) == key:
            return
        # Stop progressive icon work belonging to the category being left.
        # Without this, a large catalogue can keep occupying the UI queue and
        # make the next category click appear to have been ignored.
        self._doc_catalog_icon_generation = (
            getattr(self, "_doc_catalog_icon_generation", 0) + 1)
        self._doc_catalog_icon_queue = []
        docs_category = key
        if key == "items" and selected_wiki_item_slug is None and wiki_items:
            selected_wiki_item_slug = wiki_items[0]["slug"]
        for k, btn in self.doc_cat_buttons.items():
            if k == key:
                btn.configure(bg=COLOR["bg2"], fg=COLOR["accent"], font=FONT_UI_BOLD)
            else:
                btn.configure(bg=COLOR["bg1"], fg=COLOR["text1"], font=FONT_UI)
        if key == "buildings":
            self._configure_doc_sort_buttons(("name", "rank", "hp"))
            if self.doc_sort_key not in ("name", "rank", "hp"):
                self.doc_sort_key = "name"
        elif key == "active_skills":
            self._configure_doc_sort_buttons(("name", "power", "cooldown"))
            if self.doc_sort_key not in ("name", "power", "cooldown"):
                self.doc_sort_key = "name"
        elif key == "passive_skills":
            self._configure_doc_sort_buttons(("name", "rank"))
            if self.doc_sort_key not in ("name", "rank"):
                self.doc_sort_key = "name"
        elif key == "technologies":
            self._configure_doc_sort_buttons(
                ("name", "tier", "level_cap", "cost"))
            if self.doc_sort_key not in (
                    "name", "tier", "level_cap", "cost"):
                self.doc_sort_key = "name"
        elif key == "elements":
            self._configure_doc_sort_buttons(("name",))
            self.doc_sort_key = "name"
        elif key == "work_suitability":
            self._configure_doc_sort_buttons(("name",))
            self.doc_sort_key = "name"
        else:
            self._configure_doc_sort_buttons(("name", "num"))
            if self.doc_sort_key not in ("name", "num"):
                self.doc_sort_key = "num"
        self._refresh_sort_buttons()
        if getattr(self, "_docs_defer_initial_render", False):
            return
        self._docs_category_generation = (
            getattr(self, "_docs_category_generation", 0) + 1)
        generation = self._docs_category_generation
        self._docs_detail_generation = (
            getattr(self, "_docs_detail_generation", 0) + 1)
        detail_generation = self._docs_detail_generation

        def render_selected_category():
            if (generation != getattr(self, "_docs_category_generation", None)
                    or docs_category != key
                    or getattr(self, "_current_view_key", None) != "docs"):
                return
            if key == "buildings":
                self._load_docs_buildings()
            elif key == "active_skills":
                self._load_docs_active_skills()
            elif key == "passive_skills":
                self._load_docs_passive_skills()
            elif key == "technologies":
                self._load_docs_technologies()
            elif key == "elements":
                self._load_docs_elements()
            elif key == "work_suitability":
                self._load_docs_work_suitability()
            elif key == "pals":
                self._load_docs_pal_source_data()
            self.render_docs_list()
            self._docs_rendered_category = key
            self._view_render_revision["docs"] = self._data_revision

            def render_selected_detail():
                if (generation != getattr(
                        self, "_docs_category_generation", None)
                        or detail_generation != getattr(
                            self, "_docs_detail_generation", None)
                        or docs_category != key
                        or getattr(self, "_current_view_key", None) != "docs"):
                    return
                self.render_docs_detail()

            # Give Tk a paint cycle after the catalogue is visible. Heavy
            # element/work-suitability detail grids no longer delay the tab
            # highlight and list from appearing.
            self.after_idle(render_selected_detail)

        # Let the category highlight appear before loading its catalogue.
        self.after_idle(render_selected_category)

    def _configure_doc_sort_buttons(self, visible_keys):
        for button in self.doc_sort_buttons.values():
            button.pack_forget()
        for key in visible_keys:
            self.doc_sort_buttons[key].pack(side="left", padx=(0, 6))

    def set_doc_sort(self, key):
        if self.doc_sort_key == key:
            self.doc_sort_reverse = not self.doc_sort_reverse
        else:
            self.doc_sort_key = key
            self.doc_sort_reverse = False
        self._refresh_sort_buttons()
        self.render_docs_list()

    def _refresh_sort_buttons(self):
        arrow = "\u25BC" if self.doc_sort_reverse else "\u25B2"
        for key, btn in self.doc_sort_buttons.items():
            base = self.doc_sort_labels.get(key, key.title())
            if key == self.doc_sort_key:
                btn.configure(text=f"{base}{arrow}", bg=COLOR["accent_dim"], fg=COLOR["accent"])
            else:
                btn.configure(text=base, bg=COLOR["bg1"], fg=COLOR["text2"])

    @staticmethod
    def _num_sort_key(num_str):
        i = 0
        while i < len(num_str) and num_str[i].isdigit():
            i += 1
        # Unnumbered internal records sort after the official Paldeck instead
        # of appearing before Pal #1.
        number = int(num_str[:i]) if i else 10 ** 9
        suffix = num_str[i:]
        return (number, suffix)

    def _load_source_game_json(self, filename):
        cache = getattr(self, "_source_game_json_cache", None)
        if cache is None:
            cache = {}
            self._source_game_json_cache = cache
        cached = cache.get(filename)
        if cached is not None:
            return cached
        self._locate_technology_icon_source()
        try:
            root = getattr(self, "_technology_icon_root", None)
            archive = getattr(self, "_technology_icon_zip", None)
            if root and (root / filename).is_file():
                with open(root / filename, "r", encoding="utf-8") as handle:
                    data = json.load(handle)
                    cache[filename] = data
                    return data
            if archive:
                suffix = f"/resources/game_data/{filename}".casefold()
                member = next(
                    name for name in archive.namelist()
                    if name.replace("\\", "/").casefold().endswith(suffix))
                data = json.loads(archive.read(member).decode("utf-8"))
                cache[filename] = data
                return data
        except (OSError, KeyError, StopIteration, UnicodeError, ValueError):
            pass
        return {}

    @staticmethod
    def _clean_docs_pal_description(value):
        text = str(value or "").replace("\r\n", " ").replace("\n", " ")
        text = re.sub(r"\[ICON:[^\]]+\]", "", text)
        text = re.sub(r"\[(?:ELEM|EFFECT):([^\]]+)\]", r"\1", text)
        text = re.sub(r"\{[^}]+\}", "", text)
        return re.sub(r"\s+", " ", text).strip()

    def _load_docs_pal_source_data(self):
        """Merge the full supplied game-data record into every Docs Pal."""
        if getattr(self, "_docs_pal_source_loaded", False):
            return
        self._docs_pal_source_loaded = True
        characters = self._load_source_game_json("characters.json")
        learnsets = self._load_source_game_json("pals_learnset.json")
        skills_data = self._load_source_game_json("skills.json")
        source_pals = [
            row for row in characters.get("pals", [])
            if isinstance(row, dict) and row.get("asset")
        ]
        if not source_pals:
            self._docs_pal_source_loaded = False
            return

        by_asset = {
            str(row.get("asset")).casefold(): row for row in source_pals}
        by_name = {}
        for row in source_pals:
            key = str(row.get("name") or "").casefold()
            if not key:
                continue
            current = by_name.get(key)
            asset = str(row.get("asset") or "")
            is_variant = asset.upper().startswith(
                ("BOSS_", "PREDATOR_", "GYM_", "RAID_", "SUMMON_"))
            if current is None or (
                    str(current.get("asset") or "").upper().startswith(
                        ("BOSS_", "PREDATOR_", "GYM_", "RAID_", "SUMMON_"))
                    and not is_variant):
                by_name[key] = row

        skill_names = {
            str(row.get("asset") or "").casefold():
            str(row.get("name") or row.get("asset") or "")
            for row in skills_data.get("skills", [])
            if isinstance(row, dict) and row.get("asset")
        }
        learnset = learnsets.get("learnset", {})
        learnset_ci = {
            str(key).casefold(): value for key, value in learnset.items()}
        work_names = {
            "EmitFlame": "Kindling",
            "Watering": "Watering",
            "Seeding": "Planting",
            "GenerateElectricity": "Generating Electricity",
            "Handcraft": "Handiwork",
            "Collection": "Gathering",
            "Deforest": "Lumbering",
            "Mining": "Mining",
            "OilExtraction": "Oil Extraction",
            "ProductMedicine": "Medicine Production",
            "Cool": "Cooling",
            "Transport": "Transporting",
            "MonsterFarm": "Farming",
        }
        self._source_pal_icon_files = {}
        matched_assets = set()

        for pal in wiki_pals:
            spawn_id = str(pal.get("spawn_id") or "")
            source = by_asset.get(spawn_id.casefold())
            name_source = by_name.get(
                str(pal.get("name") or "").casefold())
            # Some legacy catalogue rows point at a valid but completely
            # different Pal asset (for example Aegidron -> GrassDragon).
            # A mismatched source name is evidence that the old asset is wrong,
            # so prefer the verified name mapping from characters.json.
            if (name_source is not None and (
                    source is None
                    or str(source.get("name") or "").casefold()
                    != str(pal.get("name") or "").casefold())):
                source = name_source
            if source is None:
                continue
            asset = str(source.get("asset") or spawn_id)
            matched_assets.add(asset.casefold())
            stats = source.get("stats") or {}
            pal["spawn_id"] = asset
            pal["subtitle"] = asset
            pal["stats"] = [
                ("HP", stats.get("hp", "—")),
                ("Melee Attack", stats.get("melee_attack", "—")),
                ("Shot Atk", stats.get("shot_attack", "—")),
                ("Defense", stats.get("defense", "—")),
            ]
            size = str(stats.get("size") or "—").split("::")[-1]
            pal["extra"] = [
                ("Rarity", stats.get("rarity", "—")),
                ("Work Speed", stats.get("craft_speed", "—")),
                ("Size", size),
                ("Food", stats.get("food_amount", "—")),
                ("Run Speed", stats.get("run_speed", "—")),
                ("Ride Sprint", stats.get("ride_sprint_speed", "—")),
                ("Support", stats.get("support", "—")),
            ]
            pal["work"] = [
                (work_names.get(key, key), int(value))
                for key, value in (source.get("work_suitabilities") or {}).items()
                if isinstance(value, (int, float)) and value > 0
            ]
            pal["passive_name"] = (
                str(source.get("partner_skill") or "No partner skill listed"))
            pal["passive_desc"] = self._clean_docs_pal_description(
                source.get("description"))
            moves = learnset.get(asset)
            if moves is None:
                moves = learnset_ci.get(asset.casefold(), [])
            pal["skills"] = [
                (skill_names.get(
                    str(move.get("WazaID") or "")
                    .replace("EPalWazaID::", "").casefold(),
                    str(move.get("WazaID") or "")
                    .replace("EPalWazaID::", "")),
                 move.get("level", "—"))
                for move in moves
                if isinstance(move, dict) and move.get("WazaID")
            ]
            icon_path = source.get("icon")
            if icon_path:
                self._source_pal_icon_files[asset.casefold()] = str(icon_path)

        positive_index_by_asset = {
            str(row.get("asset") or "").casefold():
                int((row.get("stats") or {}).get("zukan_index"))
            for row in source_pals
            if isinstance((row.get("stats") or {}).get("zukan_index"), int)
            and (row.get("stats") or {}).get("zukan_index") >= 0
        }
        existing_num_by_name = {
            re.sub(r"\s*\([^)]*\)\s*$", "", str(pal.get("name") or ""))
                .strip().casefold(): str(pal.get("num"))
            for pal in wiki_pals if pal.get("name") and pal.get("num")
        }
        used_nums = {str(pal.get("num")) for pal in wiki_pals}
        self._source_doc_pal_ids = {}

        def variant_suffix(source):
            asset_upper = str(source.get("asset") or "").upper()
            for prefix, label in (
                    ("BOSS_", "BOSS"), ("RAID_", "RAID"),
                    ("PREDATOR_", "PRED"), ("GYM_", "GYM"),
                    ("SUMMON_", "SUMMON")):
                if asset_upper.startswith(prefix):
                    return label
            match = re.search(
                r"\((Boss|Raid|Predator|Gym|Summon)\)",
                str(source.get("name") or ""), re.IGNORECASE)
            return match.group(1).upper() if match else ""

        def catalogue_num(source, internal_index):
            stats = source.get("stats") or {}
            raw_index = stats.get("zukan_index")
            if isinstance(raw_index, int) and raw_index >= 0:
                base = str(raw_index)
            else:
                asset = str(source.get("asset") or "")
                stripped = re.sub(
                    r"^(?:BOSS_|RAID_|PREDATOR_|GYM_|SUMMON_)+",
                    "", asset, flags=re.IGNORECASE)
                base_index = positive_index_by_asset.get(stripped.casefold())
                if base_index is not None:
                    base = str(base_index)
                else:
                    plain_name = re.sub(
                        r"\s*\([^)]*\)\s*$", "",
                        str(source.get("name") or "")).strip().casefold()
                    base = existing_num_by_name.get(plain_name, "")
            suffix = variant_suffix(source)
            candidate = f"{base}-{suffix}" if base and suffix else base
            if not candidate or candidate in used_nums:
                asset_token = re.sub(
                    r"[^A-Za-z0-9]+", "", str(source.get("asset") or ""))
                candidate = f"INT-{asset_token or internal_index + 1}"
            used_nums.add(candidate)
            return candidate

        def source_to_doc_pal(source, num):
            asset = str(source.get("asset") or "")
            stats = source.get("stats") or {}
            size = str(stats.get("size") or "—").split("::")[-1]
            moves = learnset.get(asset)
            if moves is None:
                moves = learnset_ci.get(asset.casefold(), [])
            return {
                "num": num,
                "name": str(source.get("name") or asset or "Unknown Pal"),
                "subtitle": asset,
                "spawn_id": asset,
                "icon": "?",
                "stats": [
                    ("HP", stats.get("hp", "—")),
                    ("Melee Attack", stats.get("melee_attack", "—")),
                    ("Shot Atk", stats.get("shot_attack", "—")),
                    ("Defense", stats.get("defense", "—")),
                ],
                "extra": [
                    ("Rarity", stats.get("rarity", "—")),
                    ("Work Speed", stats.get("craft_speed", "—")),
                    ("Size", size),
                    ("Food", stats.get("food_amount", "—")),
                    ("Run Speed", stats.get("run_speed", "—")),
                    ("Ride Sprint", stats.get("ride_sprint_speed", "—")),
                    ("Support", stats.get("support", "—")),
                ],
                "work": [
                    (work_names.get(key, key), int(value))
                    for key, value in (
                        source.get("work_suitabilities") or {}).items()
                    if isinstance(value, (int, float)) and value > 0
                ],
                "passive_name": str(
                    source.get("partner_skill")
                    or "No partner skill listed"),
                "passive_desc": self._clean_docs_pal_description(
                    source.get("description")),
                "skills": [
                    (skill_names.get(
                        str(move.get("WazaID") or "")
                        .replace("EPalWazaID::", "").casefold(),
                        str(move.get("WazaID") or "")
                        .replace("EPalWazaID::", "")),
                     move.get("level", "—"))
                    for move in moves
                    if isinstance(move, dict) and move.get("WazaID")
                ],
            }

        for index, source in enumerate(source_pals):
            asset = str(source.get("asset") or "")
            if asset.casefold() in matched_assets:
                matched = next(
                    (pal for pal in wiki_pals
                     if str(pal.get("spawn_id") or "").casefold()
                     == asset.casefold()), None)
                if matched:
                    self._source_doc_pal_ids[asset.casefold()] = matched["num"]
                continue
            num = catalogue_num(source, index)
            pal = source_to_doc_pal(source, num)
            wiki_pals.append(pal)
            self._source_doc_pal_ids[asset.casefold()] = num
            icon_path = source.get("icon")
            if icon_path:
                self._source_pal_icon_files[asset.casefold()] = str(icon_path)

    def _load_docs_buildings(self):
        if hasattr(self, "docs_buildings"):
            return self.docs_buildings
        data = self._load_source_game_json("world.json")
        self.docs_buildings = [
            building for building in data.get("structures", [])
            if isinstance(building, dict)
        ]
        self.doc_building_filter = None
        self.selected_doc_building_asset = (
            self.docs_buildings[0].get("asset")
            if self.docs_buildings else None)
        self._doc_building_rows = {}
        self._doc_building_photos = {}
        return self.docs_buildings

    def _load_docs_active_skills(self):
        if hasattr(self, "docs_active_skills"):
            return self.docs_active_skills
        data = self._load_source_game_json("skills.json")
        elements = {
            str(row.get("name") or "").casefold(): row
            for row in data.get("elements", [])
            if isinstance(row, dict) and row.get("name")
        }
        self.docs_active_skill_elements = elements
        self.docs_active_skills = []
        for source in data.get("skills", []):
            if not isinstance(source, dict) or not source.get("asset"):
                continue
            skill = dict(source)
            element = elements.get(str(skill.get("element") or "").casefold(), {})
            skill["element_display"] = (
                element.get("display") or skill.get("element") or "Unknown")
            skill["element_color"] = element.get("color") or COLOR["text2"]
            skill["icon"] = (element.get("icons") or {}).get("small")
            skill["description"] = self._clean_docs_pal_description(
                skill.get("description"))
            self.docs_active_skills.append(skill)
        self.docs_active_skills.sort(
            key=lambda row: str(row.get("name") or "").casefold())
        self.selected_doc_active_skill_asset = (
            self.docs_active_skills[0].get("asset")
            if self.docs_active_skills else None)
        self.doc_active_skill_element_filter = None
        return self.docs_active_skills

    def _docs_active_skill_photo(self, skill, size):
        if not PIL_AVAILABLE:
            return None
        if not hasattr(self, "_docs_active_skill_photo_cache"):
            self._docs_active_skill_photo_cache = {}
        key = (
            str(skill.get("asset") or skill.get("id") or skill.get("name")
                or skill.get("icon") or ""),
            int(size))
        if key in self._docs_active_skill_photo_cache:
            return self._docs_active_skill_photo_cache[key]
        self._locate_technology_icon_source()
        relative = str(skill.get("icon") or "").lstrip("/").replace("\\", "/")
        image = None
        try:
            root = getattr(self, "_technology_icon_root", None)
            archive = getattr(self, "_technology_icon_zip", None)
            if root and (root / Path(relative)).is_file():
                with Image.open(root / Path(relative)) as source:
                    image = source.convert("RGBA")
            if image is None and archive and relative:
                suffix = "/resources/game_data/" + relative
                member = next(
                    (actual for normalized, actual
                     in self._technology_icon_zip_names.items()
                     if normalized.casefold().endswith(suffix.casefold())),
                    None)
                if member:
                    with archive.open(member) as handle:
                        with Image.open(io.BytesIO(handle.read())) as source:
                            image = source.convert("RGBA")
            if image is not None:
                image.thumbnail((size, size), Image.Resampling.LANCZOS)
                photo = ImageTk.PhotoImage(image)
                self._docs_active_skill_photo_cache[key] = photo
                return photo
        except (OSError, KeyError, ValueError):
            pass
        self._docs_active_skill_photo_cache[key] = None
        return None

    def _load_docs_passive_skills(self):
        if hasattr(self, "docs_passive_skills"):
            return self.docs_passive_skills
        data = self._load_source_game_json("skills.json")
        self.docs_passive_skills = []
        for source in data.get("passives", []):
            if not isinstance(source, dict) or not source.get("asset"):
                continue
            passive = dict(source)
            passive["description"] = self._clean_docs_pal_description(
                passive.get("description"))
            raw_category = str(passive.get("category") or "")
            passive["category_display"] = (
                "Shown in game"
                if raw_category.endswith("SortDisplayable")
                else "Hidden / internal")
            self.docs_passive_skills.append(passive)
        self.docs_passive_skills.sort(
            key=lambda row: str(row.get("name") or "").casefold())
        self.selected_doc_passive_skill_asset = (
            self.docs_passive_skills[0].get("asset")
            if self.docs_passive_skills else None)
        # Start with actual player-facing passives. The full internal catalogue
        # remains available through the "All" visibility filter.
        self.doc_passive_category_filter = "Shown in game"
        self.doc_passive_rank_filter = None
        return self.docs_passive_skills

    def _load_docs_technologies(self):
        if hasattr(self, "docs_technologies"):
            return self.docs_technologies
        data = self._load_source_game_json("world.json")
        rows = data.get("technology", [])
        if not rows:
            try:
                rows = get_embedded_technology_data()
            except (ValueError, TypeError, json.JSONDecodeError):
                rows = []
        self.docs_technologies = []
        for source in rows:
            if not isinstance(source, dict) or not source.get("asset"):
                continue
            technology = dict(source)
            technology["description"] = self._clean_docs_pal_description(
                technology.get("description"))
            raw_type = str(technology.get("type") or "").casefold()
            technology["type_display"] = (
                "Ancient" if technology.get("is_boss_tech")
                or raw_type in ("boss", "ancient") else "Standard")
            self.docs_technologies.append(technology)
        self.docs_technologies.sort(
            key=lambda row: str(row.get("name") or "").casefold())
        self.selected_doc_technology_asset = (
            self.docs_technologies[0].get("asset")
            if self.docs_technologies else None)
        self.doc_technology_type_filter = None
        return self.docs_technologies

    def _render_technology_filter_chips(self):
        for widget in self.doc_item_cat_frame.winfo_children():
            widget.destroy()
        if not self.doc_item_cat_frame.winfo_ismapped():
            self.doc_item_cat_frame.pack(
                fill="x", padx=10, pady=(0, 8),
                before=self.doc_building_tree)
        tk.Label(
            self.doc_item_cat_frame, text="Type:", bg=COLOR["bg1"],
            fg=COLOR["text2"], font=("Segoe UI", 8),
        ).pack(side="left", padx=(0, 5))
        for label, value in (
                ("All", None), ("Ancient", "Ancient"),
                ("Standard", "Standard")):
            active = self.doc_technology_type_filter == value
            chip = tk.Label(
                self.doc_item_cat_frame, text=label,
                bg=COLOR["accent_dim"] if active else COLOR["bg2"],
                fg=COLOR["accent"] if active else COLOR["text1"],
                font=("Segoe UI", 8, "bold") if active else ("Segoe UI", 8),
                padx=7, pady=3, cursor="hand2",
                highlightthickness=1, highlightbackground=COLOR["line"])
            chip.pack(side="left", padx=(0, 4))
            chip.bind(
                "<Button-1>",
                lambda _event, selected=value:
                    self._select_doc_technology_filter(selected))

    def _select_doc_technology_filter(self, value):
        self.doc_technology_type_filter = value
        self.render_docs_list()

    def _render_technologies_list(self):
        self._show_building_list_widgets(True)
        self._render_technology_filter_chips()
        query = self.doc_search_var.get().strip().casefold()
        if query == "search...":
            query = ""
        technologies = [
            row for row in self._load_docs_technologies()
            if (not query
                or query in str(row.get("name") or "").casefold()
                or query in str(row.get("asset") or "").casefold()
                or query in str(row.get("description") or "").casefold()
                or any(
                    query in str(value).casefold()
                    for value in (
                        row.get("unlock_item_recipes") or [])
                    + (row.get("unlock_build_objects") or [])))
            and (not self.doc_technology_type_filter
                 or row.get("type_display")
                 == self.doc_technology_type_filter)
        ]
        sort_key = {
            "tier": lambda row: row.get("tier") or 0,
            "level_cap": lambda row: row.get("level_cap") or 0,
            "cost": lambda row: row.get("cost") or 0,
        }.get(
            self.doc_sort_key,
            lambda row: str(row.get("name") or "").casefold())
        technologies.sort(key=sort_key, reverse=self.doc_sort_reverse)

        tree = self.doc_building_tree
        tree.delete(*tree.get_children(""))
        self._doc_catalog_rows = {}
        self._doc_building_photos = {}
        selected_iid = None
        icon_rows = []
        for index, technology in enumerate(technologies):
            iid = f"technology_{index}"
            tree.insert(
                "", "end", iid=iid,
                text=f"  {technology.get('name') or technology.get('asset')}")
            self._doc_catalog_rows[iid] = ("technology", technology)
            icon_rows.append((iid, "technology", technology))
            if (technology.get("asset")
                    == self.selected_doc_technology_asset):
                selected_iid = iid
        if selected_iid:
            tree.selection_set(selected_iid)
            tree.see(selected_iid)
        elif technologies:
            self.selected_doc_technology_asset = technologies[0].get("asset")
            tree.selection_set("technology_0")
        tree.yview_moveto(0.0)
        self._queue_doc_catalog_icons(icon_rows)

    def _prepare_docs_reference_pal(self, source):
        """Give source-only Pal variants a clean Paldeck number and icon."""
        pal = dict(source)
        asset = str(pal.get("asset") or "")
        asset_key = asset.casefold()
        doc_ids = getattr(self, "_source_doc_pal_ids", {})
        mapped = str(doc_ids.get(asset_key) or "")

        # Internal catalogue keys are useful for uniqueness in the main Docs
        # catalogue, but they are not Paldeck numbers and should never be
        # presented to the user as "#INT-...".
        number_match = re.match(r"^(\d+[A-Za-z]?)", mapped)
        display_number = number_match.group(1) if number_match else ""
        stats_index = (pal.get("stats") or {}).get("zukan_index")
        if not display_number and isinstance(stats_index, int) and stats_index >= 0:
            display_number = str(stats_index)

        # Boss, raid, predator, gym and summon records often omit their own
        # Paldeck number/icon. Inherit those presentation fields from the base
        # asset while keeping the variant's actual data and display name.
        base_asset = re.sub(
            r"^(?:(?:BOSS|RAID|PREDATOR|GYM|SUMMON)_)+",
            "", asset, flags=re.IGNORECASE)
        if base_asset.casefold() != asset_key:
            base_mapped = str(doc_ids.get(base_asset.casefold()) or "")
            base_match = re.match(r"^(\d+[A-Za-z]?)", base_mapped)
            if base_match:
                display_number = base_match.group(1)
            if not pal.get("icon"):
                base_icon = getattr(
                    self, "_source_pal_icon_files", {}).get(
                        base_asset.casefold())
                if base_icon:
                    pal["icon"] = base_icon

        # Some internal variant asset names do not use a standard prefix. Use
        # the visible base name as a final, conservative lookup.
        if not display_number:
            base_name = re.sub(
                r"\s*\((?:Boss|Raid|Predator|Gym|Summon)\)\s*$", "",
                str(pal.get("name") or ""), flags=re.IGNORECASE).strip()
            for known in wiki_pals:
                known_name = re.sub(
                    r"\s*\([^)]*\)\s*$", "",
                    str(known.get("name") or "")).strip()
                if known_name.casefold() != base_name.casefold():
                    continue
                known_match = re.match(
                    r"^(\d+[A-Za-z]?)", str(known.get("num") or ""))
                if known_match:
                    display_number = known_match.group(1)
                    if not pal.get("icon"):
                        known_asset = str(known.get("spawn_id") or "")
                        known_icon = getattr(
                            self, "_source_pal_icon_files", {}).get(
                                known_asset.casefold())
                        if known_icon:
                            pal["icon"] = known_icon
                    break

        pal["doc_num"] = display_number
        return pal

    def _load_docs_elements(self):
        if hasattr(self, "docs_elements"):
            return self.docs_elements
        self._load_docs_pal_source_data()
        skills = self._load_source_game_json("skills.json")
        characters = self._load_source_game_json("characters.json")
        self.docs_elements = []
        for source in skills.get("elements", []):
            if not isinstance(source, dict) or not source.get("name"):
                continue
            element = dict(source)
            icons = element.get("icons") or {}
            element["icon"] = icons.get("small") or icons.get("large")
            element["pals"] = []
            self.docs_elements.append(element)
        by_name = {
            str(element.get("name")).casefold(): element
            for element in self.docs_elements}
        for source in characters.get("pals", []):
            if not isinstance(source, dict) or not source.get("asset"):
                continue
            pal = self._prepare_docs_reference_pal(source)
            for element_name in (pal.get("elements") or {}):
                element = by_name.get(str(element_name).casefold())
                if element is not None:
                    element["pals"].append(pal)
        for element in self.docs_elements:
            element["pals"].sort(
                key=lambda pal: str(pal.get("name") or "").casefold())
        self.docs_elements.sort(key=lambda row: row.get("index", 999))
        self.selected_doc_element_name = (
            self.docs_elements[0].get("name")
            if self.docs_elements else None)
        self.doc_element_pal_sort = "name"
        self.doc_element_pal_sort_reverse = False
        return self.docs_elements

    def _render_elements_list(self):
        self._show_building_list_widgets(True)
        self.doc_item_cat_frame.pack_forget()
        query = self.doc_search_var.get().strip().casefold()
        if query == "search...":
            query = ""
        elements = [
            row for row in self._load_docs_elements()
            if not query
            or query in str(row.get("name") or "").casefold()
            or query in str(row.get("display") or "").casefold()]
        elements.sort(
            key=lambda row: str(
                row.get("display") or row.get("name") or "").casefold(),
            reverse=self.doc_sort_reverse)
        tree = self.doc_building_tree
        tree.delete(*tree.get_children(""))
        self._doc_catalog_rows = {}
