    def _load_docs_work_suitability(self):
        if hasattr(self, "docs_work_suitability"):
            return self.docs_work_suitability
        self._load_docs_pal_source_data()
        work_data = self._load_source_game_json("work_suitability.json")
        characters = self._load_source_game_json("characters.json")
        self.docs_work_suitability = []
        source_by_id = {
            str(row.get("id") or "").casefold(): row
            for row in work_data.get("work_types", [])
            if isinstance(row, dict) and row.get("id")}
        # These icon indices intentionally follow the reference editor's
        # _WORK_ICON_REMAP. The final five UI assets are not ordered the same
        # way as work_suitability.json.
        canonical_work_types = (
            ("EmitFlame", "Kindling", 0),
            ("Watering", "Watering", 1),
            ("Seeding", "Planting", 2),
            ("GenerateElectricity", "Generating Electricity", 3),
            ("Handcraft", "Handiwork", 4),
            ("Collection", "Gathering", 5),
            ("Deforest", "Lumbering", 6),
            ("Mining", "Mining", 7),
            ("Transport", "Transporting", 11),
            ("MonsterFarm", "Ranching", 12),
            ("ProductMedicine", "Medicine Production", 8),
            ("OilExtraction", "Oil Extraction", 9),
            ("Cool", "Cooling", 10),
        )
        for index, (work_id, display_name, icon_index) in enumerate(
                canonical_work_types):
            work_type = dict(source_by_id.get(work_id.casefold(), {}))
            work_type.update({
                "id": work_id,
                "display_name": display_name,
                "index": index,
                "icon": f"/icons/ui/T_icon_palwork_{icon_index:02d}.webp",
            })
            work_type["pals"] = []
            self.docs_work_suitability.append(work_type)
        by_id = {
            str(row.get("id")).casefold(): row
            for row in self.docs_work_suitability}
        for source in characters.get("pals", []):
            if not isinstance(source, dict) or not source.get("asset"):
                continue
            for work_id, level in (
                    source.get("work_suitabilities") or {}).items():
                work_type = by_id.get(str(work_id).casefold())
                if (work_type is None
                        or not isinstance(level, (int, float))
                        or level <= 0):
                    continue
                pal = self._prepare_docs_reference_pal(source)
                pal["work_level"] = int(level)
                work_type["pals"].append(pal)
        for work_type in self.docs_work_suitability:
            work_type["pals"].sort(
                key=lambda pal: str(pal.get("name") or "").casefold())
        self.docs_work_suitability.sort(
            key=lambda row: row.get("index", 999))
        self.selected_doc_work_id = (
            self.docs_work_suitability[0].get("id")
            if self.docs_work_suitability else None)
        self.doc_work_pal_sort = "name"
        self.doc_work_pal_sort_reverse = False
        return self.docs_work_suitability

