    def _queue_doc_catalog_icons(self, rows):
        self._doc_catalog_icon_generation = (
            getattr(self, "_doc_catalog_icon_generation", 0) + 1)
        generation = self._doc_catalog_icon_generation
        self._doc_catalog_icon_queue = list(rows)
        self.after_idle(
            lambda token=generation: self._load_doc_catalog_icon_batch(token))

    def _load_doc_catalog_icon_batch(self, generation):
        if generation != getattr(self, "_doc_catalog_icon_generation", None):
            return
        for _index in range(6):
            if not getattr(self, "_doc_catalog_icon_queue", None):
                return
            iid, kind, entry = self._doc_catalog_icon_queue.pop(0)
            if kind == "building":
                photo = self._docs_building_photo(entry, 24)
            elif kind == "active_skill":
                photo = self._docs_active_skill_photo(entry, 22)
            elif kind == "passive_skill":
                photo = self._docs_active_skill_photo(entry, 22)
            elif kind == "technology":
                photo = self._docs_active_skill_photo(entry, 24)
            elif kind == "element":
                photo = self._docs_active_skill_photo(entry, 24)
            elif kind == "work_suitability":
                photo = self._docs_active_skill_photo(entry, 24)
            elif kind == "pal":
                photo = self.get_pal_photo(entry.get("spawn_id"), 28)
                if photo is None:
                    source_icon = getattr(
                        self, "_source_pal_icon_files", {}).get(
                            str(entry.get("spawn_id") or "").casefold())
                    if source_icon:
                        photo = self._docs_active_skill_photo({
                            "asset": entry.get("spawn_id"),
                            "icon": source_icon,
                        }, 28)
            else:
                photo = self.get_item_photo(entry.get("game_id"), 28)
            if photo and self.doc_building_tree.exists(iid):
                self._doc_building_photos[iid] = photo
                self.doc_building_tree.item(iid, image=photo)
        self.after(
            8, lambda token=generation:
            self._load_doc_catalog_icon_batch(token))

    def _on_doc_catalog_tree_select(self, _event=None):
        selection = self.doc_building_tree.selection()
        if not selection:
            return
        row = getattr(self, "_doc_catalog_rows", {}).get(selection[0])
        if not row:
            return
        kind, entry = row
        expected_kind = {
            "buildings": "building",
            "pals": "pal",
            "items": "item",
            "active_skills": "active_skill",
            "passive_skills": "passive_skill",
            "technologies": "technology",
            "elements": "element",
            "work_suitability": "work_suitability",
        }.get(docs_category)
        if kind != expected_kind:
            return
        if kind == "building":
            self.selected_doc_building_asset = entry.get("asset")
        elif kind == "pal":
            global selected_wiki_num
            selected_wiki_num = entry["num"]
        elif kind == "item":
            global selected_wiki_item_slug
            selected_wiki_item_slug = entry["slug"]
        elif kind == "active_skill":
            self.selected_doc_active_skill_asset = entry.get("asset")
        elif kind == "passive_skill":
            self.selected_doc_passive_skill_asset = entry.get("asset")
        elif kind == "technology":
            self.selected_doc_technology_asset = entry.get("asset")
        elif kind == "element":
            self.selected_doc_element_name = entry.get("name")
        elif kind == "work_suitability":
            self.selected_doc_work_id = entry.get("id")
        self.render_docs_detail()

