    def _render_technology_detail(self):
        technologies = self._load_docs_technologies()
        technology = next(
            (row for row in technologies
             if row.get("asset") == self.selected_doc_technology_asset),
            technologies[0] if technologies else None)
        if not technology:
            tk.Label(
                self.doc_detail_inner,
                text="The technology database could not be loaded.",
                bg=COLOR["bg0"], fg=COLOR["text2"], font=FONT_UI,
            ).pack(anchor="w")
            return

        header = tk.Frame(self.doc_detail_inner, bg=COLOR["bg0"])
        header.pack(fill="x", anchor="w")
        photo = self._docs_active_skill_photo(technology, 58)
        if photo:
            icon = tk.Label(header, image=photo, bg=COLOR["bg0"])
            icon.image = photo
        else:
            icon = tk.Label(
                header, text="?", bg=COLOR["bg2"], fg=COLOR["accent"],
                font=("Segoe UI", 28, "bold"), width=3, height=2,
                highlightthickness=1, highlightbackground=COLOR["line"])
        icon.pack(side="left", padx=(0, 14))
        title = tk.Frame(header, bg=COLOR["bg0"])
        title.pack(side="left", fill="x", expand=True)
        tk.Label(
            title,
            text=technology.get("name") or technology.get("asset") or "---",
            bg=COLOR["bg0"], fg=COLOR["text0"],
            font=("Segoe UI", 19, "bold"),
        ).pack(anchor="w")
        tk.Label(
            title, text=technology.get("asset") or "---",
            bg=COLOR["bg0"], fg=COLOR["text2"], font=FONT_MONO,
        ).pack(anchor="w", pady=(3, 0))

        tk.Frame(
            self.doc_detail_inner, bg=COLOR["line"], height=1
        ).pack(fill="x", pady=13)
        tk.Label(
            self.doc_detail_inner,
            text=technology.get("description")
                 or "No description is available for this technology.",
            bg=COLOR["bg0"], fg=COLOR["text1"], font=("Segoe UI", 10),
            justify="left", wraplength=850,
        ).pack(fill="x", anchor="w", pady=(0, 16))

        def stat_card(parent, label, value, width=100):
            card = tk.Frame(
                parent, bg=COLOR["bg2"], width=width, height=92,
                highlightthickness=1, highlightbackground=COLOR["line"])
            card.pack_propagate(False)
            tk.Label(
                card, text=label, bg=COLOR["bg3"], fg=COLOR["text2"],
                font=("Segoe UI", 8), padx=9, pady=7,
            ).pack(fill="x", padx=8, pady=(9, 0))
            tk.Label(
                card, text=str(value), bg=COLOR["bg2"],
                fg=COLOR["text0"], font=("Segoe UI", 15, "bold"),
            ).pack(anchor="w", padx=15, pady=(8, 0))
            return card

        stats = tk.Frame(self.doc_detail_inner, bg=COLOR["bg0"])
        stats.pack(fill="x", anchor="w", pady=(0, 16))
        for label, value in (
                ("Cost", technology.get("cost", 0)),
                ("Level Cap", technology.get("level_cap", 0)),
                ("Tier", technology.get("tier", 0)),
                ("Type", technology.get("type_display", "Standard"))):
            stat_card(
                stats, label, value,
                112 if label in ("Level Cap", "Type") else 92
            ).pack(side="left", padx=(0, 8))

        unlock_items = list(technology.get("unlock_item_recipes") or [])
        unlock_buildings = list(technology.get("unlock_build_objects") or [])
        item_names = {
            str(item.get("game_id") or "").casefold():
                item.get("name") or item.get("game_id")
            for item in wiki_items if item.get("game_id")
        }
        buildings = self._load_docs_buildings()
        building_names = {
            str(row.get("asset") or "").casefold():
                row.get("name") or row.get("asset")
            for row in buildings if row.get("asset")
        }

        def unlock_section(title_text, identifiers, names):
            if not identifiers:
                return
            tk.Label(
                self.doc_detail_inner, text=title_text,
                bg=COLOR["bg0"], fg=COLOR["text1"], font=FONT_UI_BOLD,
            ).pack(fill="x", anchor="w", pady=(0, 7))
            box = tk.Frame(
                self.doc_detail_inner, bg=COLOR["bg2"],
                highlightthickness=1, highlightbackground=COLOR["line"])
            box.pack(fill="x", anchor="w", pady=(0, 14))
            for identifier in identifiers:
                name = names.get(str(identifier).casefold(), identifier)
                row = tk.Frame(box, bg=COLOR["bg2"])
                row.pack(fill="x", padx=10, pady=5)
                tk.Label(
                    row, text=str(name), bg=COLOR["bg2"],
                    fg=COLOR["accent"], font=("Segoe UI", 9),
                    anchor="w",
                ).pack(side="left")
                if str(name) != str(identifier):
                    tk.Label(
                        row, text=str(identifier), bg=COLOR["bg2"],
                        fg=COLOR["text2"], font=FONT_MONO,
                        anchor="e",
                    ).pack(side="right")

        unlock_section("Unlocks Items", unlock_items, item_names)
        unlock_section("Unlocks Buildings", unlock_buildings, building_names)

        requirements = []
        required_tech = str(
            technology.get("require_technology") or "").strip()
        required_boss = str(
            technology.get("require_tower_boss") or "").strip()
        if required_tech:
            requirements.append(("Required technology", required_tech))
        if required_boss and required_boss.casefold() != "none":
            requirements.append(("Required tower boss", required_boss))
        if requirements:
            tk.Label(
                self.doc_detail_inner, text="Requirements",
                bg=COLOR["bg0"], fg=COLOR["text1"], font=FONT_UI_BOLD,
            ).pack(fill="x", anchor="w", pady=(0, 7))
            box = tk.Frame(
                self.doc_detail_inner, bg=COLOR["bg2"],
                highlightthickness=1, highlightbackground=COLOR["line"])
            box.pack(fill="x", anchor="w")
            for label, value in requirements:
                row = tk.Frame(box, bg=COLOR["bg2"])
                row.pack(fill="x", padx=10, pady=5)
                tk.Label(
                    row, text=label, bg=COLOR["bg2"],
                    fg=COLOR["text2"], font=("Segoe UI", 9),
                ).pack(side="left")
                tk.Label(
                    row, text=value, bg=COLOR["bg2"],
                    fg=COLOR["text0"], font=FONT_MONO,
                ).pack(side="right")

    def render_docs_detail(self):
        self._docs_pal_grid_generation = (
            getattr(self, "_docs_pal_grid_generation", 0) + 1)
        for w in self.doc_detail_inner.winfo_children():
            w.destroy()

        if docs_category == "items":
            self._render_item_detail()
            return

        if docs_category == "buildings":
            self._render_building_detail()
            return

        if docs_category == "active_skills":
            self._render_active_skill_detail()
            return

        if docs_category == "passive_skills":
            self._render_passive_skill_detail()
            return

        if docs_category == "technologies":
            self._render_technology_detail()
            return

        if docs_category == "elements":
            self._render_element_detail()
            return

        if docs_category == "work_suitability":
            self._render_work_suitability_detail()
            return

        if docs_category != "pals":
            tk.Label(self.doc_detail_inner, text="Select a category with entries to see details here.",
                     bg=COLOR["bg0"], fg=COLOR["text2"], font=FONT_UI).pack(anchor="w")
            return

        pal = get_wiki_pal(selected_wiki_num)
        if not pal:
            tk.Label(self.doc_detail_inner, text="No pal selected.", bg=COLOR["bg0"],
                      fg=COLOR["text2"], font=FONT_UI).pack(anchor="w")
            return

        head = tk.Frame(self.doc_detail_inner, bg=COLOR["bg0"])
        head.pack(fill="x", anchor="w")
        title_row = tk.Frame(head, bg=COLOR["bg0"])
        title_row.pack(anchor="w")
        tk.Label(title_row, text=pal["name"], bg=COLOR["bg0"], fg=COLOR["text0"],
                 font=("Segoe UI", 18, "bold")).pack(side="left")
        number = str(pal.get("num") or "")
        if number and not number.upper().startswith("INT-"):
            tk.Label(
                title_row, text=f"  #{number}", bg=COLOR["bg0"],
                fg=COLOR["text2"], font=("Segoe UI", 11),
            ).pack(side="left")
        tk.Label(head, text=pal["subtitle"], bg=COLOR["bg0"], fg=COLOR["text1"],
                 font=("Segoe UI", 10)).pack(anchor="w")
        spawn_row = tk.Frame(head, bg=COLOR["bg0"])
        spawn_row.pack(anchor="w", pady=(2, 0))
        tk.Label(spawn_row, text="Spawn ID:", bg=COLOR["bg0"], fg=COLOR["text2"],
                 font=("Segoe UI", 9)).pack(side="left")
        tk.Label(spawn_row, text=pal.get("spawn_id", "\u2014"), bg=COLOR["bg2"], fg=COLOR["text0"],
                 font=FONT_MONO, padx=6).pack(side="left", padx=(6, 0))
        tk.Frame(self.doc_detail_inner, bg=COLOR["line"], height=1).pack(fill="x", pady=12)

        content = tk.Frame(self.doc_detail_inner, bg=COLOR["bg0"])
        content.pack(fill="both", expand=True, anchor="w")

        portrait_photo = self.get_pal_photo(pal.get("spawn_id"), 96)
        if portrait_photo:
            portrait = tk.Label(content, image=portrait_photo, bg=COLOR["bg2"],
                                 highlightthickness=1, highlightbackground=COLOR["line"])
            portrait.image = portrait_photo
        else:
            portrait = tk.Label(content, text=pal["icon"], bg=COLOR["bg2"], fg=COLOR["text0"],
                                 font=("Segoe UI", 46), width=4, height=2,
                                 highlightthickness=1, highlightbackground=COLOR["line"])
        portrait.pack(side="left", anchor="n", padx=(0, 24))

        stats_col = tk.Frame(content, bg=COLOR["bg0"])
        stats_col.pack(side="left", fill="both", expand=True, anchor="n")

        def stat_card(parent, label, value):
            card = tk.Frame(parent, bg=COLOR["bg2"], highlightthickness=1,
                             highlightbackground=COLOR["line"], width=90, height=64)
            card.pack_propagate(False)
            tk.Label(card, text=label, bg=COLOR["bg2"], fg=COLOR["text2"],
                     font=("Segoe UI", 8)).pack(anchor="w", padx=10, pady=(8, 0))
            tk.Label(card, text=str(value), bg=COLOR["bg2"], fg=COLOR["text0"],
                     font=("Segoe UI", 14, "bold")).pack(anchor="w", padx=10)
            return card

        row1 = tk.Frame(stats_col, bg=COLOR["bg0"])
        row1.pack(anchor="w", pady=(0, 8))
