    def _build_roster(self, parent):
        frame = tk.Frame(parent, bg=COLOR["bg1"], width=260,
                          highlightthickness=1, highlightbackground=COLOR["line"])
        frame.pack_propagate(False)

        head = tk.Frame(frame, bg=COLOR["bg1"])
        head.pack(fill="x")
        tk.Label(head, text="PARTY", bg=COLOR["bg1"], fg=COLOR["text2"],
                 font=("Segoe UI", 8, "bold"), padx=12, pady=8).pack(side="left")
        tk.Button(head, text="+", command=self.add_entry, bg=COLOR["bg1"],
                  fg=COLOR["text1"], relief="flat", bd=0, font=FONT_UI_BOLD).pack(side="right", padx=8)
        tk.Frame(frame, bg=COLOR["line"], height=1).pack(fill="x")

        canvas = tk.Canvas(frame, bg=COLOR["bg1"], highlightthickness=0)
        scrollbar = ttk.Scrollbar(frame, orient="vertical", command=canvas.yview)
        self.roster_list = tk.Frame(canvas, bg=COLOR["bg1"])
        self.roster_list.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.create_window((0, 0), window=self.roster_list, anchor="nw", width=242)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True, padx=(6, 0), pady=6)
        scrollbar.pack(side="right", fill="y")
        return frame

    def render_roster(self):
        for w in self.roster_list.winfo_children():
            w.destroy()
        party_ids = getattr(self, "_party_container_ids", None) or set()
        fallback_party_id = getattr(self, "player_container_ids", {}).get("OtomoCharacterContainerId")
        if fallback_party_id:
            party_ids = party_ids | {fallback_party_id}
        for e in entries:
            if e.get("is_real_pal") and party_ids and e.get("container_id") not in party_ids:
                continue
            selected = e["id"] == selected_id
            card = tk.Frame(self.roster_list,
                             bg=COLOR["accent_dim"] if selected else COLOR["bg2"],
                             highlightthickness=1,
                             highlightbackground=COLOR["accent"] if selected else COLOR["line"],
                             cursor="hand2")
            card.pack(fill="x", pady=3, padx=2)

            spawn_id = e.get("character_id")
            thumb_photo = self.get_pal_photo(spawn_id, 32) if spawn_id else None
            if thumb_photo:
                thumb = tk.Label(card, image=thumb_photo, bg=COLOR["bg3"])
                thumb.image = thumb_photo
            else:
                thumb = tk.Label(card, text=e["icon"], bg=COLOR["bg3"], fg=COLOR["text0"],
                                  font=("Segoe UI", 14), width=3, height=1)
            thumb.pack(side="left", padx=8, pady=8)

            info = tk.Frame(card, bg=card["bg"])
            info.pack(side="left", fill="x", expand=True, pady=8)
            name_txt = ("\u2605 " if e["starred"] else "") + e["name"]
            tk.Label(info, text=name_txt, bg=card["bg"], fg=COLOR["text0"],
                     font=FONT_UI_BOLD, anchor="w").pack(fill="x")
            sub = f"Lv. {e['level']} / {e['max_level']}" + ("  \U0001F512" if e["locked"] else "")
            tk.Label(info, text=sub, bg=card["bg"], fg=COLOR["text2"],
                     font=("Segoe UI", 8), anchor="w").pack(fill="x")

            bar_bg = tk.Frame(info, bg=COLOR["bg3"], height=4)
            bar_bg.pack(fill="x", pady=(4, 0))
            pct = max(0.02, e["level"] / e["max_level"])
            bar_fill = tk.Frame(bar_bg, bg=COLOR["good"], height=4)
            bar_fill.place(relx=0, rely=0, relwidth=pct, relheight=1)

            for widget in (card, thumb, info):
                widget.bind("<Button-1>", lambda ev, eid=e["id"]: self.select_entry(eid))
            for child in info.winfo_children():
                child.bind("<Button-1>", lambda ev, eid=e["id"]: self.select_entry(eid))

