        tag_btn("Max All", self.max_box, COLOR["accent"])
        tag_btn("Bulk Clone Pals", self.bulk_clone_box)
        tag_btn("Bulk Delete Pals", self.bulk_delete_box, COLOR["danger"])

        nav = tk.Frame(toolbar, bg=COLOR["bg1"])
        nav.pack(side="right", padx=6)
        prev_btn = tk.Label(nav, text="\u25c0", bg=COLOR["bg2"], fg=COLOR["text1"],
                             font=("Segoe UI", 9), padx=8, pady=4, cursor="hand2")
        prev_btn.pack(side="left", padx=2)
        prev_btn.bind("<Button-1>", lambda ev: self._shift_box(-1))
        next_btn = tk.Label(nav, text="\u25b6", bg=COLOR["bg2"], fg=COLOR["text1"],
                             font=("Segoe UI", 9), padx=8, pady=4, cursor="hand2")
