        next_btn.bind("<Button-1>", lambda ev: self._shift_box(1))

        export_btn = tk.Button(toolbar, text="\U0001F4E6  Export Save", command=self.export_save_from_editor,
                                bg=COLOR["accent"], fg="#ffffff", activebackground=COLOR["accent"],
                                relief="flat", bd=0, font=("Segoe UI", 9, "bold"), padx=12)
        export_btn.pack(side="right", padx=6, pady=6)

