    def _shift_box(self, delta):
        self.current_box = max(1, min(32, self.current_box + delta))
        self.render_box_grid()

    def _box_pal_entries(self):
        palbox_id = getattr(self, "_palbox_container_id", None)
        by_slot = {}
        for e in entries:
            if (e.get("is_real_pal") and palbox_id and e.get("container_id") == palbox_id
                    and e.get("slot_index") is not None):
                box_num = (e["slot_index"] // BOX_SLOTS) + 1
                if box_num == self.current_box:
                    by_slot[e["slot_index"] % BOX_SLOTS] = e
        return [by_slot.get(i) for i in range(BOX_SLOTS)]

    def restore_box(self):
        for e in self._box_pal_entries():
            if not e or e["locked"] or not e.get("is_real_pal"):
                continue
            fields = self.pal_field_refs.get(e["id"])
            if fields is None:
                continue
            cid = self._pal_field_value(fields, "CharacterID", "") or ""
            scaling_row = get_pal_scaling(cid)
            if not scaling_row:
                continue
            level = int(self._pal_field_value(fields, "Level", 1) or 1)
            talent_hp = int(self._pal_field_value(fields, "Talent_HP", 0) or 0)
            rank_hp = int(self._pal_field_value(fields, "Rank_HP", 0) or 0)
            friendship = int(self._pal_field_value(fields, "FriendshipPoint", 0) or 0)
            condenser = int(self._pal_field_value(fields, "Rank", 1) or 1)
            awake = bool(self._pal_field_value(fields, "bIsAwakening", False))
            max_hp = calculate_max_hp(scaling_row, level, talent_hp, rank_hp,
                                       friendship, condenser, awake) / 1000.0
            self._pal_set_hp(fields, max_hp)
            self._pal_set_field(fields, "FullStomach", "FloatProperty", float(scaling_row[7]))
        self.render_box_grid()
        self.render_detail()

    def max_box(self):
        for e in self._box_pal_entries():
            if e and not e["locked"]:
                self.select_entry(e["id"])
                self._maximize_current_pal()
        self.render_box_grid()

    def _maximize_current_pal(self):
        e = get_entry(selected_id)
        if not e or not e.get("is_real_pal"):
            return
        fields = self.pal_field_refs.get(e["id"])
        if fields is None:
            return
        cheat = getattr(self, "pal_cheat_mode", False)
        cap, soul_cap, lv_cap = (255, 255, 255) if cheat else (100, 20, 80)
        for name in ("Talent_HP", "Talent_Shot", "Talent_Defense"):
            self._pal_set_field(fields, name, "ByteProperty", cap)
        for name in ("Rank_HP", "Rank_Attack", "Rank_Defence", "Rank_CraftSpeed"):
            self._pal_set_field(fields, name, "ByteProperty", soul_cap)
        self._pal_set_field(fields, "Rank", "ByteProperty", 5)
        self._pal_set_field(fields, "FriendshipPoint", "IntProperty", 200000)
        self._pal_set_field(fields, "bIsAwakening", "BoolProperty", True)
        self._pal_set_field(fields, "Level", "ByteProperty", lv_cap)
        e["level"] = lv_cap
        e["max_level"] = max(e.get("max_level", 80), lv_cap)
        e["talent_hp"] = cap
        e["talent_shot"] = cap
        e["talent_defense"] = cap
        e["rank"] = 5
        cid = self._pal_field_value(fields, "CharacterID", "") or ""
        scaling_row = get_pal_scaling(cid)
        if scaling_row:
            max_hp = calculate_max_hp(scaling_row, lv_cap, cap, soul_cap, 200000, 5, True) / 1000.0
            self._pal_set_hp(fields, max_hp)
            self._pal_set_field(fields, "FullStomach", "FloatProperty", float(scaling_row[7]))

    def bulk_clone_box(self):
        box_entries = [e for e in self._box_pal_entries() if e]
        if not box_entries:
            messagebox.showinfo("Nothing to clone", "This box is empty.")
            return
        if not messagebox.askyesno("Bulk Clone Pals",
                                    f"Clone all {len(box_entries)} pal(s) in Box {self.current_box}? "
                                    f"Clones are added as new roster entries, not placed into a "
                                    f"specific box slot (this app doesn't create new box-container "
                                    f"link data, only edits pals that already have one)."):
            return
        for e in box_entries:
            self.clone_entry(e)
        self.render_box_grid()

    def bulk_delete_box(self):
        box_entries = [e for e in self._box_pal_entries() if e]
        if not box_entries:
            return
        if not messagebox.askyesno("Bulk Delete Pals",
                                    f"Delete all {len(box_entries)} pal(s) in Box {self.current_box}? "
                                    f"This can't be undone."):
            return
        for e in box_entries:
            self.delete_entry(e)
        self.render_box_grid()

    def render_box_grid(self):
        for w in self.box_grid_frame.winfo_children():
            w.destroy()
        box_entries = self._box_pal_entries()
        count = sum(1 for e in box_entries if e)
        self.box_title_label.configure(text=f"Box {self.current_box} ({count})")
        cols = 6
        for i in range(BOX_SLOTS):
            r, c = divmod(i, cols)
            e = box_entries[i]
            selected = e is not None and e["id"] == selected_id
            slot = tk.Frame(self.box_grid_frame,
                             bg=COLOR["bg2"] if e else COLOR["bg1"],
                             width=90, height=90,
                             highlightthickness=2 if selected else 1,
                             highlightbackground=COLOR["accent"] if selected else COLOR["line"],
                             cursor="hand2" if e else "arrow")
            slot.grid(row=r, column=c, padx=5, pady=5)
            slot.grid_propagate(False)
            if e:
                spawn_id = e.get("character_id")
                slot_photo = self.get_pal_photo(spawn_id, 44) if spawn_id else None
                if slot_photo:
                    lbl = tk.Label(slot, image=slot_photo, bg=slot["bg"])
                    lbl.image = slot_photo
                else:
                    lbl = tk.Label(slot, text=e["icon"], bg=slot["bg"], fg=COLOR["text0"], font=("Segoe UI", 22))
                lbl.place(relx=0.5, rely=0.42, anchor="center")
                lvl = tk.Label(slot, text=str(e["level"]), bg=COLOR["bg0"], fg=COLOR["text1"],
                               font=("Consolas", 8))
                lvl.place(relx=0.06, rely=0.88, anchor="w")
                if e["locked"]:
                    tk.Label(slot, text="\U0001F512", bg=slot["bg"], fg=COLOR["warn"],
                             font=("Segoe UI", 9)).place(relx=0.94, rely=0.1, anchor="ne")
                for w in (slot, lbl, lvl):
                    w.bind("<Button-1>", lambda ev, eid=e["id"]: self.select_entry(eid))
                    w.bind("<Button-3>", lambda ev, eid=e["id"], box_pos=i: self._show_pal_slot_context_menu(ev, eid, box_pos))
                    w.bind("<Button-2>", lambda ev, eid=e["id"], box_pos=i: self._show_pal_slot_context_menu(ev, eid, box_pos))
            else:
                slot.bind("<Button-3>", lambda ev, box_pos=i: self._show_box_slot_context_menu(ev, box_pos))
                slot.bind("<Button-2>", lambda ev, box_pos=i: self._show_box_slot_context_menu(ev, box_pos))

    def _show_box_slot_context_menu(self, event, box_pos):
        menu = tk.Menu(self, tearoff=0, bg=COLOR["bg2"], fg=COLOR["text0"],
                        activebackground=COLOR["accent_dim"])
        menu.add_command(label="Add Pal...",
                          command=lambda: self.after(50, lambda: self.open_pal_picker(box_pos)))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _show_pal_slot_context_menu(self, event, entry_id, box_pos):
        self.select_entry(entry_id)
        menu = tk.Menu(self, tearoff=0, bg=COLOR["bg2"], fg=COLOR["text0"],
                       activebackground=COLOR["accent_dim"])
        menu.add_command(label="Clone Pal", command=lambda: self.after(50, lambda: self._clone_real_pal_to_empty_slot(entry_id)))
        menu.add_separator()
        menu.add_command(label="Delete Pal", command=lambda: self.after(50, lambda: self._delete_real_pal_from_slot(entry_id)))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _character_map_and_pair_index(self, entry_id):
        fields = self.pal_field_refs.get(entry_id)
        if fields is None or not getattr(self, "loaded_sav_json", None):
            return None, None
        world = next((p for p in self.loaded_sav_json.get("properties", [])
                      if p.get("name") == "worldSaveData"), None)
        if not world or not isinstance(world.get("value"), dict):
            return None, None
        csm = _find_field(world["value"].get("_fields", []), "CharacterSaveParameterMap")
        pairs = csm.get("value", {}).get("_map", []) if csm else []
        for idx, pair in enumerate(pairs):
            if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                continue
            val = pair[1]
            val_fields = val.get("_map_struct_fields", []) if isinstance(val, dict) else []
            raw = _find_field(val_fields, "RawData")
            decoded = raw.get("value", {}).get("_rawdata_decoded", []) if raw else []
            sp = next((x for x in decoded if x.get("name") == "SaveParameter"), None)
            candidate = sp.get("value", {}).get("_fields") if sp else None
            if candidate is fields:
                return pairs, idx
        return None, None

    def _set_pal_slot_index(self, pal_fields, slot_index):
        slot_id = _find_field(pal_fields, "SlotId")
        if not slot_id or not isinstance(slot_id.get("value"), dict):
            return False
        slot_fields = slot_id["value"].get("_fields", [])
        slot_field = _find_field(slot_fields, "SlotIndex")
        if slot_field is None:
            slot_fields.append({"name": "SlotIndex", "type": "IntProperty", "extra": {}, "value": slot_index})
        else:
            slot_field["value"] = slot_index
        return True

    def _palbox_slot_items(self):
        """Return the serialized slot array for the currently loaded Palbox."""
        if not getattr(self, "loaded_sav_json", None) or not getattr(
                self, "_palbox_container_id", None):
            return None
        world = next((p for p in self.loaded_sav_json.get("properties", [])
                      if p.get("name") == "worldSaveData"), None)
        if not world or not isinstance(world.get("value"), dict):
            return None
        containers = _find_field(
            world["value"].get("_fields", []), "CharacterContainerSaveData")
        pairs = containers.get("value", {}).get("_map", []) if containers else []
        for key, value in pairs:
            key_fields = key.get("_map_struct_fields", []) if isinstance(key, dict) else []
            id_field = _find_field(key_fields, "ID")
            container_id = (
                id_field.get("value", {}).get("_raw_b64")
                if id_field and isinstance(id_field.get("value"), dict) else None
            )
            if container_id != self._palbox_container_id:
                continue
            value_fields = (
                value.get("_map_struct_fields", []) if isinstance(value, dict) else [])
            slots = _find_field(value_fields, "Slots")
            if slots and isinstance(slots.get("value"), dict):
                return slots["value"].get("_items")
        return None

    def _append_palbox_slot_reference(self, instance_id, slot_index):
        """Add the CharacterContainerSaveData link required by the game."""
        slot_items = self._palbox_slot_items()
        if slot_items is None:
            return False

        template = next((
            item for item in slot_items
            if isinstance(item, dict)
            and _find_field(item.get("_fields", []), "RawData")
        ), None)
        if template is None:
            return False

        new_slot = copy.deepcopy(template)
        fields = new_slot.get("_fields", [])
        index_field = _find_field(fields, "SlotIndex")
        raw_field = _find_field(fields, "RawData")
        raw_value = raw_field.get("value", {}) if raw_field else {}
        raw_bytes = bytearray(_item_slot_raw_bytes(raw_value) or b"")
        if index_field is None or len(raw_bytes) < 33:
            return False

        index_field["value"] = int(slot_index)
        # PalworldSaveTools creates Palbox slot links with a zero PlayerUId,
        # the new instance GUID and a zero permission byte.  Copying the
        # template slot's player bytes makes the in-memory editor look right,
        # but Palworld silently rejects that link while loading the save.
        raw_bytes = bytearray((b"\x00" * 16) + bytes(instance_id) + b"\x00")
        raw_value.clear()
        raw_value["_array"] = list(raw_bytes)
        slot_items.append(new_slot)
        return True

    def _remove_palbox_slot_reference(self, instance_id, slot_index):
        slot_items = self._palbox_slot_items()
        if slot_items is None:
            return False
        for index, item in enumerate(slot_items):
            fields = item.get("_fields", []) if isinstance(item, dict) else []
            slot_field = _find_field(fields, "SlotIndex")
            raw_field = _find_field(fields, "RawData")
            raw_bytes = (
                _item_slot_raw_bytes(raw_field.get("value", {}))
                if raw_field else None)
            instance_matches = (
                raw_bytes is not None and len(raw_bytes) >= 32
                and raw_bytes[16:32] == bytes(instance_id))
            slot_matches = (
                slot_field is not None
                and int(slot_field.get("value", -1)) == int(slot_index))
            if instance_matches or slot_matches:
                slot_items.pop(index)
                return True
        return False

    def _update_guild_pal_handle(self, instance_id, add=True,
                                 template_instance_id=None):
        """Register or unregister a Pal instance in its owning guild."""
        if not getattr(self, "loaded_sav_json", None):
            return False
        world = next((p for p in self.loaded_sav_json.get("properties", [])
                      if p.get("name") == "worldSaveData"), None)
        if not world or not isinstance(world.get("value"), dict):
            return False
        group_map = _find_field(
            world["value"].get("_fields", []), "GroupSaveDataMap")
        encoded = group_map.get("value", {}).get("_raw_b64") if group_map else None
        if not encoded:
            return False
        try:
            original = base64.b64decode(encoded)
            reader = io.BytesIO(original)
            map_flags = reader.read(4)
            pair_count = struct.unpack("<i", reader.read(4))[0]
            pairs = []
            target_index = None
            needle = bytes(template_instance_id or instance_id)
            for pair_index in range(pair_count):
                key_guid = reader.read(16)
                fields = read_property_list(reader)
                raw_field = _find_field(fields, "RawData")
                group_raw = _rawdata_bytes(fields) if raw_field else None
                group_type = _find_field(fields, "GroupType")
                if (target_index is None and group_raw
                        and group_type
                        and group_type.get("value") == "EPalGroupType::Guild"
                        and needle in group_raw):
                    target_index = pair_index
                pairs.append([key_guid, fields])
            if target_index is None:
                return False

            fields = pairs[target_index][1]
            raw_field = _find_field(fields, "RawData")
            group_raw = _rawdata_bytes(fields)
            raw_reader = io.BytesIO(group_raw)
            raw_reader.read(16)
            _read_fstring(raw_reader)
            count_offset = raw_reader.tell()
            handle_count = struct.unpack("<i", raw_reader.read(4))[0]
            handles_offset = raw_reader.tell()
            handles = [
                group_raw[handles_offset + i * 32:handles_offset + (i + 1) * 32]
                for i in range(handle_count)
            ]
            tail = group_raw[handles_offset + handle_count * 32:]
            instance_bytes = bytes(instance_id)
            if add:
                if not any(handle[16:32] == instance_bytes for handle in handles):
                    handles.append((b"\x00" * 16) + instance_bytes)
            else:
                handles = [
                    handle for handle in handles
                    if handle[16:32] != instance_bytes
                ]
            updated_group_raw = (
                group_raw[:count_offset]
                + struct.pack("<i", len(handles))
                + b"".join(handles)
                + tail
            )
            raw_field["value"] = {"_array": list(updated_group_raw)}

            rebuilt = io.BytesIO()
            rebuilt.write(map_flags)
            rebuilt.write(struct.pack("<i", len(pairs)))
            for key_guid, pair_fields in pairs:
                rebuilt.write(key_guid)
                write_property_list(rebuilt, pair_fields)
            group_map["value"]["_raw_b64"] = base64.b64encode(
                rebuilt.getvalue()).decode("ascii")
            return True
        except Exception:
            return False

    def _delete_real_pal_from_slot(self, entry_id):
        global selected_id
        e = get_entry(entry_id)
        if not e or not e.get("is_real_pal"):
            return
        if not messagebox.askyesno("Delete Pal", f"Delete {e.get('name', 'this pal')} from this slot completely?\n\nThis change is permanent once the save is exported."):
            return
        pairs, idx = self._character_map_and_pair_index(entry_id)
        if pairs is None:
            messagebox.showerror("Delete failed", "The pal's save record could not be located.")
            return
        pair = pairs[idx]
        key_fields = (
            pair[0].get("_map_struct_fields", [])
            if isinstance(pair[0], dict) else [])
        instance_field = _find_field(key_fields, "InstanceId")
        instance_id = None
        if instance_field and isinstance(instance_field.get("value"), dict):
            try:
                instance_id = base64.b64decode(
                    instance_field["value"].get("_raw_b64", ""))
            except Exception:
                instance_id = None
        pairs.pop(idx)
        if instance_id:
            self._remove_palbox_slot_reference(
                instance_id, e.get("slot_index", -1))
            self._update_guild_pal_handle(instance_id, add=False)
        self.pal_field_refs.pop(entry_id, None)
        if e in entries:
            entries.remove(e)
        history.insert(0, {"name": e.get("name", "Pal"), "field": "deleted", "before": f"Box {self.current_box}, Slot {(e.get('slot_index', 0) % BOX_SLOTS) + 1}", "after": "empty"})
        selected_id = entries[0]["id"] if entries else None
        self.render_all()

    def _clone_real_pal_to_empty_slot(self, entry_id):
        global selected_id
        e = get_entry(entry_id)
        if not e or not e.get("is_real_pal"):
            return
        box_entries = self._box_pal_entries()
        try:
            empty_pos = box_entries.index(None)
        except ValueError:
            messagebox.showwarning("Box full", "There are no empty slots in the current box for the cloned pal.")
            return
        pairs, idx = self._character_map_and_pair_index(entry_id)
        if pairs is None:
            messagebox.showerror("Clone failed", "The pal's save record could not be located.")
            return
        key_copy, value_copy = copy.deepcopy(pairs[idx])
        key_fields = key_copy.get("_map_struct_fields", []) if isinstance(key_copy, dict) else []
        instance = _find_field(key_fields, "InstanceId")
        source_instance_id = None
        if instance and isinstance(instance.get("value"), dict):
            try:
                source_instance_id = base64.b64decode(
                    instance["value"].get("_raw_b64", ""))
            except Exception:
                source_instance_id = None
        new_instance_id = _new_palworld_guid_bytes()
        if instance and isinstance(instance.get("value"), dict):
            instance["value"]["_raw_b64"] = base64.b64encode(
                new_instance_id).decode("ascii")
        val_fields = value_copy.get("_map_struct_fields", []) if isinstance(value_copy, dict) else []
        raw = _find_field(val_fields, "RawData")
        decoded = raw.get("value", {}).get("_rawdata_decoded", []) if raw else []
        sp = next((x for x in decoded if x.get("name") == "SaveParameter"), None)
        new_fields = sp.get("value", {}).get("_fields") if sp else None
        if new_fields is None:
            messagebox.showerror("Clone failed", "The pal record is not in an editable format.")
            return
        new_slot_index = (self.current_box - 1) * BOX_SLOTS + empty_pos
        if not self._set_pal_slot_index(new_fields, new_slot_index):
            messagebox.showerror("Clone failed", "The pal's slot information could not be updated.")
            return
        if not self._append_palbox_slot_reference(
                new_instance_id, new_slot_index):
            messagebox.showerror(
                "Clone failed",
                "The Palbox slot record could not be created. No changes were made.")
            return
        if not source_instance_id or not self._update_guild_pal_handle(
                new_instance_id, add=True,
                template_instance_id=source_instance_id):
            self._remove_palbox_slot_reference(
                new_instance_id, new_slot_index)
            messagebox.showerror(
                "Clone failed",
                "The cloned Pal could not be registered to the player's guild. "
                "No changes were made.")
            return
        pairs.append((key_copy, value_copy))
        new_entry = copy.deepcopy(e)
        new_id = max((item["id"] for item in entries), default=0) + 1
        new_entry["id"] = new_id
        new_entry["slot_index"] = new_slot_index
        new_entry["name"] = e.get("name", "Pal")
        entries.append(new_entry)
        self.pal_field_refs[new_id] = new_fields
        selected_id = new_id
        history.insert(0, {"name": new_entry["name"], "field": "cloned", "before": f"Slot {(e.get('slot_index', 0) % BOX_SLOTS) + 1}", "after": f"Slot {empty_pos + 1}"})
        self.render_all()

    def open_pal_picker(self, box_pos):
        if not getattr(self, "_palbox_container_id", None):
            messagebox.showwarning("No Palbox found",
                                   "Couldn't find the Palbox storage container in this save "
                                   "(load a save with an actual Palbox first).")
            return
        # The original built-in catalogue predates several current Pals and
        # contains some obsolete name-to-asset mappings. Merge the verified
        # characters.json supplied with PalworldSaveTools before displaying
        # the picker so Add Pal always writes the game's real CharacterID.
        self._locate_technology_icon_source()
        self._load_docs_pal_source_data()
        win = tk.Toplevel(self)
        win.title("Add Pal")
        win.geometry("560x640")
        win.configure(bg=COLOR["bg1"])
        win.transient(self)
        win.lift()
        win.attributes("-topmost", True)
        win.after(100, win.grab_set)

        tk.Label(win, text=f"Add Pal — Box {self.current_box}, Slot {box_pos + 1}",
                 bg=COLOR["bg1"], fg=COLOR["text0"], font=("Segoe UI", 11, "bold")).pack(
            anchor="w", padx=14, pady=(14, 8))
        search_var = tk.StringVar()
        search_entry = tk.Entry(win, textvariable=search_var, font=FONT_UI, bg=COLOR["bg2"],
                                fg=COLOR["text0"], relief="flat", insertbackground=COLOR["text0"])
        search_entry.pack(fill="x", padx=14, pady=(0, 8), ipady=6)
        search_entry.focus_set()

        list_wrap = tk.Frame(win, bg=COLOR["bg2"], highlightthickness=1,
                             highlightbackground=COLOR["line"])
        list_wrap.pack(fill="both", expand=True, padx=14, pady=(0, 8))
        list_canvas = tk.Canvas(list_wrap, bg=COLOR["bg2"], highlightthickness=0)
        list_scroll = ttk.Scrollbar(list_wrap, orient="vertical")
        list_canvas.pack(side="left", fill="both", expand=True)
        list_scroll.pack(side="right", fill="y")

        picked = {"pal": None}
        candidates = []
        photo_refs = []
        ROW_H = 42
        selected_label = tk.Label(win, text="No pal selected", bg=COLOR["bg1"], fg=COLOR["text2"],
                                  font=("Segoe UI", 9))
        selected_label.pack(anchor="w", padx=14)

        def render_visible(*_):
            list_canvas.delete("vrow")
            photo_refs.clear()
            if not candidates:
                list_canvas.create_text(10, 14, anchor="nw", text="No pals match.",
                                        fill=COLOR["text2"], font=("Segoe UI", 9), tags="vrow")
                return
            top = max(0, int(list_canvas.canvasy(0) // ROW_H))
            count = int(max(1, list_canvas.winfo_height()) // ROW_H) + 3
            width = max(200, list_canvas.winfo_width())
            for idx in range(top, min(len(candidates), top + count)):
                pal = candidates[idx]
                y = idx * ROW_H
                selected = picked["pal"] is not None and picked["pal"]["spawn_id"] == pal["spawn_id"]
                bg = COLOR["accent_dim"] if selected else COLOR["bg2"]
                list_canvas.create_rectangle(0, y, width, y + ROW_H, fill=bg, outline="", tags="vrow")
                photo = self.get_pal_photo(pal["spawn_id"], 28)
                if photo is not None:
                    photo_refs.append(photo)
                    list_canvas.create_image(22, y + ROW_H / 2, image=photo, tags="vrow")
                else:
                    list_canvas.create_text(22, y + ROW_H / 2, text="🐾", fill=COLOR["text0"],
                                            font=("Segoe UI", 12), tags="vrow")
                list_canvas.create_text(44, y + ROW_H / 2, anchor="w", text=pal["name"],
                                        fill=COLOR["accent"] if selected else COLOR["text0"],
                                        font=FONT_UI_BOLD if selected else FONT_UI, tags="vrow")

        def canvas_yview(*args):
            list_canvas.yview(*args)
            render_visible()

        list_scroll.configure(command=canvas_yview)
        list_canvas.configure(yscrollcommand=list_scroll.set)

        def refresh_list(*_):
            query = search_var.get().strip().lower()
            candidates[:] = [
                p for p in wiki_pals
                if p.get("spawn_id")
                and p["spawn_id"] != "—"
                and not str(p["spawn_id"]).upper().startswith(
                    "RAID_YAKUSHIMABOSS002")
                and (not query or query in p["name"].lower())
            ]
            candidates.sort(key=lambda p: p["name"])
            list_canvas.configure(scrollregion=(0, 0, max(1, list_canvas.winfo_width()),
                                                max(1, len(candidates) * ROW_H)))
            list_canvas.yview_moveto(0)
            render_visible()

        def pal_at_event(event):
            idx = int(list_canvas.canvasy(event.y) // ROW_H)
            return candidates[idx] if 0 <= idx < len(candidates) else None

        def pick_event(event):
            pal = pal_at_event(event)
            if pal is None:
                return
            picked["pal"] = pal
            selected_label.configure(text=f"Selected: {pal['name']}", fg=COLOR["text0"])
            render_visible()

        def confirm():
            if picked["pal"] is None:
                messagebox.showwarning("No pal selected", "Pick a pal from the list first.")
                return
            self.spawn_new_pal(picked["pal"]["spawn_id"], box_pos)
            win.destroy()

        def double_pick(event):
            pick_event(event)
            if picked["pal"] is not None:
                confirm()

        def mousewheel(event):
            delta = -1 if event.delta > 0 else 1
            list_canvas.yview_scroll(delta * 3, "units")
            render_visible()
            return "break"

        btn_row = tk.Frame(win, bg=COLOR["bg1"])
        btn_row.pack(fill="x", padx=14, pady=(0, 14))
        tk.Button(btn_row, text="Add Pal", command=confirm, bg=COLOR["accent"], fg="#ffffff",
                  relief="flat", bd=0, padx=14, pady=8, font=("Segoe UI", 9, "bold")).pack(side="left")
        tk.Button(btn_row, text="Cancel", command=win.destroy, bg=COLOR["bg3"], fg=COLOR["text0"],
                  relief="flat", bd=0, padx=14, pady=8).pack(side="left", padx=(8, 0))

        list_canvas.bind("<Button-1>", pick_event)
        list_canvas.bind("<Double-Button-1>", double_pick)
        list_canvas.bind("<MouseWheel>", mousewheel)
        list_canvas.bind("<Configure>", lambda e: render_visible())
        search_entry.bind("<KeyRelease>", lambda e: self._debounce("add_pal_search", refresh_list, 180))
        win.after_idle(refresh_list)

    def spawn_new_pal(self, character_id, box_pos):
        if not getattr(self, "loaded_sav_json", None):
            messagebox.showwarning("No save loaded", "Load a save first.")
            return
        if str(character_id).upper().startswith("RAID_YAKUSHIMABOSS002"):
            messagebox.showerror(
                "Moon Lord cannot be added to a Palbox",
                "Moon Lord is stored by Palworld as a multi-part raid actor, "
                "not as a Pal-compatible character. The game removes its "
                "record when it validates the Palbox.\n\n"
                "There is currently no separate capturable or Palbox-compatible "
                "Moon Lord character ID in the game data.")
            return
        world = next((p for p in self.loaded_sav_json.get("properties", [])
                      if p["name"] == "worldSaveData"), None)
        if not world:
            return
        csm = _find_field(world["value"]["_fields"], "CharacterSaveParameterMap")
        if not csm or "_map" not in csm.get("value", {}):
            messagebox.showwarning("Can't add pal", "This save's CharacterSaveParameterMap "
                                    "isn't in a format this app can add new entries to.")
            return

        slot_index = (self.current_box - 1) * BOX_SLOTS + box_pos
        instance_id = _new_palworld_guid_bytes()
        zero_guid = b"\x00" * 16

        # Start from a real Pal record already accepted by this save. Besides
        # the visible fields, its RawData carries owner/guild metadata and
        # version-specific fields which must be preserved for the game to
        # recognize the new Pal.
        template_pair = None
        for candidate in csm["value"]["_map"]:
            if not isinstance(candidate, (list, tuple)) or len(candidate) != 2:
                continue
            candidate_fields = (
                candidate[1].get("_map_struct_fields", [])
                if isinstance(candidate[1], dict) else [])
            candidate_raw = _find_field(candidate_fields, "RawData")
            candidate_decoded = (
                candidate_raw.get("value", {}).get("_rawdata_decoded", [])
                if candidate_raw else [])
            candidate_sp = next((
                item for item in candidate_decoded
                if item.get("name") == "SaveParameter"), None)
            candidate_pal_fields = (
                candidate_sp.get("value", {}).get("_fields")
                if candidate_sp else None)
            candidate_slot = (
                _find_field(candidate_pal_fields, "SlotId")
                if candidate_pal_fields else None)
            candidate_container_id = None
            if candidate_slot and isinstance(candidate_slot.get("value"), dict):
                slot_fields = candidate_slot["value"].get("_fields", [])
                container = _find_field(slot_fields, "ContainerId")
                if container and isinstance(container.get("value"), dict):
                    container_fields = container["value"].get("_fields", [])
                    container_guid = _find_field(container_fields, "ID")
                    if (container_guid
                            and isinstance(container_guid.get("value"), dict)):
                        candidate_container_id = container_guid["value"].get(
                            "_raw_b64")
            if (candidate_pal_fields
                    and _find_field(candidate_pal_fields, "CharacterID")
                    and candidate_container_id == self._palbox_container_id):
                template_pair = copy.deepcopy(candidate)
                break
        if template_pair is None:
            messagebox.showerror(
                "Can't add pal",
                "No existing Pal owned by this Palbox was found to use as a "
                "save-format template. Put at least one Pal in this Palbox in "
                "game, save, then load that save again.")
            return

        key, value = template_pair
        key_fields = key.get("_map_struct_fields", [])
        player_uid = _find_field(key_fields, "PlayerUId")
        instance = _find_field(key_fields, "InstanceId")
        debug_name = _find_field(key_fields, "DebugName")
        template_instance_id = None
        if instance and isinstance(instance.get("value"), dict):
            try:
                template_instance_id = base64.b64decode(
                    instance["value"].get("_raw_b64", ""))
            except Exception:
                template_instance_id = None
        if player_uid and isinstance(player_uid.get("value"), dict):
            player_uid["value"]["_raw_b64"] = base64.b64encode(
                zero_guid).decode("ascii")
        if not instance or not isinstance(instance.get("value"), dict):
            messagebox.showerror(
                "Can't add pal", "The Pal template has no editable instance ID.")
            return
        instance["value"]["_raw_b64"] = base64.b64encode(
            instance_id).decode("ascii")
        if debug_name is not None:
            debug_name["value"] = ""

        scaling_row = get_pal_scaling(character_id)
        hp_value = int(calculate_max_hp(scaling_row, 1, 0, 0, 0, 1, False)) if scaling_row else 100000
        stomach = float(scaling_row[7]) if scaling_row else 100.0
        value_fields = value.get("_map_struct_fields", [])
        raw_data_field = _find_field(value_fields, "RawData")
        decoded = raw_data_field.get("value", {}).get(
            "_rawdata_decoded", []) if raw_data_field else []
        save_parameter = next((
            item for item in decoded if item.get("name") == "SaveParameter"), None)
        pal_fields = (
            save_parameter.get("value", {}).get("_fields")
            if save_parameter else None)
        if pal_fields is None:
            messagebox.showerror(
                "Can't add pal", "The Pal template is not editable.")
            return

        def set_existing(name, new_value):
            field = _find_field(pal_fields, name)
            if field is not None:
                field["value"] = new_value

        set_existing("CharacterID", character_id)
        set_existing("Gender", "EPalGenderType::Female")
        set_existing("NickName", "")
        set_existing("Level", 1)
        set_existing("Exp", 0)
        set_existing("Rank", 1)
        set_existing("Talent_HP", 50)
        set_existing("Talent_Shot", 50)
        set_existing("Talent_Defense", 50)
        set_existing("Rank_HP", 0)
        set_existing("Rank_Attack", 0)
        set_existing("Rank_Defence", 0)
        set_existing("Rank_CraftSpeed", 0)
        set_existing("FriendshipPoint", 0)
        set_existing("FullStomach", stomach)
        for list_name in ("EquipWaza", "MasteredWaza", "PassiveSkillList"):
            list_field = _find_field(pal_fields, list_name)
            if list_field and isinstance(list_field.get("value"), dict):
                if "_array" in list_field["value"]:
                    list_field["value"]["_array"] = []
                elif "_items" in list_field["value"]:
                    list_field["value"]["_items"] = []
        hp_field = _find_field(pal_fields, "Hp")
        if hp_field and isinstance(hp_field.get("value"), dict):
            hp_inner = _find_field(hp_field["value"].get("_fields", []), "Value")
            if hp_inner is not None:
                hp_inner["value"] = hp_value
        if not self._set_pal_slot_index(pal_fields, slot_index):
            messagebox.showerror(
                "Can't add pal", "The Pal template has no editable slot information.")
            return
        if not self._append_palbox_slot_reference(instance_id, slot_index):
            messagebox.showerror(
                "Can't add pal",
                "The Palbox slot link could not be created. No changes were made.")
            return
        if not template_instance_id or not self._update_guild_pal_handle(
                instance_id, add=True,
                template_instance_id=template_instance_id):
            self._remove_palbox_slot_reference(instance_id, slot_index)
            messagebox.showerror(
                "Can't add pal",
                "The new Pal could not be registered to the player's guild. "
                "No changes were made.")
            return

        csm["value"]["_map"].append((key, value))

        icon, species_name = character_id_display(character_id)
        global entries
        new_id = (max((e["id"] for e in entries), default=0)) + 1
        entries.append({
            "id": new_id, "name": species_name, "icon": icon, "level": 1, "max_level": 255,
            "locked": False, "starred": False, "is_real_pal": True, "character_id": character_id,
            "species_name": species_name, "nickname": "", "gender": "EPalGenderType::Female",
            "exp": 0, "rank": 1, "talent_hp": 50, "talent_shot": 50, "talent_defense": 50,
            "rank_hp": 0, "rank_attack": 0, "rank_defence": 0, "rank_craftspeed": 0,
            "container_id": self._palbox_container_id, "slot_index": slot_index,
        })
        self.pal_field_refs[new_id] = pal_fields
        self.render_box_grid()
        self.select_entry(new_id)

    def _build_detail(self, parent):
        frame = tk.Frame(parent, bg=COLOR["bg1"], width=350,
                          highlightthickness=1, highlightbackground=COLOR["line"])
        frame.pack_propagate(False)

        self.detail_skills_host = tk.Frame(
            frame, bg=COLOR["bg1"], height=174)
        self.detail_skills_host.pack_propagate(False)

        detail_wrap = tk.Frame(frame, bg=COLOR["bg1"])
        detail_wrap.pack(side="top", fill="both", expand=True)
        detail_canvas = tk.Canvas(
            detail_wrap, bg=COLOR["bg1"], highlightthickness=0)
        detail_scroll = ttk.Scrollbar(
            detail_wrap, orient="vertical", command=detail_canvas.yview)
        self.detail_inner = tk.Frame(detail_canvas, bg=COLOR["bg1"])
        detail_window = detail_canvas.create_window(
            (12, 12), window=self.detail_inner, anchor="nw")

        def update_scroll_region(_event=None):
            detail_canvas.configure(scrollregion=detail_canvas.bbox("all"))

        def resize_detail(event):
            detail_canvas.itemconfigure(
                detail_window, width=max(1, event.width - 28))

        self.detail_inner.bind("<Configure>", update_scroll_region)
        detail_canvas.bind("<Configure>", resize_detail)
        detail_canvas.configure(yscrollcommand=detail_scroll.set)
        detail_canvas.pack(side="left", fill="both", expand=True)
        detail_scroll.pack(side="right", fill="y")
        self.detail_canvas = detail_canvas

        def wheel(event):
            if not event.delta:
                return
            amount = -int(event.delta / 120) if abs(event.delta) >= 100 else (
                -1 if event.delta > 0 else 1)
            detail_canvas.yview_scroll(amount, "units")
            return "break"

        detail_canvas.bind("<MouseWheel>", wheel)
        self.detail_inner.bind("<MouseWheel>", wheel)
        return frame

    def render_detail(self):
        for w in self.detail_inner.winfo_children():
            w.destroy()
        for w in self.detail_skills_host.winfo_children():
            w.destroy()
        grid_skills_host = getattr(self, "grid_skills_host", None)
        if grid_skills_host is not None:
            for w in grid_skills_host.winfo_children():
                w.destroy()
        self.detail_skills_host.pack_forget()
        if hasattr(self, "detail_canvas"):
            self.detail_canvas.yview_moveto(0.0)
        e = get_entry(selected_id)
        if not e:
            tk.Label(self.detail_inner, text="Select an entry from the roster\nor box to edit its fields here.",
                     bg=COLOR["bg1"], fg=COLOR["text2"], font=FONT_UI, justify="center").pack(expand=True)
            return

        head = tk.Frame(self.detail_inner, bg=COLOR["bg1"])
        head.pack(fill="x", pady=(0, 14))
        self._render_pal_portrait(e, head)

        if e.get("is_real_pal"):
            self._render_pal_flag_buttons(e, head)

        name_frame = tk.Frame(head, bg=COLOR["bg1"])
        name_frame.pack(side="left", fill="x", expand=True, padx=10)
        self.f_name = tk.Entry(name_frame, font=("Segoe UI", 12, "bold"),
                                bg=COLOR["bg1"], fg=COLOR["text0"], relief="flat",
                                insertbackground=COLOR["text0"])
        self.f_name.insert(0, e["name"])
        self.f_name.pack(fill="x")
        sub_txt = e.get("species_name", "") if e.get("is_real_pal") else f"ID #{e['id']:04d}"
        tk.Label(name_frame, text=sub_txt, bg=COLOR["bg1"], fg=COLOR["text2"],
                 font=("Segoe UI", 8)).pack(anchor="w", pady=(2, 0))

        def field_row(label, widget_builder):
            row = tk.Frame(self.detail_inner, bg=COLOR["bg1"])
            row.pack(fill="x", pady=5)
            tk.Frame(row, bg=COLOR["line"], height=1).pack(side="bottom", fill="x", pady=(6, 0))
            tk.Label(row, text=label, bg=COLOR["bg1"], fg=COLOR["text1"], font=FONT_UI).pack(side="left")
            widget_builder(row)

        if e.get("is_real_pal"):
            level_fields = self._pal_fields(e)
            if level_fields is not None:
                self._render_pal_big_level(e, level_fields)

        def build_level(row):
            if e.get("is_real_pal"):
                self.f_level = None
                tk.Button(
                    row, text="Change Level",
                    command=lambda: self._open_pal_value_editor(
                        e, "Level", "level", "Level", 1,
                        255 if self.pal_cheat_mode else e["max_level"],
                        "ByteProperty"),
                    bg=COLOR["bg3"], fg=COLOR["accent"],
                    activebackground=COLOR["accent_dim"],
                    activeforeground=COLOR["text0"], relief="flat", bd=0,
                    font=("Segoe UI", 8, "bold"), padx=11, pady=5,
                    cursor="hand2", highlightthickness=1,
                    highlightbackground=COLOR["line_strong"],
                ).pack(side="right")
                return
            self.f_level = tk.Spinbox(row, from_=1, to=e["max_level"], width=8,
                                       justify="right", font=FONT_MONO)
            self.f_level.delete(0, "end")
            self.f_level.insert(0, str(e["level"]))
            self.entry_style(self.f_level)
            self.f_level.pack(side="right")
        field_row("Level", build_level)

        if e.get("is_real_pal"):
            self._render_real_pal_fields(e, field_row)
        else:
            self._render_sample_stat_fields(e, field_row)

        badge_row = tk.Frame(self.detail_inner, bg=COLOR["bg1"])
        badge_row.pack(fill="x", pady=(14, 0))
        b1 = tk.Label(badge_row, text=("\u2605 Boss/Gym" if e["starred"] else "Standard"),
                      bg=COLOR["bg1"], fg=COLOR["gold"] if e["starred"] else COLOR["text1"],
                      font=("Segoe UI", 8), highlightthickness=1,
                      highlightbackground=COLOR["gold"] if e["starred"] else COLOR["line_strong"],
                      padx=8, pady=3)
        b1.pack(side="left", padx=(0, 6))
        if e.get("is_real_pal"):
            b2 = tk.Label(badge_row, text="From loaded save", bg=COLOR["bg1"], fg=COLOR["accent"],
                          font=("Segoe UI", 8), highlightthickness=1,
                          highlightbackground=COLOR["accent"], padx=8, pady=3)
        else:
            b2 = tk.Label(badge_row, text=("Protected" if e["locked"] else "Editable"),
                          bg=COLOR["bg1"], fg=COLOR["text1"], font=("Segoe UI", 8),
                          highlightthickness=1, highlightbackground=COLOR["line_strong"], padx=8, pady=3)
        b2.pack(side="left")

        action_row = tk.Frame(self.detail_inner, bg=COLOR["bg1"])
        action_row.pack(fill="x", pady=(16, 0))

        def action_btn(parent, label, cmd, kind="normal"):
            fg = COLOR["text0"]
            bg = COLOR["bg3"]
            if kind == "primary":
                bg = COLOR["accent"]
                fg = "#ffffff"
            b = tk.Button(parent, text=label, command=cmd, bg=bg, fg=fg,
                          activebackground=bg, relief="flat", bd=0, font=("Segoe UI", 9, "bold"), pady=7)
            return b

        action_btn(action_row, "Apply changes", lambda: self.apply_changes(e), "primary").pack(
            side="left", fill="x", expand=True, padx=(0, 4))
        action_btn(action_row, "Clone", lambda: self.clone_entry(e)).pack(
            side="left", fill="x", expand=True, padx=4)
        action_btn(action_row, "Delete", lambda: self.delete_entry(e)).pack(
            side="left", fill="x", expand=True, padx=(4, 0))

    def _render_sample_stat_fields(self, e, field_row):
        self.f_locked = tk.BooleanVar(value=e["locked"])
        def build_locked(row):
            ttk.Checkbutton(row, variable=self.f_locked, style="Dark.TCheckbutton").pack(side="right")
        field_row("Locked", build_locked)

        self.f_starred = tk.BooleanVar(value=e["starred"])
        def build_starred(row):
            ttk.Checkbutton(row, variable=self.f_starred, style="Dark.TCheckbutton").pack(side="right")
        field_row("Starred", build_starred)

        stat_title = tk.Label(self.detail_inner, text="STATS", bg=COLOR["bg1"], fg=COLOR["text2"],
                               font=("Segoe UI", 8, "bold"))
        stat_title.pack(anchor="w", pady=(14, 6))

        self.stat_vars = {}
        stat_colors = {"hp": COLOR["danger"], "atk": COLOR["warn"], "def": COLOR["accent"], "spd": COLOR["good"]}
        stat_labels = {"hp": "HP", "atk": "Attack", "def": "Defense", "spd": "Speed"}
        for key in ("hp", "atk", "def", "spd"):
            line = tk.Frame(self.detail_inner, bg=COLOR["bg1"])
            line.pack(fill="x", pady=3)
            tk.Label(line, text=stat_labels[key], bg=COLOR["bg1"], fg=COLOR["text1"],
                     font=("Segoe UI", 9), width=8, anchor="w").pack(side="left")

            track = tk.Frame(line, bg=COLOR["bg3"], height=8)
            track.pack(side="left", fill="x", expand=True, padx=6)
            pct = min(1.0, e[key] / STAT_MAX[key])
            fill = tk.Frame(track, bg=stat_colors[key], height=8)
            fill.place(relx=0, rely=0, relwidth=max(pct, 0.01), relheight=1)

            var = tk.StringVar(value=str(e[key]))
            self.stat_vars[key] = var
            val_entry = tk.Entry(line, textvariable=var, width=6, justify="right",
                                  bg=COLOR["bg1"], fg=COLOR["text0"], relief="flat",
                                  font=FONT_MONO, insertbackground=COLOR["text0"])
            val_entry.pack(side="right")

    _PAL_ID_PREFIXES = ("BOSS_", "PREDATOR_", "GYM_", "RAID_", "POLICE_", "SUMMON_", "QUEST_")

    def _pal_fields(self, e):
        return self.pal_field_refs.get(e["id"])

    def _pal_field_value(self, fields, name, default=None):
        f = _find_field(fields, name)
        if f is None or isinstance(f["value"], dict):
            return default
        return f["value"]

    def _pal_set_field(self, fields, name, prop_type, value):
        extra = (
            {"bool_value": 1 if bool(value) else 0}
            if prop_type == "BoolProperty" else {}
        )
        f = _find_field(fields, name)
        if f is not None:
            f["type"] = prop_type
            f["extra"] = extra
            f["value"] = value
        else:
            fields.append({
                "name": name, "type": prop_type,
                "extra": extra, "value": value,
            })

    def _pal_strip_id_prefix(self, cid):
        upper = cid.upper()
        for pfx in self._PAL_ID_PREFIXES:
            if upper.startswith(pfx):
                return cid[len(pfx):]
        return cid

    def _render_pal_portrait(self, e, parent):
        size = 64
        wrap = tk.Frame(parent, bg=COLOR["bg1"], width=size, height=size)
        wrap.pack(side="left")
        wrap.pack_propagate(False)

        fields = self._pal_fields(e) if e.get("is_real_pal") else None
        ring_color = None
        if fields is not None:
            cid = self._pal_field_value(fields, "CharacterID", "") or ""
            if cid.upper().startswith("BOSS_") or self._pal_field_value(fields, "IsRarePal", False):
                ring_color = COLOR["gold"]
            elif self._pal_field_value(fields, "bIsAwakening", False):
                ring_color = COLOR["danger"]

        head_spawn_id = e.get("character_id")
        photo = self.get_circular_pal_photo(head_spawn_id, size, ring_color) if head_spawn_id else None
        if photo:
            portrait_lbl = tk.Label(wrap, image=photo, bg=COLOR["bg1"], bd=0)
            portrait_lbl.image = photo
        else:
            portrait_lbl = tk.Label(wrap, text=e["icon"], bg=COLOR["bg3"], fg=COLOR["text0"],
                                     font=("Segoe UI", 22), width=3, height=1)
        portrait_lbl.place(relx=0.5, rely=0.5, anchor="center")

        if fields is not None:
            def badge(text, corner, fg):
                lbl = tk.Label(wrap, text=text, bg=COLOR["bg0"], fg=fg,
                               font=("Segoe UI", 7), width=2, height=1)
                positions = {
                    "tl": (0.02, 0.02, "nw"), "tr": (0.98, 0.02, "ne"),
                    "bl": (0.02, 0.98, "sw"), "br": (0.98, 0.98, "se"),
                }
                rx, ry, anchor = positions[corner]
                lbl.place(relx=rx, rely=ry, anchor=anchor)

            cid = self._pal_field_value(fields, "CharacterID", "") or ""
            if cid.upper().startswith("BOSS_"):
                badge("\U0001F451", "tl", COLOR["gold"])
            elif self._pal_field_value(fields, "IsRarePal", False):
                badge("\u2b50", "tl", COLOR["gold"])
            if cid.upper().startswith("PREDATOR_"):
                badge("\U0001F47F", "tr", COLOR["danger"])
            if int(self._pal_field_value(fields, "FavoriteIndex", 0) or 0) > 0:
                badge("\U0001F512", "tr", COLOR["text0"])
            if self._pal_field_value(fields, "bIsAwakening", False):
                badge("\U0001F525", "br", COLOR["danger"])
            if self._pal_field_value(fields, "bImportedCharacter", False):
                badge("\U0001F9EC", "bl", COLOR["accent"])

    @staticmethod
    def _passive_rank_style(rank):
        try:
            rank = int(rank)
        except (TypeError, ValueError):
            rank = 1
        if rank <= 0:
            return "#5C1515", "#FF5555", "Negative"
        if rank >= 4:
            return "#0D3B66", "#7DD3FC", "Epic"
        if rank >= 2:
            return "#5C4033", "#FFD700", "Rare"
        return "#343442", "#FFFFFF", "Common"

    def _pal_passive_source(self):
        if hasattr(self, "_pal_passive_source_cache"):
            return self._pal_passive_source_cache
        rows = self._load_source_game_json("skills.json").get("passives", [])
        self._pal_passive_source_cache = {
            str(row.get("asset") or "").casefold(): row
            for row in rows if isinstance(row, dict) and row.get("asset")
        }
        return self._pal_passive_source_cache

    @staticmethod
    def _format_pal_passive_description(info):
        text = str(info.get("description") or "")
        text = text.replace("{CharacterName}", "Pal")
        for index in range(1, 5):
            value = info.get(f"effect{index}", 0)
            if isinstance(value, float) and value.is_integer():
                value_text = str(int(value))
            else:
                value_text = str(value)
            text = text.replace(f"{{EffectValue{index}}}", value_text)
        return re.sub(r"\s+", " ", text).strip()

    @staticmethod
    def _active_skill_element_style(element_name):
        symbols = {
            "Normal": "\u25c8", "Fire": "\u2666",
            "Water": "\u25c9", "Electricity": "\u2726",
            "Leaf": "\u2748", "Ice": "\u2744",
            "Earth": "\u25c6", "Dark": "\u25c7",
            "Dragon": "\u2725",
        }
        colors = {
            "Normal": COLOR["text1"], "Fire": COLOR["danger"],
            "Water": "#4fd1e0", "Electricity": COLOR["warn"],
            "Leaf": COLOR["good"], "Ice": COLOR["accent"],
            "Earth": "#d49a5b", "Dark": "#c56bd6",
            "Dragon": "#ec79d7",
        }
        return (
            symbols.get(str(element_name or ""), "\u25c7"),
            colors.get(str(element_name or ""), COLOR["accent"]))

    def _open_pal_active_picker(self, variable, anchor, selected_ids):
        none_label = "\u2014 (none) \u2014"
        popup = tk.Toplevel(self)
        popup.withdraw()
        popup.overrideredirect(True)
        popup.configure(bg=COLOR["line_strong"])
        popup.transient(self)

        self.update_idletasks()
        popup.update_idletasks()
        width, height = 390, 430
        main_x = self.winfo_rootx()
        main_y = self.winfo_rooty()
        main_width = max(self.winfo_width(), self.winfo_screenwidth())
        main_height = max(self.winfo_height(), self.winfo_screenheight())
        x = main_x + (main_width - width) // 2
        y = main_y + (main_height - height) // 2
        popup.geometry(f"{width}x{height}+{x}+{y}")
        popup.update_idletasks()
        popup.deiconify()
        popup.lift()
        popup.grab_set()

        shell = tk.Frame(
            popup, bg=COLOR["bg1"], highlightthickness=1,
            highlightbackground=COLOR["line_strong"])
        shell.pack(fill="both", expand=True, padx=1, pady=1)
        search_var = tk.StringVar()
        search = tk.Entry(
            shell, textvariable=search_var, bg=COLOR["bg2"],
            fg=COLOR["text0"], insertbackground=COLOR["text0"],
            relief="flat", font=("Segoe UI", 9),
            highlightthickness=1, highlightbackground=COLOR["line_strong"])
        search.pack(fill="x", padx=5, pady=5, ipady=5)
        search.focus_set()

        list_wrap = tk.Frame(shell, bg=COLOR["bg1"])
        list_wrap.pack(fill="both", expand=True, padx=5, pady=(0, 5))
        canvas = tk.Canvas(
            list_wrap, bg=COLOR["bg1"], highlightthickness=0)
        scrollbar = ttk.Scrollbar(
            list_wrap, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        rows = []
        photo_refs = []
        row_height = 29

        def refresh(*_args):
            query = search_var.get().strip().casefold()
            rows[:] = [(None, none_label, "", "")]
            matches = []
            for skill_id, data in ACTIVE_SKILL_DATA.items():
                name, element, power, _cooldown = data
                if (not query or query in str(name).casefold()
                        or query in str(skill_id).casefold()
                        or query in str(element).casefold()):
                    matches.append((skill_id, name, element, power))
            matches.sort(key=lambda item: str(item[1]).casefold())
            rows.extend(matches)
            canvas.configure(
                scrollregion=(0, 0, max(1, canvas.winfo_width()),
                              max(1, len(rows) * row_height)))
            canvas.yview_moveto(0.0)
            render_visible()

        def render_visible(*_args):
            canvas.delete("active_picker_row")
            photo_refs.clear()
            if not rows:
                return
            first = max(0, int(canvas.canvasy(0) // row_height))
            visible_count = max(
                1, int(canvas.winfo_height() // row_height) + 2)
            canvas_width = max(250, canvas.winfo_width())
            for index in range(first, min(len(rows), first + visible_count)):
                skill_id, name, element, power = rows[index]
                y0 = index * row_height
                selected_elsewhere = (
                    skill_id is not None
                    and str(skill_id).casefold() in selected_ids)
                bg = COLOR["bg2"] if index % 2 == 0 else COLOR["bg1"]
                canvas.create_rectangle(
                    0, y0, canvas_width, y0 + row_height,
                    fill=bg, outline=COLOR["line"], width=1,
                    tags=("active_picker_row", f"active_row_{index}"))
                display_name = "-- clear --" if skill_id is None else name
                canvas.create_text(
                    8, y0 + row_height / 2, text=display_name,
                    anchor="w",
                    fill=COLOR["text2"] if selected_elsewhere
                    else COLOR["text0"],
                    font=("Segoe UI", 9),
                    tags=("active_picker_row", f"active_row_{index}"))
                if skill_id is not None:
                    symbol, color = self._active_skill_element_style(element)
                    canvas.create_text(
                        canvas_width - 55, y0 + row_height / 2,
                        text=symbol, anchor="center", fill=color,
                        font=("Segoe UI Symbol", 10, "bold"),
                        tags=("active_picker_row", f"active_row_{index}"))
                    canvas.create_text(
                        canvas_width - 8, y0 + row_height / 2,
                        text=str(power), anchor="e", fill=COLOR["warn"],
                        font=("Consolas", 9, "bold"),
                        tags=("active_picker_row", f"active_row_{index}"))

        def choose(event):
            index = int(canvas.canvasy(event.y) // row_height)
            if not (0 <= index < len(rows)):
                return
            skill_id, name, _element, _power = rows[index]
            variable.set(name if skill_id is not None else none_label)
            popup.destroy()

        def mousewheel(event):
            amount = -int(event.delta / 120) if abs(event.delta) >= 100 else (
                -1 if event.delta > 0 else 1)
            canvas.yview_scroll(amount, "units")
            render_visible()
            return "break"

        def canvas_yview(*args):
            canvas.yview(*args)
            render_visible()

        scrollbar.configure(command=canvas_yview)
        search_var.trace_add("write", refresh)
        canvas.bind("<ButtonRelease-1>", choose)
        canvas.bind("<MouseWheel>", mousewheel)
        canvas.bind("<Configure>", render_visible)
        popup.bind("<Escape>", lambda _event: popup.destroy())
        refresh()

    def _open_pal_passive_picker(self, variable, anchor, selected_ids):
        source = self._pal_passive_source()
        none_label = "\u2014 (none) \u2014"
        popup = tk.Toplevel(self)
        popup.title("Select a Passive Skill")
        popup.geometry("500x520")
        popup.configure(bg=COLOR["bg0"])
