def _log_diag(self,operation,stage,exc=None,severity="warning",property_path="",message=""):
    row={"timestamp":datetime.datetime.now().isoformat(timespec="seconds"),"operation":operation,
         "save_path":getattr(self,"loaded_sav_path",None) or getattr(self,"loaded_save_path",None) or "",
         "parser_stage":stage,"property_path":property_path,"severity":severity,
         "exception_type":type(exc).__name__ if exc else "","message":message or (str(exc) if exc else ""),
         "traceback":"".join(traceback.format_exception(type(exc),exc,exc.__traceback__)) if exc else ""}
    self.diagnostics.append(row); self.diagnostics=self.diagnostics[-500:]
SaveEditorApp.log_diagnostic=_log_diag


def _validation_text(report):
    lines=[f"CRITICAL ERRORS: {len(report.errors)}",f"WARNINGS: {len(report.warnings)}",""]
    for title,items in (("ERRORS",report.errors),("WARNINGS",report.warnings),("INFO",report.info)):
        lines.append(title)
        lines.append("-"*len(title))
        for x in items: lines.append(f"[{x.code}] {x.message}"+(f"\n  Path: {x.path}" if x.path else ""))
        lines.append("")
    return "\n".join(lines)


def _validate_current(self,show=True):
    obj=getattr(self,"loaded_sav_json",None)
    if obj is None:
        obj=getattr(self,"json_editor_data",None)
    if obj is None:
        if show: messagebox.showwarning("No save loaded","Load a save or valid JSON first.")
        return SaveValidationReport()
    rebuilt=None
    try: rebuilt=json_dict_to_gvas_bytes(obj)
    except Exception as exc:
        report=SaveValidationReport(); report.add("error","REBUILD_FAILED",f"{type(exc).__name__}: {exc}","$")
        self.log_diagnostic("Validate","GVAS rebuild",exc,"critical")
        if show:self._show_report_window(report)
        return report
    report=validate_save_json(obj,rebuilt)
    if show:self._show_report_window(report)
    return report
