def _selected_slot_payload(self):
    ci = getattr(self, "inventory_selected_container", None)
    si = getattr(self, "inventory_selected_slot", None)
    if ci is None or si is None:
        return None

    raw_field = getattr(self, "inventory_slot_refs", {}).get((ci, si))
    raw_value = raw_field.get("value") if isinstance(raw_field, dict) else None
    slot_bytes = _item_slot_raw_bytes(raw_value)
    decoded = decode_item_slot_bytes(slot_bytes) if slot_bytes else None

    container = next(
        (c for c in getattr(self, "inventory_containers", [])
         if c.get("index") == ci),
        None,
    )
    displayed_slot = next(
        (s for s in (container or {}).get("slots", [])
         if s.get("slot_index") == si),
        None,
    )

    slot_struct = None
    obj = getattr(self, "loaded_sav_json", None)
    if obj is not None and raw_field is not None:
        for _path, node in _safe_walk(obj):
            if isinstance(node, dict) and node.get("_struct") == "PalItemSlotSaveData":
                if _field_map(node).get("RawData") is raw_field:
                    slot_struct = node
                    break

    dynamic_uuid = _dynamic_id_from_slot_bytes(slot_bytes)
    dynamic_record = None
    if dynamic_uuid and obj is not None:
        target = dynamic_uuid.lower()
        for record in _dynamic_items_array(obj) or []:
            if (_dynamic_record_id(record) or "").lower() == target:
                dynamic_record = record
                break

    dynamic_bytes = b""
    if dynamic_record:
        dynamic_raw_field = _field_map(dynamic_record).get("RawData")
        if dynamic_raw_field:
            dynamic_bytes = _item_slot_raw_bytes(dynamic_raw_field.get("value")) or b""

    details = {
        "item_id": (
            decoded.get("item_id") if decoded
            else (displayed_slot or {}).get("item_id")
        ),
        "count": (
            decoded.get("count") if decoded
            else (displayed_slot or {}).get("count")
        ),
        "slot_index": decoded.get("marker") if decoded else si,
        "dynamic_uuid": dynamic_uuid,
        "tail_b64": decoded.get("tail_b64") if decoded else None,
    }
    return {
        "container_index": ci,
        "slot_index": si,
        "slot": slot_struct,
        "raw": raw_field,
        "details": details,
        "dynamic_record": dynamic_record,
        "slot_bytes": slot_bytes or b"",
        "dynamic_bytes": dynamic_bytes,
    }
SaveEditorApp._selected_slot_payload=_selected_slot_payload


def _decode_dynamic_record_bytes(blob, fallback_item_id=None):
    """Decode the dynamic-item layout that this editor reads and writes."""
    blob = bytes(blob or b"")
    result = {
        "Dynamic record size": len(blob),
        "Dynamic item type": "unknown",
    }
    if len(blob) < 32:
        result["Decode status"] = "Record is shorter than the 32-byte GUID header."
        return result

    result["Header GUID"] = _guid_from_pal_bytes(blob[:16]) or "00000000-0000-0000-0000-000000000000"
    result["Record dynamic UUID"] = _guid_from_pal_bytes(blob[16:32]) or "00000000-0000-0000-0000-000000000000"
    cursor = 32

    if cursor + 4 > len(blob):
        result["Decode status"] = "Item ID length is missing."
        return result
    text_length = struct.unpack_from("<i", blob, cursor)[0]
    cursor += 4
    item_id = fallback_item_id
    try:
        if text_length > 0 and cursor + text_length <= len(blob):
            item_id = blob[cursor:cursor + max(0, text_length - 1)].decode("utf-8", "replace")
            cursor += text_length
        elif text_length < 0:
            byte_length = -text_length * 2
            if cursor + byte_length <= len(blob):
                item_id = blob[cursor:cursor + max(0, byte_length - 2)].decode("utf-16-le", "replace")
                cursor += byte_length
    except (UnicodeDecodeError, ValueError):
        pass

    result["Dynamic record item ID"] = item_id or "Unknown"
    metadata = get_dynamic_item_metadata(item_id or fallback_item_id or "")
    item_type = metadata.get("type", "unknown")
    result["Dynamic item type"] = item_type
    if metadata:
        for key, value in metadata.items():
            if key != "type":
                result[f"Metadata: {key.replace('_', ' ').title()}"] = value

    if cursor + 4 <= len(blob):
        result["Unknown header value"] = struct.unpack_from("<I", blob, cursor)[0]
        cursor += 4
    if cursor + 4 <= len(blob):
        result["Current durability"] = struct.unpack_from("<f", blob, cursor)[0]
        cursor += 4
    if item_type == "weapon":
        if cursor + 4 <= len(blob):
            result["Remaining ammunition"] = struct.unpack_from("<i", blob, cursor)[0]
            cursor += 4
        if cursor + 4 <= len(blob):
            result["Passive skill count"] = struct.unpack_from("<I", blob, cursor)[0]
            cursor += 4

    result["Decoded bytes"] = cursor
    result["Undecoded trailing bytes"] = max(0, len(blob) - cursor)
    if cursor < len(blob):
        result["Trailing data (hex)"] = blob[cursor:].hex(" ")
    result["Decode status"] = "Decoded known fields; remaining bytes are preserved verbatim."
    return result


def _show_dynamic_inspector(self):
    payload=self._selected_slot_payload()
    if not payload:
        messagebox.showinfo("Dynamic Item Inspector","Select an inventory slot first."); return
    win=tk.Toplevel(self); win.title("Dynamic Item Inspector"); win.geometry("1100x760"); win.configure(bg=COLOR["bg0"])
    nb=ttk.Notebook(win); nb.pack(fill="both",expand=True,padx=10,pady=10)
    summary=tk.Frame(nb,bg=COLOR["bg1"]); rawtab=tk.Frame(nb,bg=COLOR["bg1"]); hextab=tk.Frame(nb,bg=COLOR["bg1"]); scantab=tk.Frame(nb,bg=COLOR["bg1"])
    nb.add(summary,text="Fields"); nb.add(rawtab,text="Raw JSON"); nb.add(hextab,text="Hex View"); nb.add(scantab,text="Unknown Scanner")
    d=payload["details"]
    slot_fields = _field_map(payload["slot"])
    custom_value = _unwrap_field_value(slot_fields.get("CustomVersionData"))
    custom_bytes = _extract_raw_bytes(custom_value)
    rows=[("Item/static ID",d.get("item_id")),("Container index",payload["container_index"]),("Slot index",payload["slot_index"]),("Stack count",d.get("count")),("Dynamic UUID",d.get("dynamic_uuid")),("Matching dynamic record","Yes" if payload["dynamic_record"] else "No"),("CustomVersionData","Present" if slot_fields.get("CustomVersionData") else "Missing"),("CustomVersionData size",len(custom_bytes)),("Slot raw-data size",len(payload["slot_bytes"]))]
    if payload["dynamic_record"]:
        rows.append(("Dynamic raw-data size",len(payload["dynamic_bytes"])))
        rows.extend(_decode_dynamic_record_bytes(payload["dynamic_bytes"],d.get("item_id")).items())
        dynamic_fields = _field_map(payload["dynamic_record"])
        rows.append(("Dynamic record fields",", ".join(dynamic_fields) or "None"))
    for r,(k,v) in enumerate(rows):
        tk.Label(summary,text=k,bg=COLOR["bg1"],fg=COLOR["text2"],anchor="w",font=FONT_UI_BOLD).grid(row=r,column=0,sticky="w",padx=12,pady=5)
        e=tk.Entry(
            summary,
            bg=COLOR["bg2"],
            fg=COLOR["text0"],
            readonlybackground=COLOR["bg2"],
            disabledbackground=COLOR["bg2"],
            disabledforeground=COLOR["text0"],
            selectbackground=COLOR["accent"],
            selectforeground="#ffffff",
            insertbackground=COLOR["text0"],
            relief="flat",
            highlightthickness=1,
            highlightbackground=COLOR["line"],
            font=FONT_MONO,
            width=80,
        )
        e.grid(row=r,column=1,sticky="ew",padx=12,pady=5)
        e.insert(0,"" if v is None else str(v))
        e.configure(state="readonly")
    summary.grid_columnconfigure(1,weight=1)
    import pprint
    raw_text=pprint.pformat({"slot":payload["slot"],"raw":payload["raw"],"dynamic_record":payload["dynamic_record"]},width=140,sort_dicts=False)
    t=tk.Text(rawtab,bg=COLOR["bg2"],fg=COLOR["text0"],font=FONT_MONO,wrap="none"); t.pack(fill="both",expand=True); t.insert("1.0",raw_text)
    dynbytes=payload["dynamic_bytes"]; slotbytes=payload["slot_bytes"]
    h=tk.Text(hextab,bg=COLOR["bg2"],fg=COLOR["text0"],font=FONT_MONO,wrap="none"); h.pack(fill="both",expand=True); h.insert("1.0","DYNAMIC RECORD BYTES\n"+_hex_dump(dynbytes)+"\n\nSLOT RAW BYTES\n"+_hex_dump(slotbytes))
    controls=tk.Frame(scantab,bg=COLOR["bg1"]); controls.pack(fill="x",padx=8,pady=8)
    target=tk.StringVar(); tk.Label(controls,text="Target number (optional):",bg=COLOR["bg1"],fg=COLOR["text1"]).pack(side="left"); tk.Entry(controls,textvariable=target,width=16).pack(side="left",padx=5)
    out=tk.Text(scantab,bg=COLOR["bg2"],fg=COLOR["text0"],font=FONT_MONO,wrap="none"); out.pack(fill="both",expand=True,padx=8,pady=8)
    def runscan():
        try: tv=float(target.get()) if target.get().strip() else None
        except ValueError: messagebox.showerror("Invalid target","Enter a number."); return
        rows=scan_unknown_blob(dynbytes or slotbytes,target=tv)
        out.delete("1.0","end"); out.insert("1.0",json.dumps(rows[:10000],indent=2,default=str))
    tk.Button(controls,text="Scan",command=runscan,bg=COLOR["accent_dim"],fg=COLOR["accent"],relief="flat").pack(side="left",padx=5)
    tk.Button(controls,text="Copy selected tab",command=lambda:self.clipboard_append(nb.select()),bg=COLOR["bg3"],fg=COLOR["text1"],relief="flat").pack(side="left")
SaveEditorApp.show_dynamic_inspector=_show_dynamic_inspector


