SaveEditorApp.json_editor_export_sav=_safe_json_export


_old_context=SaveEditorApp._show_slot_context_menu
def _new_context(self,event,container_index,slot_index,is_empty):
    menu=tk.Menu(self,tearoff=0,bg=COLOR["bg2"],fg=COLOR["text0"],activebackground=COLOR["accent"],activeforeground="#fff",relief="flat",bd=0)
    if is_empty:
        menu.add_command(label="Add Item...",command=lambda:self.after(50,lambda:self.open_item_picker(container_index,slot_index)))
        if self.inventory_clipboard:
            menu.add_command(label="Paste copied item",command=lambda:self._paste_inventory_slot(container_index,slot_index))
    else:
        menu.add_command(label="Edit Item...",command=lambda:self._select_inventory_slot(container_index,slot_index))
        menu.add_command(label="Inspect dynamic/raw data",command=lambda:(self._select_inventory_slot(container_index,slot_index),self.show_dynamic_inspector()))
        menu.add_command(label="Copy item",command=lambda:self._copy_inventory_slot(container_index,slot_index))
        menu.add_command(label="Replace With...",command=lambda:self.after(50,lambda:self.open_item_picker(container_index,slot_index)))
        menu.add_separator(); menu.add_command(label="Delete item",command=lambda:self.apply_inventory_edit(container_index,slot_index,"","0"))
    try:menu.tk_popup(event.x_root,event.y_root)
    finally:menu.grab_release()
SaveEditorApp._show_slot_context_menu=_new_context


def _copy_slot(self,ci,si):
    import copy
    field=self.inventory_slot_refs.get((ci,si))
    if field is None:return
    self.inventory_clipboard=copy.deepcopy(field)
    messagebox.showinfo("Copied","The slot RawData was copied in memory. Dynamic items are not duplicated because UUIDs must remain unique; paste is limited to static/stackable items.")
SaveEditorApp._copy_inventory_slot=_copy_slot


def _paste_slot(self,ci,si):
    import copy
    src=self.inventory_clipboard
    if not src:return
    raw=_unwrap_field_value(src); d=_slot_details_from_raw(raw) if isinstance(raw,dict) else {}
    guid=d.get("dynamic_uuid")
    if guid and guid!="00000000-0000-0000-0000-000000000000":
        messagebox.showwarning("Dynamic paste blocked","Dynamic items cannot share a UUID. Use Add Item to create a new dynamic record safely."); return
    dest=self.inventory_slot_refs.get((ci,si))
    if dest is None:
        messagebox.showwarning("Paste unavailable","This empty slot has no existing RawData reference. Use Add Item so the verified slot creation path also supplies CustomVersionData."); return
    dest.clear(); dest.update(copy.deepcopy(src)); self.render_inventory()
SaveEditorApp._paste_inventory_slot=_paste_slot


if __name__ == "__main__":
    multiprocessing.freeze_support()
    try:
        app = SaveEditorApp()
        app.mainloop()
    except Exception:
        startup_error = traceback.format_exc()
        error_path = Path(__file__).with_name(
            "All-In-1_Pal_Editor_startup_error.txt")
        try:
            error_path.write_text(startup_error, encoding="utf-8")
        except OSError:
            pass
        try:
            ctypes.windll.user32.MessageBoxW(
                0,
                "The editor could not start.\n\n"
                f"Error details were saved to:\n{error_path}",
                "All-In-1 Pal Editor - Startup Error",
                0x10,
            )
        except Exception:
            print(startup_error)
